pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: penalize less when item nearly fills the bin
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Perfect fill gets a big reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 3.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        let mut nb = 15.0 + post_residual as f64; // post_residual == capacity here
        // open new bin more willingly early, or when mean residual of open bins is large (fragmented)
        nb -= 10.0 * (1.0 - progress);
        nb += 0.15 * mean_residual;
        nb -= 2.0 * open_bins_count as f64;
        // if next item is large and open bins are fragmented, new bin is attractive
        if next_item_size >= 60 && mean_residual < next_item_size as f64 {
            nb -= 20.0;
        }
        score += nb;
    }

    // Mild preference to fill bins with smaller residuals first (best-fit-like)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals that are too small for any
    // plausible future item (1..=100) are pure waste; penalize heavily.
    // A residual below ~10 is nearly unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead space becomes more costly later in the stream (less time to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * progress;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.6 * open_bins_count as f64;

    // If this bin is the only one that can fit the item, strongly prefer it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and would not fit here, mild penalty for wasting
    // the chance to place it elsewhere.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Mean residual coupling: bins far below mean residual are emptier than
    // average; slightly deprioritize them to keep fills balanced.
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: make the empty bin attractive only when nothing fits
    // well. Baseline moderate score; dead-space penalties on open bins push
    // selection toward a new bin when open bins would create waste.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: reward small post_residual with polynomial decay
    let x = pr / cap; // normalized post-residual in [0,1]
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Penalize large dead space non-linearly (cubic)
    score += 8.0 * x * x * x * (1.0 + 2.0 * progress);

    // Perfect fit bonus (smooth gaussian-like kernel around zero residual)
    score -= 15.0 * (-(x * 12.0) * (-(x * 12.0)));

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (x - nx).abs();
        score -= 10.0 * (-(fit_gap * 8.0) * (-(fit_gap * 8.0)));
        if nx > x {
            score += 6.0 * (nx - x); // next item won't fit: mild penalty
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Mean residual context: prefer bins below mean residual (tighter packing)
    let mr = mean_residual / cap;
    score += 5.0 * (x - mr) * (x - mr);

    // Stream-progress drift: later in stream, be more tolerant of new bins
    score -= 3.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

