pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small to fit typical future
    // items are unusable dead space -> strong penalty.
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            // The smaller (and thus more useless) the gap, the bigger the penalty.
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Reward tight fits generally: prefer bins where item fills a large fraction
    // of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage scattering across many open bins when
    // plenty are already open; encourage consolidation.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: if open bins are on average quite full
    // (low mean residual), opening a new bin is more acceptable; if mean
    // residual is large, prefer filling existing bins.
    score += mean_residual * 0.4;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item would fit in the post-residual, reward this
    // placement (keeps usable space for the future).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space -> mild penalty.
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // moderate fallback. It should win only when all open bins would create
    // severe dead space. Base cost plus pressure from stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheap; later, prefer reuse.
        score = bin_capacity as f64 * 0.9 + progress * 10.0 + (open_bins_count as f64) * 0.3;
        // If the new bin would still leave a large usable residual for the
        // lookahead item, keep it competitive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (C/8 bands)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor() as i32; // 0..7

    // Dead-space penalty: residuals in (0, 10) are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    if next_fits {
        // Harmonic bonus scaled by how "clean" the leftover class is
        score -= 10.0 + (7 - class.min(7)) as f64 * 2.0;
    } else if next_item_size > 0 {
        // Penalize leaving residue that cannot host the next item,
        // worse when residue is small (dead space)
        score += (post_residual.min(30)) as f64 * 0.4;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * (mean_residual / cap);
        score += 60.0 - crowding * 15.0;
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Mildly reward filling existing bins tighter than mean residual
        if (pr < mean_residual) {
            score -= 5.0;
        }
    }

    // Modulo-16 harmonic texture on post_residual: multiples of 16 align with common size classes
    if post_residual % 16 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10 minimum size) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small unusable gap: penalty grows as gap shrinks toward 10.
        score += (20 - post_residual) as f64 * 3.0;
    } else {
        // Larger residuals are more reusable: mild reward.
        score -= (post_residual as f64 - 20.0) * 0.3;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Dead-space coupling: waste relative to residual.
    let waste = (bin_residual - item_size) as f64 / bin_residual as f64;
    score += waste * 15.0;

    // Open-bin pressure: discourage spreading across many open bins;
    // prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when this item would leave
    // a very small gap in existing bins, or when open bins are congested.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 1.2;
        // Perfect-fit lookahead: if next item exactly fills this bin, new bin is great.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 50.0;
        }
        // Late in stream, opening new bins is less costly.
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Lookahead synergy: if post_residual exactly fits next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 30.0; // next item will perfectly consume this bin
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item fits current residual but not post_residual: mild penalty
        // for fragmenting.
        score += 6.0;
    }

    // Mean-residual context: if this bin's post placement is far below mean,
    // it's creating an outlier gap.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Threshold scales with the lookahead item.
    let min_useful = if next_item_size > 0 {
        (next_item_size as f64 * 0.9).min(80.0)
    } else {
        10.0
    };

    if post_residual > 0 && (post_residual as f64) < min_useful {
        // Dead space penalty: quadratic in how far below the useful threshold.
        let gap = min_useful - post_residual as f64;
        score += gap * gap * 0.35;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if (post_residual as f64) >= min_useful {
        // Residual stays reusable for the lookahead item: mild reward.
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless the
    // fit is genuinely good. Scales with fraction of stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(0.6) * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates badly from the mean residual
    // (prefer consistent packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: neutral-ish baseline; only attractive when the best
    // existing option is poor. Give it a moderate default so tight fits in
    // open bins win, but very poor fits trigger a new bin.
    if bin_residual == bin_capacity {
        // New bin: residual after placement = capacity - item_size, usually
        // large, so base score is already high; add a fixed opening cost.
        score += 12.0;
        // If nothing fits well anywhere, make the new bin more attractive.
        if post_residual >= 20 && open_bins_count > 0 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item would fit exactly in the
    // post-residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
