    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: can next item fit into the leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: leftover is reusable by the very next item
            score -= 12.0 + 0.5 * (next_item_size as f64);
            // Harmonic match: leftover class equals next item class
            let next_class = (next_item_size / 10).min(9);
            if next_class as u32 == post_residual / 10 {
                score -= 15.0;
            }
        } else {
            // Leftover cannot host next item: penalize proportionally
            score += 0.35 * (next_item_size as f64 - pr).min(60.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tightest fit (post_residual already does this)
        score += 0.05 * (fitting_bins_count as f64);
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin gives a good harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 55.0;
        // More attractive early in the stream (many items left to use the bin)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Attractive if open bins are all crowded (high mean residual usage)
        score -= 0.15 * (open_bins_count as f64) + 0.1 * (cap - mean_residual);
        // If next item is large, a fresh bin is useful
        if next_item_size >= 50 {
            score -= 8.0;
        }
