    // Lookahead coupling: reward if the next item fits exactly into the post residual,
    // penalize if the next item cannot fit (guaranteed dead space for next step).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chain
        } else if next_item_size < post_residual {
            // partial credit scaled by how well next item uses the leftover
            let use_frac = next_item_size as f64 / post;
            score -= 25.0 * use_frac;
        } else {
            score += 20.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance logic: if this is the only bin that fits the item, prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin gives a tight fit.
        // Make new bins mildly unattractive by default; exact/tight fits elsewhere win.
        score = post as f64 + 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild pressure to consolidate when many bins are open: prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress) * (1.0 - frac);

    // Deviation from mean residual: bins far below mean are "specialists",
    // slightly favor filling them to keep the pool homogeneous.
    score += 0.10 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; residuals below a "useful gap" threshold are heavily penalized.
    let useful_gap = 12.0;
    if (post_residual as f64) < useful_gap {
        // Dead space: penalize proportionally to how close to zero it is.
        score += (useful_gap - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward filling most of the bin: fraction of bin consumed by this placement.
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= fill_fraction * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the empty/new-bin candidate relatively more).
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item can exactly use the post residual, big reward;
    // if the next item cannot fit in post residual but could fit in a fresh bin,
    // slightly penalize hogging this bin.
    if next_item_size > 0 {
        let nr = next_item_size as u32;
        if nr == post_residual {
            score -= 30.0;
        } else if nr <= post_residual {
            score -= 5.0;
        } else if post_residual > 0 && nr > bin_capacity {
            // next item can't fit anywhere fresh either; neutral
        }
    }

    // Mean-residual coupling: when average residual across bins is large,
    // there is slack elsewhere; mildly penalize this bin to spread load.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Stream progression: late in the stream, avoid opening new bins even harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: perfect 2-step match strongly rewarded.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward tightness of the two-step packing.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // Next item does NOT fit after this placement: penalize, scaled by
            // how badly it misses (dead space that blocks the lookahead item).
            let miss = (next_item_size - post_residual) as f64;
            score += 12.0 + 0.6 * miss.min(80.0);
        }
    } else {
        // Last item: just minimize leftover.
        score -= 5.0;
    }

    // Relative-to-mean residual: prefer bins that keep the fleet balanced,
    // but allow deviation when it produces a tight fit.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well anywhere.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // But if the lookahead item exactly fills a fresh bin with the current one... rare.
        if item_size as f64 + next_item_size as f64 >= bin_capacity as f64 && next_item_size > 0 {
            score -= 45.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // Many open bins with high mean residual -> consolidate instead of opening.
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Slight preference for filling larger bins first (best-fit flavor).
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize dead space that no future item can use (items >= 1, but
        // residual smaller than the smallest plausible item is waste).
        if post_residual < 10 {
            score += 15.0;
        }
        // Penalize residuals that only tiny items could fill.
        if post_residual < item_size {
            score += 6.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post residual can't host next item: mild penalty scaled by waste.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when there are open bins
    // that fit, unless the fit in existing bins would be terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, exploring new bins is cheaper; late, expensive.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - t);
        // If mean residual across open bins is high, prefer reusing them.
        score += 0.15 * mean_residual;
    }

    // Prefer filling bins with small residuals first (many-open-bins pressure).
    if open_bins_count > 4 {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * (1.0 + 1.5 * progress * pr_norm - 0.8 * progress * progress);

    // Penalize dead space more as the stream progresses.
    let dead_penalty = pr_norm * pr_norm * (0.5 + 2.0 * progress);

    // Lookahead: reward leaving room for the next item.
    let lookahead = if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n { -0.6 * (1.0 - (n / cap)) * (1.0 - progress) } else { 0.4 * (n / cap) * (1.0 + progress) }
    } else { 0.0 };

    // Last-chance bin: strongly favor using it.
    let last_chance = if fitting_bins_count == 1 { -2.0 } else { 0.0 };

    // New-bin candidate: neutral baseline, slight penalty early to prefer filling open bins.
    let new_bin_bias = if bin_residual == bin_capacity { 0.3 + 0.5 * (1.0 - progress) } else { 0.0 };

    // Mean residual coupling: prefer bins below mean residual (tighter packs).
    let mean_coupling = 0.5 * (pr - mean_residual) / cap;

    let mut score = poly + dead_penalty + lookahead + last_chance + new_bin_bias + mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    // Small residual classes (0..=2) are "dead space" -> penalize; large classes are useful.
    match class {
        0 => score += 18.0,
        1 => score += 9.0,
        2 => score += 4.0,
        3 => score -= 1.5,
        4 => score -= 2.5,
        5 => score -= 3.0,
        _ => score -= 2.0,
    }

    // Exact-fill bonus: harmonic residue zero means perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits too; small reward scaled by how well it fills
            let nxt_class = (post_residual - next_item_size) / 10;
            score -= (3.0 - nxt_class as f64).max(0.0) * 2.0;
        } else {
            // next item cannot use this residual: penalize small residuals more
            if post_residual < next_item_size && post_residual < 25 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual would be tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual < 10 {
            score -= 8.0;
        }
    }

    // New-bin candidate: empty bin gets a baseline cost that scales with how full
    // existing bins are (mean residual). If open bins are loose, opening new bins
    // is cheap-ish; if they are tight, discourage.
    if bin_residual == bin_capacity {
        score += 14.0 - (mean_residual / bin_capacity as f64) * 20.0;
        // early in the stream, opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
        // many open bins -> discourage spreading
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Prefer tighter fits overall: reward small post_residual relative to capacity.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold the minimum item (1)
    // are worthless, but gaps below the *next* item are likely dead too.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual cannot serve the lookahead item -> penalize as dead space
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if post_residual > 0 && post_residual < 10 {
        // tiny unusable sliver
        score += 25.0;
    } else {
        // usable residual: mild reward for larger leftover utility
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening more.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when bin pressure is high
        score += 15.0 + pressure * 10.0;
        // but if the current fit is terrible (huge dead space), new bin is fine
        if post_residual as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        score -= pressure * 2.0;
    }

    // Early in the stream, be slightly more willing to open bins for diversity;
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    } else {
        score += progress * 3.0;
    }

    // Prefer bins whose residual is already tight relative to the fleet mean
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
