pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: prefer tight fits but tolerate larger residuals.
    // Late in the stream: strongly penalize wasted space (higher-order term).
    let progress_sq = progress * progress;
    let progress_cu = progress_sq * progress;
    score += 30.0 * progress * norm_pr * norm_pr;
    score += 55.0 * progress_cu * norm_pr * norm_pr * norm_pr;

    // Smooth quadratic shaping of residual size itself (dead-space curvature).
    score += 0.15 * norm_pr * norm_pr * (1.0 + progress);

    // Reward near-perfect fits smoothly: subtract a bell-shaped bonus around small residuals.
    let fit_bonus = (-norm_pr * norm_pr * 40.0).exp();
    score -= 12.0 * fit_bonus * (1.0 - progress * 0.5);

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack_after_next = pr - nxt;
        if slack_after_next >= 0.0 {
            let tight = 1.0 - (slack_after_next / cap);
            score -= 8.0 * tight * tight * (1.0 - progress * 0.6);
        } else {
            // Next item won't fit: mild smooth penalty scaled by leftover size.
            score += 6.0 * norm_pr * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: smooth reward for using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - progress * 0.4);
    }

    // Slight preference to fill existing bins when many are open (smooth in open count).
    score += 0.05 * (open_bins_count as f64) * norm_pr;

    // Mean residual context: penalize placements that leave residual far above the mean.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: how "reusable" is the leftover space?
    // Class 0: post_residual is a multiple of 25 (very reusable chunks: 0,25,50,75)
    // Class 1: multiple of 10 (common item granularity)
    // Class 2: multiple of 5
    // Class 3: anything else (awkward dead space)
    let pr = post_residual;
    let class = if pr % 25 == 0 { 0 } else if pr % 10 == 0 { 1 } else if pr % 5 == 0 { 2 } else { 3 };

    // Reward bins whose leftover lands in a reusable harmonic class.
    score -= match class {
        0 => 20.0,
        1 => 12.0,
        2 => 6.0,
        _ => 0.0,
    };

    // Perfect fill is king.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the post-residual exactly or partially fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Next item can still fit: reward proportionally, strongly if exact class match.
            score -= 8.0;
            if pr % 10 == next_item_size % 10 {
                score -= 6.0;
            }
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize awkward leftovers that trap the stream.
            let waste = (next_item_size - pr) as f64;
            score += 0.15 * waste;
            if class == 3 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable slivers (< smallest item size 10).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Mild pressure toward tighter bins when many bins are open (fragmentation control).
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // If existing bins are fragmented (high mean residual but poor classes), new bin is fine.
        if mean_residual > 0.45 * bin_capacity as f64 {
            score -= 12.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // Big items (>= half capacity) justify fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose pre-residual was already in a harmonic class (they were built well).
    if bin_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space smaller than the minimum item size
    } else if post_residual < 20 {
        score += 15.0; // risky gap: only tiny items can use it
    }

    // Reward tight fits (low post_residual) with a saturating bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Open-bin pressure: with many bins open, prefer reusing existing bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual,
    // but give it an explicit mild penalty unless the fit would be terrible
    // in every open bin (large item, few fitting bins).
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size > bin_capacity / 2 || (fitting_bins_count <= 1 && bin_residual != bin_capacity) {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if the next item fits in this bin's post_residual,
    // reward chaining placements.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would be blocked by post_residual dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }

    // Early in the stream, be slightly more willing to spread items (keep
    // residuals flexible); later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize this bin if its residual is far below
    // the mean (it is already "used up"); favor bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 150.0 - 3.0 * chain_fit;
        if chain_fit == 0.0 {
            score -= 500.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, worse if tiny.
        score += 80.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Penalize small unusable residuals (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 * (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if next item is large and this item leaves a great match, allow new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Slight preference for consolidating as stream progresses.
    if bin_residual != bin_capacity {
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good; superlinear penalty on waste.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items (1..100 unknown dist):
    // residual after placement below ~10 is nearly unusable.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 10.0; // perfect last-chance swan song
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score -= 12.0; // bin becomes fully dead but was used well
        }
        // If next item is large and this bin can't host it anyway, prefer using
        // this bin for the current item.
        if next_item_size > bin_residual && post_residual < 10 {
            score -= 15.0;
        }
    }

    // Global state: many open bins with slack -> prefer filling existing bins,
    // discourage opening new bins.
    let slack_pressure = mean_residual / bin_capacity as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by aggregate slack.
        score += 40.0 + 60.0 * slack_pressure + 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper; late stream, expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is huge and won't fit any typical residual, new bin is fine.
        if next_item_size > 50 {
            score -= 15.0;
        }
    } else {
        // Filling an existing bin reduces mean residual pressure: reward it.
        score -= 5.0 + 10.0 * slack_pressure;
    }

    // Prefer bins whose residual is close to item size (minimize fragmentation).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * fit_gap * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on tolerate slack, later penalize it
    score += 30.0 * norm_pr * progress * progress;

    // Interaction of post-residual with mean residual of open bins:
    // placing into a bin whose residual is below average is attractive
    score -= 8.0 * norm_pr * (mean_residual / cap - norm_pr).max(0.0);

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 15.0 * scarcity * (1.0 - norm_pr);

    // Lookahead: penalize leaving residual just barely below next item,
    // reward residuals that can still accommodate the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).powf(2.0));
        } else {
            score += 5.0 * ((-gap) / cap).powf(2.0) * 100.0;
        }
    }

    // New-bin candidate: mildly penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
        score += item_size as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes
    let pr = post_residual;
    if pr > 0 {
        // Perfect-fit reward
        score -= 30.0;
        // Small dead space (unusable by typical items) heavily penalized
        if pr < 10 {
            score += 25.0;
        }
        // Classify by residue mod 10 (typical item granularity)
        let r10 = (pr % 10) as f64;
        score += 0.8 * r10;
        // Residue classes divisible by 5 are more reusable
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 10 == 0 { score -= 6.0; }
    }

    // Capacity-fraction thresholds: residual left as fraction of capacity
    let frac = post_residual as f64 / cap;
    if frac < 0.1 {
        score += 20.0; // nearly full bin: good, keep it attractive
    } else if frac < 0.3 {
        score -= 5.0;
    } else if frac > 0.7 {
        score += 10.0; // wasteful placement into large bin
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate: penalize mildly unless open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 15.0 - 25.0 * pressure;
        if open_bins_count == 0 { score -= 50.0; }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0; // marginal gap: only next_item_size <= gap rescues it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else {
        // large residual is reusable: mild reward scaled by fill ratio
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 8.0 * fill;
    }

    // Lookahead coupling: prefer bins whose leftover matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // leftover can't serve next item
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmenting across bins;
    // with few open bins, opening a new one is cheap so avoid bad fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or item is large,
        // unattractive when many bins already open (consolidate instead).
        score -= 20.0 - 0.8 * open_bins_count as f64 + 10.0 * (item_size as f64 / bin_capacity as f64);
        score += 5.0 * progress;
    } else {
        score += 0.05 * pressure * (1.0 - progress);
    }

    // Mean-residual alignment: prefer bins near the mean (balanced packing).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: if the next item fits exactly into the post residual,
    // heavily reward this bin (perfect chain match).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // next item fits, but with leftover slack; reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack * 1.5;
        } else {
            // next item does NOT fit here: penalize creating a gap that wastes the residual
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.2;
        }
    }

    // Penalize small unusable dead space (< 10, minimum item size) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // emptier; placing here keeps balance. Reward if post_residual stays near mean.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (post residual tiny).
    if fitting_bins_count == 1 {
        score -= 40.0;
        if post_residual < 10 {
            score += 50.0; // undo bonus for near-perfect fills? keep small
        }
    }

    // New-bin candidate: residual == capacity. Only attractive when the current
    // item is large and no open bin offers a good fit; discourage by default.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 35.0 };
        score += pressure;
        // if next item is large too, opening a fresh bin is more reasonable
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate conservatism.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Fraction of capacity wasted if we place here.
    let waste_frac = post_residual as f64 / bin_capacity as f64;

    // Strongly penalize large dead space, super-linearly.
    score += 40.0 * waste_frac * waste_frac;

    // Reward tight fits: small post_residual gets a bonus.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item can fit in the post-residual,
    // reward this placement (keeps a good future slot alive is bad — actually
    // placing here and leaving room for next item is good).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual as u32 && next_item_size >= item_size {
            // Next item is big and won't fit here anyway; consuming this bin now is fine.
            score -= 6.0;
        }
        // Penalize leaving a sliver that neither fits next item nor is useful.
        if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin for a fittable item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    // or the open-bin pool is fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let poor_options = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && fragmentation > 20.0);
        if poor_options {
            score -= 18.0 + 10.0 * (1.0 - progress);
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 25.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins that reduce mean residual spread.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * deviation / bin_capacity as f64;

    // Late in the stream, be more greedy about tight fits (less future to plan for).
    score -= 10.0 * progress * (1.0 - waste_frac);

    // Mild penalty for placing into an almost-empty bin when other bins could absorb it.
    if bin_residual == bin_capacity && fitting_bins_count > 3 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    let mut score = pr;

    // Tight-fit reward: quadratic coupling of post_residual with item size.
    let tight = 1.0 - (pr / cap).powi(2);
    score -= 18.0 * tight * (it / cap);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward leaving space close to the next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = ((pr - nx) / cap).abs();
        score -= 12.0 * (1.0 - gap).max(0.0) * (0.5 + 0.5 * progress);
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0 * (1.0 - pr / cap);
    }

    // Penalize bins deviating from mean residual (keep residuals homogeneous),
    // with smooth polynomial weighting by stream progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + progress);

    // Mild penalty for spreading across many bins early on.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let waste = pr / cap; // = 1 for empty bin, but keep generic
        score += 15.0 * (1.0 - waste) + 20.0 * (1.0 - progress) * (fitting_bins_count as f64).min(3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 10 classes of size 10.
    let class = (post_residual / 10) as f64;
    score += class * 2.0; // prefer bins falling into lower (tighter) residual classes

    // Dead space penalty: residual that no plausible item (1..=100) can be
    // "harmonically" paired with. Small residuals (<10) are dead weight.
    if post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward: post residual in a harmonic class that pairs with
    // common item sizes (exact multiples of 5 / 10 are reusable).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item exactly fills the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class after the pair matters
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 {
                score -= 12.0;
            }
            score += post2 as f64 * 0.5;
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist;
    // but if the item is large relative to capacity and fits nowhere tightly,
    // a fresh bin is attractive.
    if bin_residual == bin_capacity {
        // fresh bin: score by wasted space if item placed alone
        score += 20.0 - (item_size as f64);
        if item_size >= 50 {
            score -= 10.0; // big items deserve a fresh bin
        }
        if fitting_bins_count > 0 {
            score += 10.0; // some open bin fits: prefer reusing it
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Mean residual coupling: when open bins are generally loose, tighten
    // selection pressure toward the fullest bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are the worst outcome. Penalize "unusable" gaps aggressively.
    // A gap is unusable if it's smaller than the smallest plausible item (1..100,
    // unknown distribution -> use a conservative threshold around 10).
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else {
        // Reward tight-but-usable fits: quadratic bonus as post_residual shrinks
        // toward the usable band, so near-perfect fills beat loose ones.
        score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * 0.0;
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bins pressure: discourage spreading across many bins; but if this bin
    // is the ONLY fitting bin, strongly favor using it over opening a new one.
    score += (open_bins_count as f64) * 0.8;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual can't host the next item -> mild penalty for wasted gap.
        score += 10.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): neutral baseline.
    // Should win only when all open bins would leave dead space or are bad fits.
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual = capacity - item_size, already in base score.
        // Add fixed offset so it loses to decent fits but beats dead-space makers.
        score += 12.0;
    }

    // Slight preference for filling older (smaller-residual) bins early in stream.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residual too small for any plausible item (min size 1, but tiny slivers < 8 are waste)
    if post_residual > 0 && post_residual < 8 {
        score += 120.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item still fits here: mild reward proportional to slack after that
            let after_next = post_residual - next_item_size;
            score -= 60.0 + after_next as f64 * 0.5;
        } else {
            // next item cannot use the leftover: penalize gap size
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Relative to mean residual: prefer bins with residual close to item need (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += tightness * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 80.0 + open_bins_count as f64 * -2.0;
        // strongly discourage new bin if a perfect/two-step fit exists elsewhere is handled by their low scores
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0; // lookahead suggests bigger item later, keep bins open
        }
    }

    // Stream progression: later in stream, slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0; // likely dead space
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can also go here: great packing chain.
            let chain_waste = post_residual - next_item_size;
            score -= 15.0 - (chain_waste as f64) * 0.2;
        } else if next_item_size <= bin_residual {
            // Next item would have fit here before we consumed space: mild penalty.
            score += 6.0;
        }
        // Perfect chain: post_residual exactly matches next item.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are fragmented or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin (wasting all residual capacity elsewhere).
        score += 55.0;
        // More open bins with high mean residual => fragmentation, new bin less bad.
        let fragmentation = mean_residual / (bin_capacity as f64);
        score -= 40.0 * fragmentation;
        // Early in stream: opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to item (good fit ratio).
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 8.0 * fit_ratio;
        // Slight preference for bins below mean residual (balancing).
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Mild penalty for accumulating many open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mildly favor tight fits (low post_residual).
    // Late (progress ~ 1): penalize large residuals more strongly (dead space
    // at the end of the stream can never be recovered).
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let coupling = pr_norm * (1.0 + 2.0 * progress * progress) - 6.0 * poly * (1.0 - progress);

    let mut score = pr + 20.0 * coupling;

    // Smooth penalty for opening new bins when many bins fit the item,
    // scaled by how full the stream already is.
    let fit_term = (fitting_bins_count as f64).ln_1p();
    score += 15.0 * progress * (1.0 / fit_term);

    // Lookahead: reward leaving room for the next item (smooth quadratic gap).
    let nr = next_item_size as f64;
    if nr > 0.0 {
        let gap = pr - nr;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap) * (1.0 - (gap / cap));
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mild preference for bins with below-average residual (tight bins).
    score += 3.0 * ((pr - mean_residual) / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    // into "usable" classes (>= next item, >= half capacity) vs dead space.
    let pr = post_residual;
    let class = pr / 10; // integer division bucket 0..=10

    // Reward residuals that exactly match the next item's size (perfect lookahead fit)
    if next_item_size > 0 && pr == next_item_size {
        score -= 12.0;
    }
    // Reward residuals that can still hold the next item at all
    if next_item_size > 0 && pr >= next_item_size {
        score -= 4.0 + 0.05 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 {
        // dead space relative to lookahead: penalize quadratically
        score += 0.15 * (next_item_size - pr) as f64;
    }

    // Modulo arithmetic on residual: multiples of 10 are "harmonic" residual classes
    let rem10 = pr % 10;
    score += rem10 as f64 * 0.6; // prefer residuals aligned to decade grid

    // Threshold classes via integer division
    if pr >= bin_capacity / 2 {
        score -= 3.0; // still a half-full-capable bin
    } else if class == 0 {
        score += 8.0; // nearly full bin: great, seal it (low residual is good anyway)
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when item leaves harmonically large residue
    if bin_residual == bin_capacity {
        let new_post = bin_capacity - item_size;
        if next_item_size > 0 && new_post >= next_item_size {
            score -= 2.0;
        }
        // discourage opening new bins when open bins fit decently
        if fitting_bins_count > 0 && item_size <= 50 {
            score += 6.0;
        }
        score += 1.5; // mild default cost of opening a bin
    }

    // Stream progression: late in the stream, tighten bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr as f64) * 0.1;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

