        // Opening a new bin is acceptable if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward fullness (lower residual than average is good).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Early in the stream, allow new bins more freely to build a portfolio.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score -= (1.0 - progress) * 8.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // this is a great two-item packing.
    if next_item_size > 0 && post_residual == next_item_size {
