pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Penalize leaving dead space that no plausible item (1..=100) can fill well.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers
    }

    // Lookahead coupling: if the next item exactly fits the post_residual,
    // strongly favor this placement (chains items together).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item cannot use the leftover: mild penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we only
    // open new bins when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // filling bins with larger residuals less aggressively (balance load).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Prefer bins whose residual is close to item size (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += gap * gap * 30.0;

    // Mild preference for using fewer bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let resid_frac = pr / cap;

    // Smooth quadratic reward for tight fits (small post_residual)
    let tightness = 1.0 - resid_frac; // 1 = perfectly tight
    score -= 30.0 * tightness * tightness * fit_frac;

    // Non-linear coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tiny residuals mildly),
    // later, pack tightly (penalize large residuals more).
    let flex = progress * progress;
    score += (1.0 - flex) * 8.0 * resid_frac * (1.0 - resid_frac);
    score += flex * 12.0 * resid_frac * resid_frac;

    // Lookahead: reward residual that can still hold the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            // residual too small for next item: penalize dead space
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let waste_penalty = (mean_residual / cap).max(0.0);
        score += 20.0 + 10.0 * (1.0 - progress) - 15.0 * waste_penalty;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0; // open bins can't hold next item well
        }
    }

    // Mild pressure to reduce open bin count
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: bucket by capacity/10 fractions.
    // Small dead space (<10) is nearly unusable -> strongly penalize leaving it.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Larger residuals are usable: mild reward scaled by class.
        score -= 3.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic integer-division class: residual divisible into chunks of 10/20
    // is more reusable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving a residual that is
            // just barely too small (wasted potential).
            if post_residual >= next_item_size.saturating_sub(5) {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: prefer existing bins unless waste is large.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost grows with number of open bins.
        score = cap - item_size as f64 + 10.0 + open_bins_count as f64 * 0.5;
        // Late in the stream, avoid opening bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 40 {
            score += 15.0 * progress;
        }
        // Opening a bin is fine if a big item benefits from fresh capacity.
        if item_size >= 60 {
            score -= 5.0;
        }
    } else {
        // Mild preference for fuller bins (tight packing first).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it is already tight; encourage filling it.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.2;
    } else {
        score += (res - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
