        score -= 10.0;
    }

    // Compare post_residual against the mean residual across open bins.
    // Leaving a residual far below the mean wastes capacity elsewhere.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
    score -= (post_residual as f64 - mean_residual).max(0.0) * 0.1;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when no good chaining opportunity exists among open bins.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / total_items.max(1) as f64;
        // Prefer reusing open bins early; allow opening new bins more readily later
        // when open-bin clutter (high mean residual spread) is unproductive.
        score += 20.0 - 15.0 * early;
        if open_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            // If next item chains perfectly even in a fresh bin, mild preference.
            score -= 5.0;
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
