    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * t;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 40.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 5.0 * (next_item_size as f64 / cap);
        }
    }

    // New-bin candidate: keep it neutral-to-slightly-positive; only attractive
    // when all open bins leave large post_residuals late in the stream.
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - t);
        score += 0.05 * open_bins_count as f64;
    }

    // Smooth non-linear coupling of fit tightness with stream progress.
    score -= 8.0 * (1.0 - fit).powi(3) * t;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but strongly reward exact/tight fits.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect: residual in "dead zone" (nothing >=10 fits... but sizes 1..100 possible)
    }

    // Harmonic class of post_residual: modulo classes on capacity.
    // Residuals that are multiples of common size classes are reusable.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0; // residual aligns with decile classes -> likely reusable
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Penalize residuals in awkward harmonic classes (prime-ish / odd small values)
    if pr > 0 && pr < 10 {
        score += 20.0; // unusable dead space for most distributions
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward, scaled by how well it fits after too
            let pr2 = pr - next_item_size;
            score -= 12.0;
            if pr2 <= 10 { score -= 10.0; }
        } else {
            // next item won't fit here: mild penalty if we leave a large stranded residual
            if pr >= next_item_size / 2 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 0 {
        // When many bins fit, prefer the tightest (already via post_residual),
        // but slight penalty to spread load: keep scores comparable.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if current fit is bad (large post_residual)
        // or no other bins really fit well. Penalize new bins by default.
        score += 35.0;
        // But if this item is huge and would leave a decent residual anyway,
        // and stream is early (many items to come), allow new bins more readily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 {
            score -= 15.0;
        }
        if progress < 0.2 {
            score -= 5.0; // early stream: opening bins is cheaper long-term
        }
        // If next item is large and current open bins are all crowded, new bin helps
        if next_item_size > 0 && next_item_size >= 50 && mean_residual < 30.0 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: if open bins are already very full on average,
    // prefer spreading; if lots of slack exists, prefer tight fills.
    let slack = mean_residual - post_residual as f64;
    if slack > 0.0 {
        score += slack * 0.15; // this bin's residual below average -> good consolidation
    }

    // Integer-division threshold on post_residual: quarter classes of capacity.
    let quarter = bin_capacity / 4;
    if pr > quarter && pr < 2 * quarter {
        score += 6.0; // mid-range residual is least useful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small unusable gaps (dead space) much more than large leftovers.
        if post_residual <= 10 {
            score += 35.0;
        } else if post_residual <= 20 {
            score += 15.0;
        } else if post_residual <= 30 {
            score += 5.0;
        }
        // Reward leftovers that can still hold typical future items.
        if post_residual >= 50 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits in the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post residual is a tiny sliver just below next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure: when many bins are open, avoid creating near-empty new bins;
    // prefer filling existing ones. New-bin candidate gets a mild handicap
    // unless the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins tighter than average (good utilization).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits in the post-residual: strong reward, scaled by snugness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item: penalize proportionally.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.6;
    }

    // Prefer bins that are tighter than the mean residual (best-fit flavor).
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless it is genuinely needed
    // (i.e., no open bin fits, or all fits leave large dead space).
    if bin_residual == bin_capacity {
        let new_bin_penalty = if fitting_bins_count == 0 {
            -10.0 // forced: no alternative
        } else if next_item_size > 0 && post_residual >= next_item_size {
            35.0 // an open bin can chain too; keep current bins
        } else {
            12.0 + 0.3 * mean_residual
        };
        score += new_bin_penalty;
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (wasted capacity grows quadratically in value)
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect-fill bonus: residual exactly consumed
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward leaving room for the next item if it fits,
    // penalize if the leftover can't hold the next item (dead space trap)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: slight tiebreak toward fuller bins
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: when many open bins exist with high mean residual,
    // prefer consolidating into open bins over opening new ones
    let consolidation_pressure = mean_residual / bin_capacity as f64;
    score -= 10.0 * consolidation_pressure * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: empty bin gets a baseline penalty that shrinks
    // as the stream progresses or when open bins are nearly full
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0
            - 20.0 * progress
            - 30.0 * (1.0 - mean_residual / bin_capacity as f64);
        score += new_bin_penalty.max(0.0);
    }

    // Late-stream: be more conservative, avoid fragmenting residuals
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small bonus for using bins whose residual is close to mean (balance-seeking)
    score -= 3.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap;

    // Reward tight fits: quadratic coupling of fill ratio with stream progress.
    score -= 6.0 * fill * fill * (0.5 + progress);

    // Penalize residuals that are too small to be useful (dead space), scaled by progress.
    let dead = (post_residual as f64 / cap).powi(3);
    score += 20.0 * dead * (0.3 + 0.7 * progress);

    // Prefer bins whose residual deviates favorably from the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a gap that blocks the next item.
        score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it attractive only when few bins fit or item is large.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 10.0 - 14.0 * scarcity - 6.0 * (item_size as f64 / cap);
    }

    // Mild consolidation pressure as stream progresses.
    score += 2.0 * progress * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    // Residuals that are "harmonically compatible" with common item sizes (multiples of 10)
    // are more likely to be filled later; odd/prime-ish residuals waste space.
    let pr = post_residual;
    let class = pr % 10;
    let class_penalty: f64 = match class {
        0 => -8.0,   // perfect multiple of 10: highly reusable
        5 => 2.0,    // half-class: moderately reusable
        _ => 4.0 + (class as f64) * 0.3, // awkward residue: penalize
    };
    score += class_penalty;

    // Integer-division thresholds: does the NEXT item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead synergy: subtract proportional reward, stronger for tight fits
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 + 20.0 / (1.0 + slack);
        } else {
            // next item won't fit: penalize proportionally to the gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Capacity fraction coupling: reward placements that leave residual in the
    // "small-but-fillable" band (1..=20) only if next item can use it, else punish.
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.2 && frac <= 0.35 {
        score += 5.0; // dead zone: too big to ignore, too small to be useful
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Prefer keeping many small open bins consolidated; open new bins only when
    // open bins are crowded and this item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 - 6.0 * progress - (item_size as f64) * 0.1 - crowdedness.min(8.0);
        // opening early for a big item with good lookahead is fine
        if item_size >= 50 && next_item_size >= 40 && next_item_size <= 50 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter fits overall (low post_residual relative to mean)
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Larger gaps scale super-linearly to prefer filling big bins.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // Reward using the last bin that can fit the item (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Dead space for the known next item: penalize.
        score += 10.0;
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // (keep large-residual bins flexible), bins above mean are good targets.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny slivers are near-perfect fills
    } else if post_residual >= 10 {
        score += 0.05 * post_residual as f64; // larger leftover is mild waste
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 2.0;
        }
    } else {
        // Last item: maximize fill, minimize final residual hard.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * (step_index as f64 / total_items.max(1) as f64) * 50.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when existing bins
    // have poor fits (item much smaller than residuals) or many bins are open
    // with low mean residual (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing fits are loose and fragmentation is high.
        score -= 4.0 * fragmentation + 3.0 * (1.0 - fit_ratio);
        // Late in the stream, slightly discourage opening extra bins.
        score += 6.0 * progress;
        // If a perfect fit exists elsewhere, this new-bin call won't win anyway.
        if post_residual == 0 { score -= 5.0; }
    } else {
        // Existing bin: bonus for using bins that are already quite empty
        // (consolidation keeps few, fuller bins).
        score -= 1.5 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    // Prefer exact fills overwhelmingly.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted residual (dead space grows super-linearly).
    let mut score = pr_norm * pr_norm * cap;

    // Smooth cubic coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them harder.
    let prog_term = 1.0 + progress * progress * progress;
    score += pr_norm * pr_norm * pr_norm * cap * prog_term * 0.5;

    // Reward tight fits: subtract when item fills most of the bin.
    let fill = it / cap;
    score -= fill * fill * cap * 0.6;

    // Non-linear interaction: post_residual vs mean residual — prefer bins
    // whose post-residual is close to the fleet mean (keeps options open).
    let dev = pr - mean_residual.max(0.0);
    score += (dev * dev) / cap * 0.15;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        if gap < 1.0 {
            score -= cap * 0.8;
        } else {
            score += (gap / cap) * cap * 0.1 * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.5;
    }

    // New-bin candidate: mild penalty so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += cap * 0.35 * (1.0 - progress * 0.5);
    }

    // Slight preference for consolidating among many open bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: maximal reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor(); // 8 harmonic classes of leftover
    score += class * 2.0; // bigger leftover class => worse

    // Reward bins whose leftover is small but nonzero ("nearly full" harmonic class)
    if post_residual > 0 && post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Integer-division threshold coupling: leftover must accommodate next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover remains usable by lookahead: reward proportional to reusability
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // leftover becomes dead space w.r.t. lookahead: penalize
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Modulo arithmetic on post_residual: residues that pair well with common sizes
    let m = post_residual % 10;
    if m == 0 {
        score -= 15.0; // round leftovers are most reusable
    } else if m >= 7 {
        score += 5.0; // awkward slivers
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: open a new bin only if all open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open
        } else if fitting_bins_count == 1 {
            score += 40.0; // prefer the last-chance bin
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // many open bins with slack: discourage new bin
        if mean_residual > item_size as f64 * 1.5 {
            score += 25.0;
        }
    }

    // Slight preference for fuller bins among equals
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bins pressure: penalize opening/using bins when many are open,
    // but the brand-new empty bin candidate gets a fixed opening tax.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 45.0 + 15.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
    } else {
        score -= 10.0 + 2.0 * open_bins_count.min(20) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slightly penalize leaving a gap it almost fits.
        if post_residual >= next_item_size.saturating_sub(3) {
            score += 12.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., fuller bins) to consolidate content.
    score += (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size -> big reward.
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional to wasted potential.
            score += 10.0 + gap / 10.0;
        }
    }

    // Reward leaving large residuals when many bins are open (diversity of choices).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * (post_residual as f64 - mean_residual).max(-50.0);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current fit is terrible or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 > mean_residual * 0.9
            && post_residual < 20;
        if poor_fit || open_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 30.0 * (1.0 - progress);
        }
    }

    // Mild penalty for very small dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization core).
    let tightness = if post_residual == 0 {
        -500.0
    } else {
        -((post_residual as f64).powi(-1) * 20.0)
    };
    score += tightness;

    // Penalize dead space that can never be reused by typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0; // small unusable slivers are fine to leave
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 25.0; // awkward mid-range residual is bad
    } else if post_residual > 80 {
        score += 60.0; // barely used bin, wasteful placement
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 1.5;
        } else {
            // next item won't fit here; penalize slightly, scaled by how badly
            score += ((next_item_size - post_residual) as f64).min(60.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 2.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // a "tight" bin — using it keeps mean residual high for future items.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Time horizon: early on, be greedy for tight fits; late, consolidate.
    score *= 1.0 + 0.2 * (1.0 - progress);

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let base_penalty = 120.0 + 40.0 * progress;
        score += base_penalty;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial coupling
    let mut score = x * (1.0 + 2.0 * x * x);

    // Tight-fit reward, amplified by stream progress
    let tight = 1.0 - x;
    score -= 6.0 * tight * tight * (0.5 + progress);

    // Dead-space penalty: post-residual too small to be useful later
    let dead = (x * (1.0 - x)).max(0.0);
    score += 4.0 * dead * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - x);
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 2.5 * (1.0 - x) * (1.0 - nx / cap);
        } else {
            score += 1.5 * (1.0 - x) * (nx / cap);
        }
    }

    // Mild preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.05 * x;

    // New-bin candidate: penalize slightly unless residuals are tight
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - cap).abs() / cap;
        score += 1.0 + 2.0 * (1.0 - mean_gap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-decile classes of capacity
    let item_class = (item_size + 19) / 20; // 1..=5 (or up to 5 for 100)
    let post_class = (post_residual + 19) / 20; // harmonic class of leftover

    // Reward placements whose post-residual lands in a "usable" harmonic class
    // (leftovers of 20, 40, 60, 80 are reusable by mid-size items; tiny leftovers are dead space)
    match post_residual {
        0 => score -= 30.0,                      // perfect fit is ideal
        1..=9 => score += 25.0,                  // dead space penalty
        10..=19 => score += 10.0,                // only fits tiny items
        20..=39 => score -= 6.0,                 // reusable class
        40..=59 => score -= 8.0,                 // very reusable
        _ => {}                                   // large leftovers are natural early on
    }

    // Modulo logic: post_residual divisible by 10 aligns with typical item granularity
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold: can the bin still host another item of the next size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead-friendly: chain placement possible
            let chain_fit = post_residual - next_item_size;
            score -= (chain_fit.min(30) as f64) * 0.3;
            // harmonic match: post class equals next item class -> strong pairing
            let next_class = (next_item_size + 19) / 20;
            if next_class == post_class {
                score -= 8.0;
            }
        } else {
            // bin becomes dead after this placement
            score += (next_item_size - post_residual).min(20) as f64 * 0.5;
        }
    } else {
        // last item: prefer perfect closure
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0;
        score = 40.0 + pressure - (mean_residual / 10.0);
        // early in stream, opening bins is cheap; late, discourage
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // don't open a new bin if this item would leave a clean harmonic leftover elsewhere
        if post_residual <= 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // Mild tightness preference: tighter fits among equal post_residuals
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: penalize bins far below mean residual (already loose)
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual that no plausible item (min size 1) can use is pure waste.
    if post_residual > 0 {
        // Dead space weight grows as residual falls into the "unusable sliver" zone.
        let dead_zone = if post_residual <= 10 {
            3.0
        } else if post_residual <= 20 {
            1.5
        } else if post_residual <= 30 {
            0.8
        } else {
            0.0
        };
        score += dead_zone * (post_residual as f64);

        // Perfect fit gets a strong bonus.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize candidates that keep bins scattered.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless it creates terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
        // But if it leaves a nasty sliver, soften the bonus.
        if post_residual > 0 && post_residual <= 10 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (large dead space would result).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: keep it slightly worse than a decent fit.
        score += 12.0;
        // But if the current best alternative would leave big dead space, allow opening.
        if post_residual == 0 {
            score -= 40.0; // exact fit in a fresh bin (e.g. item == 100)
        }
    }

    // Lookahead: if the next item could exactly use the post_residual,
    // reward leaving that gap; if next item is large, penalize small leftovers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 3.0;
        }
    }

    // Late in the stream, tighten up: prefer tight fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Nudge toward bins whose residual is close to mean (avoid pathological outliers).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: baseline cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when the current item leaves a residual
        // that is a poor match for the next item, or when few bins fit.
        let mut nb = 55.0 + 0.35 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            // New bin leaves room for the lookahead item: attractive.
            nb -= 12.0 * (1.0 - (next_item_size as f64 / post_residual as f64).abs());
        }
        if fitting_bins_count <= 1 {
            nb -= 10.0;
        }
        nb += progress * 8.0;
        return nb;
    }

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step fit: place here strongly.
            score -= 40.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover after the lookahead item would fit.
            score += slack * 0.6;
            // Reward if the leftover is still usable (>= small item).
            if slack >= 10.0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot fit in this bin's residual: mild penalty
            // unless this is the only fitting bin.
            score += 10.0;
            if fitting_bins_count == 1 {
                score -= 15.0;
            }
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 20.0;
    }

    // Relative-to-mean-residual term: bins with residual far below mean
    // are good candidates to close out (their space is scarce).
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.25;

    // Last-chance bonus: this bin is the only one that can fit the item.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize creating unusable dead space (< 10, since items >= 10... be lenient for small items).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference early in the stream to keep bins balanced.
    score += (1.0 - progress) * (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect or near-perfect fill: massive reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Dead-space penalty: residual left behind that is likely unusable
    // (smaller than the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward leaving a residual that can host the next item,
    // penalize when the leftover is just barely too small for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - progress);
            // Extra reward if the leftover exactly matches the next item.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if post_residual > 0 {
            score += 5.0 + 4.0 * (1.0 - progress);
        }
        // If the next item fits this bin too, mild preference to keep pairing.
        if bin_residual >= next_item_size && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fuller bins.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins that are already relatively full (small residual fraction).
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fullness;

    // Global state coupling: if mean residual across open bins is high,
    // discourage opening new bins / wasting space; encourage using existing bins.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
    } else {
        // New-bin candidate: penalize opening a new bin when existing bins fit well,
        // scaled by how many bins are already open and how much of the stream remains.
        let open_cost = 10.0 + 0.6 * open_bins_count as f64 * (1.0 - progress);
        score += open_cost;
        // But if mean residual is low (open bins nearly full), a new bin is fine.
        score -= 0.08 * mean_residual;
        // If the item is large, a fresh bin gives maximal flexibility.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Late-stream behavior: near the end, prioritize closing out bins tightly.
    if progress > 0.8 {
        score -= 4.0 * (progress - 0.8) * 5.0 * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: raw post-residual waste
    let mut score = post;

    // Non-linear polynomial coupling of waste with stream progress:
    // late in the stream, dead space is costlier -> amplify quadratic waste term
    let waste_frac = post / cap;
    score += waste_frac * waste_frac * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) with a smooth exponential bonus
    score -= 8.0 * (-post / (0.25 * cap)).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // smooth coupling: closer the next item fills the leftover, the better
            let gap = (post - nxt) / cap;
            score -= 6.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // next item won't fit here: mild penalty scaled by wasted potential
            score += 2.0 * (post / cap);
        }
    }

    // Penalize placements into bins far from the mean residual (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * open_bins_count as f64;

    // New-bin candidate: prefer it only when it's genuinely better (early stream or huge item)
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // opening a new bin is attractive early or when item is large and fits are poor
        score = 0.75 * cap * (1.0 - progress) + 20.0 * item_frac * (1.0 - item_frac);
        if fitting_bins_count == 1 {
            score += 25.0; // discourage abandoning the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
