    // no open bin gives a good harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 55.0;
        // More attractive early in the stream (many items left to use the bin)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Attractive if open bins are all crowded (high mean residual usage)
        score -= 0.15 * (open_bins_count as f64) + 0.1 * (cap - mean_residual);
        // If next item is large, a fresh bin is useful
        if next_item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Slight preference to keep bins balanced when many bins are open
        score += 0.05 * (mean_residual - pr).abs();
        // Prefer filling bins with small residual relative to mean (waste reduction)
        if pr < mean_residual {
            score -= 5.0;
        }
        // Modulo-based harmonic bonus: residual divisible into common item sizes
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Mild noise-free tie-breaking on residual class to stabilize selection
    score -= class * 0.3 * (1.0 - pr_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Penalize wasting a large residual on a small item (creates fragmented space).
    if fit_ratio < 0.35 {
        score += (0.35 - fit_ratio) * 40.0;
    }

    // Open-bins pressure: many open bins make opening a new one less attractive.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (open_bins_count as f64 * 2.5 + 20.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't reuse the gap: dead space penalty.
        score += post_residual as f64 * 0.3;
    }

    // Early stream: be a bit more willing to open bins to build a good spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how far off the chain is
            score += diff * 0.4;
            // Extra penalty if post_residual just barely misses fitting next item
            if post_residual < next_item_size && post_residual > 0 {
                score += 12.0;
            }
        }
    } else {
        // Last item: minimize leftover directly, reward tight fits
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Reward bins tighter than the mean residual (good consolidation)
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.15;
    }

    // Penalize near-empty usage of fresh bins unless nothing fits well
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it only wins when fits are poor
        score += 18.0;
        // Prefer opening new bin late in stream when many bins are open and cluttered
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 8.0 + (open_bins_count as f64).min(10.0);
    }

    // Dead-space penalty: post_residual too small to ever fit min item (1..100 unknown, assume ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: prefer bins that end up nearly full.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: reward if the next item fits exactly into the post residual
    // (perfect chain), mildly reward if it fits at all.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize leaving large dead space.
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Last item: only tightness matters; strongly reward near-full bins.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits poorly everywhere else (large post residual relative to
    // item size) or the stream is early and we expect future large items.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when justified.
        score += 12.0;
        // Early stream: future items may be big, a fresh bin has option value.
        score -= 15.0 * (1.0 - progress);
        // Many open bins: adding more fragments capacity; penalize.
        score += 0.8 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin wastes little.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Reward using existing bins slightly, more so late in the stream.
        score -= 5.0 * progress;
    }

    // Global balance: prefer bins whose residual is near the mean residual
    // (keeps the fleet homogeneous and future-fit friendly).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    // Prefer filling bins with small residuals first (avoid stranding them).
    if bin_residual < 2 * item_size && bin_residual >= item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear waste penalty: quadratic in normalized residual
    score += 8.0 * norm_pr * norm_pr;

    // Tight-fit reward: strong when post_residual is small, scaled by stream progress
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tightness * (0.5 + progress);

    // Lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 20.0) * (1.0 + progress);
        // penalize leaving residual slightly larger than next item (dead space trap)
        if next_item_size as f64 > pr {
            score += 2.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin early, penalize late
    if bin_residual == bin_capacity {
        score = 60.0 * (1.0 - progress) + 20.0 + 5.0 * norm_pr;
        if fitting_bins_count == 1 {
            score += 40.0; // discourage abandoning the only fitting bin
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (denser bins)
    score -= 2.0 * (mean_residual - pr) / cap;

    // Slight preference for using fewer bins: more open bins -> favor filling existing
    score -= 0.5 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lies in
    // "usable" modular classes should be rewarded (lower score).
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by common item granularities (5,10,20)
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Class B: post_residual small enough to be near-perfect fill
    if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Class C: integer-division dead-space classes: leftover that no item
    // (min size 1, but typical small items ~10) can fill is penalized.
    let dead = (post_residual as f64) * (post_residual as f64) / cap;
    score += dead * 0.15;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize large leftovers proportionally
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline that
    // depends on stream progress and how fragmented the open bins are.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            0.0
        };
        // Opening a new bin is attractive when existing residuals are large
        // (fragmented) and we are early/mid stream; late in the stream prefer
        // filling existing bins.
        score = 30.0 + (1.0 - fragmentation) * 10.0 + progress * 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Mean-residual harmony: prefer bins close to the mean residual
    // (keeps the bin pool homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Modulo-20 harmonic class on item size: items in "big" classes
    // (>50) benefit from tight bins more.
    if item_size > 50 && post_residual <= 30 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 8) are essentially dead space.
    let dead_threshold: f64 = 8.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits strongly (super-linear in tightness).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0;
        } else {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + 2.0 * pressure;
        // But allow opening a fresh bin if no existing bin gives a decent fit.
        if post_residual == bin_capacity - item_size && fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        score -= 1.5 * pressure * (post_residual as f64) / (bin_capacity as f64);
    }

    // Prefer bins whose residual is close to the mean (keeps bins balanced).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && post_residual > 0 {
        let lookahead_gap = post_residual as i64 - next_item_size as i64;
        if lookahead_gap == 0 {
            score -= 45.0;
        } else if lookahead_gap > 0 && lookahead_gap <= 10 {
            score -= 15.0;
        } else if lookahead_gap < 0 {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += (-lookahead_gap as f64).min(30.0) * 0.5;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less than average waste is desirable.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless it's clearly beneficial:
    // a fresh bin is only attractive when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large relative to capacity and no lookahead synergy,
        // new bin is still slightly less attractive.
        if item_size >= 60 {
            score += 10.0;
        }
        // If next item is small, opening a new bin wastes its large residual;
        // encourage using existing bins instead.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 10.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor minimal post residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Lookahead: penalize leaving residual that only the next item can't use,
    // reward leaving residual the next item can fill.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= chain_tightness * 4.0;
        } else {
            // dead space relative to lookahead
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // competition: slightly prefer tighter bins among many candidates
        score += fitting_bins_count as f64 * 0.2;
    }

    // Penalize creating very small unusable residuals (likely dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 2.0;
    }
    if post_residual == 0 {
        score -= 12.0; // perfect closure
    }

    // Global state: when many bins are open and mean residual is high,
    // encourage consolidation into open bins rather than opening new ones.
    score += mean_residual * 0.05;
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling: empty bin residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; adjust with time horizon and stream state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 20.0
            + (bin_capacity - item_size) as f64 * 0.5
            + progress * 3.0;

        // If next item is large and won't fit leftover, opening fresh can help.
        if next_item_size > 0 && (bin_capacity - item_size) < next_item_size {
            new_bin_score -= 4.0;
        }
        // Few fitting bins and high mean residual -> prefer open bins.
        if fitting_bins_count >= 1 {
            new_bin_score += 6.0;
        }
        score = score.max(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Strong reward for tight fits (small post_residual), smooth non-linear.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (1.0 + 0.5 * progress);

    // Penalize large dead space super-linearly.
    score += 18.0 * norm_pr * norm_pr * cap * 0.1;

    // Lookahead: reward if next item fits in the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // Penalize residuals that block the lookahead item.
        score += 8.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Last-chance bonus: only one bin fits this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins, more so early and when alternatives exist.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 6.0 * (open_bins_count as f64).sqrt();
        // Allow opening only if existing bins would leave huge waste.
        if fitting_bins_count > 0 {
            score += 10.0 * (mean_residual - (mean_residual - item_size as f64).max(0.0));
        }
    }

    // Mild preference for filling bins below current mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues that commonly recur
    // (multiples of small integers) are more reusable than odd dead space.
    let pr = post_residual as u32;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fit: ideal
    } else if pr % 10 == 0 && pr <= 40 {
        class_bonus -= 25.0; // clean small residue, highly reusable
    } else if pr % 5 == 0 && pr <= 50 {
        class_bonus -= 15.0;
    } else if pr <= 10 {
        class_bonus -= 20.0; // tiny dead space is acceptable
    } else if pr > 50 {
        class_bonus += 10.0; // large residue wasted on a small item
    }
    score += class_bonus;

    // Lookahead: does the next item fit into the post-residue?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by tightness of fit
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 + 0.3 * slack;
            if pr % next_item_size == 0 {
                score -= 10.0; // exact harmonic division
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot
            score += 0.2 * (next_item_size - pr) as f64;
        }
    } else {
        // Last item: any bin that fits is fine, prefer tightest anyway
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early / bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let penalty = 25.0
            + 20.0 * (1.0 - progress)      // early: reuse bins aggressively
            - 30.0 * scarcity              // nothing fits: new bin is fine
            + 2.0 * open_bins_count as f64 * (1.0 - scarcity);
        score += penalty;
    }

    // Mild normalization toward mean residual: avoid extreme outliers
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A post-residual gap that is too small for the smallest possible item (1)
    // is pure waste; gaps smaller than the lookahead item are likely waste too.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 50.0;
    } else {
        let pr = post_residual as f64;
        // Nonlinear penalty for tiny dead gaps (wasted space region).
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0;
        }
        // If the lookahead item cannot fit in the resulting gap, the dead space
        // is likely permanent: extra penalty scaled by lookahead size proximity.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving a gap that exactly accommodates the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Perfect-fit shaping: reward tight packing relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: discourage scattering across many bins; encourage
    // filling existing bins when the fleet is already large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (smaller residual than average means tighter packing).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with progress through stream.
        score += 30.0 + 40.0 * progress;
        // If this bin is a last chance for the item, opening new bin is bad.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // If the next item is large, a fresh bin may still be reasonable:
        // soften the penalty slightly.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain: this bin becomes exactly full next step
        } else if next_item_size < post_residual {
            // partial chain: reward closeness of next item to post residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + gap);
        } else {
            // next item cannot fit: penalize leaving a residual that blocks it
            let excess = (next_item_size - post_residual) as f64;
            score += 20.0 + excess * 0.5;
        }
    }

    // Relative residual coupling vs mean residual of open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 0.5 {
            score -= 30.0 * (0.5 - rel); // tighter than average: good packing
        } else {
            score += 15.0 * (rel - 0.5); // looser than average: discourage
        }
    }

    // Last-chance bin bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // options are genuinely bad (e.g. item large relative to residuals).
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64) * 40.0
            + (fitting_bins_count == 0) as i32 as f64 * 100.0;
        score += 250.0 - pressure; // default high penalty, reduced under pressure
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can chain next item
        }
    }

    // Slight preference for larger items filling bins tightly late in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (item_size as f64 / bin_capacity as f64) * 10.0 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize heavily when post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 14.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual is dead space for the next item: mild penalty scaled by gap.
        let gap = next_item_size - post_residual;
        score += 3.0 * (gap as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin whose residual is closest to item_size.
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += diff * 0.35;
    }

    // Penalize opening a new bin, especially early / when open bins have room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        score += 16.0 + 10.0 * (1.0 - progress) + 2.5 * open_pressure + 0.3 * avg_waste;

        // But if no open bin fits well and mean residual is small, new bin is fine.
        if fitting_bins_count == 0 || mean_residual < item_size as f64 {
            score -= 14.0;
        }
    }

    // Slight preference for filling already-open bins as stream progresses.
    if bin_residual < bin_capacity {
        score -= 2.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Penalize leaving large awkward residuals that few items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers are wasted capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, with non-linear (quadratic/cubic) coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress) + 120.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic term: late in stream, small residuals become valuable dead-space waste
    score += 60.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits: interaction of post_residual with item size
    let tightness = 1.0 - (pr / cap);
    score -= 40.0 * tightness * (item_size as f64 / cap) * (1.0 + progress);

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 40.0 * progress;
    }

    // Many fitting bins: this placement is less critical, mild penalty
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 50.0 * (1.0 - diff / cap).max(0.0);
        // If next item would NOT fit here, mildly penalize hoarding space
        if next_item_size as f64 > pr {
            score += 8.0 * progress;
        }
    }

    // Mean residual context: penalize bins far from mean (outliers)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: neutral baseline with slight stream-dependent cost
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0; // prefer existing bins unless they're bad
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 modulate dead-space penalty.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -18.0, // perfectly aligned residual -> excellent reuse
        5 => -10.0, // half-class still attractive
        2 | 8 => -4.0,
        4 | 6 => 2.0,
        1 | 9 => 6.0,
        3 | 7 => 8.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: post_residual bands.
    let band = post_residual / 10;
    score -= (band as f64) * 1.5; // larger usable residual slightly favored

    // Penalize tiny unusable slivers strongly (non-linear).
    if post_residual < 5 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect packing
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
        } else {
            // next item cannot use this residual; mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < 25.0;
        if crowded || post_residual > 60 {
            score -= 20.0 + 15.0 * progress;
        } else {
            score += 30.0; // keep filling open bins when they are roomy
        }
    }

    // Capacity-fraction coupling: reward filling bins beyond half full.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 12.0;

    // Many open bins -> prefer consolidation.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (1..=10) are nearly unusable
    // for future items (sizes >= 1 but typically chunky); penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 - (post_residual as f64) / 10.0) + 10.0;
    } else if post_residual > 10 && post_residual <= 25 {
        // Medium-small gaps: moderate penalty, scaled by how close to "useless"
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with mean residual: bins already far below mean residual
    // (i.e. relatively empty) are less precious; bins tighter than average
    // should absorb the item to consolidate space.
    let tightness = mean_residual - bin_residual as f64;
    score -= 0.5 * tightness;

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new bins; when few bins are open, new-bin option is cheap.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item would leave a
    // large usable residual AND existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 15.0 + 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // If next item is small and would fit in the fresh residual, slight bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        // If there is exactly one fitting bin (last chance), opening new is bad.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would not fit in post-residual but would fit in a fresh bin,
    // mildly penalize leaving a residual that blocks it.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item can fill this bin's post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 25.0 - (leftover as f64) * 0.4; // good chain, decaying with leftover
        } else {
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.3; // next item won't fit here, mild penalty
        }
    } else {
        // last item: just minimize post residual hard
        score += post_residual as f64 * 0.5;
    }

    // Penalize unusable dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0; // tiny unusable sliver
    }
    if (pr - mean_residual).abs() < 5.0 {
        score -= 5.0; // keeping residuals balanced preserves flexibility
    } else if pr > mean_residual * 1.5 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild pressure against opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
    }

    // Slight preference for tighter fits as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large leftover space only mildly; it may still host future items.
    let cap = bin_capacity as f64;
    score += 0.15 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap * 0.1;

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * nest * nest;
        } else {
            // Next item won't fit here; slight penalty for wasting residual.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is costly; only attractive
    // when existing bins fit poorly (high mean residual waste) or item is large.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / cap) * (1.0 - (mean_residual / cap).min(1.0));
        let phase = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more early on (amortize over long stream), less when
        // open bins are crowded.
        let open_penalty = 10.0 + 20.0 * (1.0 - phase) + 0.5 * open_bins_count as f64;
        score += open_penalty;
        // Reward new bin when item is large and mean residual is small (poor fits).
        score -= 40.0 * pressure;
        // If next item also large, opening a bin may still be fine.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier space usage).
    score += 0.1 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling: residual normalized, shaped by progress
    let norm_pr = pr / cap;
    let shape = 1.0 + 2.0 * progress * (1.0 - progress); // smooth bump peaking mid-stream
    score += 6.0 * norm_pr * norm_pr * (1.0 + shape) * cap * 0.05;

    // Penalize residuals that neither fit next item well nor are tiny
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap > 0.0 {
            score += 2.0 * (gap / cap).powi(2) * (1.0 + progress);
        } else {
            score -= 1.5 * (1.0 + progress); // reward leaving room for next item
        }
    }

    // Last fitting bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate: mild penalty early, stronger when many bins open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    } else {
        // reward filling bins tightly, scaled by mean residual divergence
        score -= (mean_residual - pr).abs() * 0.02;
        score -= (item_size as f64 / cap) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division into capacity bands.
    let band = post_residual / (bin_capacity / 5); // bands of 20: 0..=4
    let band_bonus = match band {
        0 => -14.0,           // post_residual < 20: near-perfect fill
        1 => -7.0,            // 20..39: good fill
        2 => 0.0,             // 40..59: neutral
        3 => 6.0,             // 60..79: wasteful
        _ => 10.0,            // 80+: very wasteful
    };
    score += band_bonus;

    // Modulo arithmetic on post_residual: small odd remainders are dead space.
    let rem = post_residual % 10;
    if rem != 0 && rem < 5 {
        score += 2.5; // awkward leftover (1..4) unlikely to be reused
    } else if rem == 0 && post_residual > 0 {
        score -= 1.5; // round leftover (10,20,...) reusable
    }

    // Lookahead pairing: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        if next_item_size == post_residual {
            score -= 12.0; // perfect pair
        }
        // harmonic class match: next item lands in same 20-band
        let next_band = next_item_size / (bin_capacity / 5);
        if next_band == band {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for the next item: penalize unless it's tiny
        score += (post_residual as f64) * 0.08;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    // and when many bins are open with room (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 6.0 * progress;
        if post_residual > 20 {
            score += (post_residual as f64 - 20.0) * 0.15;
        }
    } else {
        // Favor tighter bins relative to mean residual of open bins.
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.12;
        // mild congestion bonus: prefer existing bins when many are open
        score -= (open_bins_count as f64).min(10.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (>=1)
    // can use are pure waste; residuals below the minimum item size are worst.
    let dead = (post_residual as f64 / bin_capacity as f64).powf(3.0) * 120.0;
    score += dead;

    // Tiny unfillable gap (< 10 or < next item) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones;
    // with few open bins, consolidation is fine.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // Prefer bins whose residual is near the mean (balance), mildly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // New-bin candidate: keep it competitive only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-zero post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the post_residual,
    // this is a chain fit -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a new residual; reward proportional to
            // how small the resulting two-step residual is.
            let two_step_residual = post_residual - next_item_size;
            score -= (item_size as f64) * (1.0 - two_step_residual as f64 / bin_capacity as f64);
            if two_step_residual <= 5 {
                score -= 300.0;
            }
        } else {
            // Next item cannot use the post residual: penalize dead space
            // proportionally to how unusable it is for the next item.
            let dead = post_residual as f64;
            let waste_ratio = dead / bin_capacity as f64;
            score += waste_ratio * 150.0;
            // Extra penalty if the dead space is just below next_item_size
            // (painfully close to a chain fit).
            let gap = (next_item_size as f64) - dead;
            if gap > 0.0 && gap <= 10.0 {
                score += (10.0 - gap) * 20.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (tighter bins) when the fit is good; penalize very loose bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make opening a new bin only attractive when no open bin
    // offers a decent fit. Penalize the fresh bin moderately, more so early in
    // the stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 250.0 + 200.0 * progress + 10.0 * open_bins_count as f64;
        // Exception: large items relative to residual patterns benefit from a
        // fresh bin when next item is also large.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 200.0;
        }
    }

    // Late-stream consolidation: as the stream ends, tighten packing more
    // aggressively to avoid stranded residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual.min(20) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits: subtract proportionally to how well item fills residual
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness * fill;

    // Penalize large unusable dead space (post_residual too small to matter)
    if post_residual < 10 {
        score -= 6.0; // perfect closure reward
    } else if post_residual < 20 {
        score -= 3.0;
    } else {
        // penalize leaving large awkward gaps relative to mean residual
        score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for stranding space
        score += 0.02 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced late in stream or when bins are crowded
        score += 5.0 + 10.0 * (1.0 - t) - 0.1 * open_bins_count as f64;
        // if current item nearly fills a fresh bin, opening is attractive
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 12.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate
    if open_bins_count > 2 {
        score -= 0.05 * mean_residual * (open_bins_count as f64).ln();
    }

    // Mild time-horizon damping: early stream, be conservative with big gaps
    score += (1.0 - t) * 0.03 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64;

    // Tightness: reward filling the bin (low post_residual relative to capacity)
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Exact fit bonus (strongly reward near-zero residual)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0 * (1.0 - pr / 10.0);
    }

    // Penalize creating dead space unusable by the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && nx > pr {
            score += 8.0 * (nx - pr) / cap * (1.0 + progress);
        } else if nx > 0.0 && pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Prefer the bin that leaves the largest residual among many options
        score += 3.0 * (pr / cap) * (fitting_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it late in the stream or when mean residual is small
    if bin_residual == bin_capacity {
        let mean_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 10.0 * mean_fit * openness * (1.0 - progress) + 5.0 * mean_residual / cap;
        if next_item_size > 0 && next_item_size as f64 >= fit {
            score -= 8.0; // pairing with the next item favors a fresh bin
        }
    }

    // Non-linear residual/progress coupling: waste matters more as stream ends
    score += 0.05 * (pr * pr) / cap * (0.5 + progress);

    // Mild preference for bins with residuals close to mean (balance)
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: residual mod 10 buckets
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -14.0,   // perfect fill class
        5 => -6.0,    // half-slots pair well
        2 | 8 => -3.0,
        4 | 6 => -1.5,
        1 | 9 => 2.0,
        _ => 0.0,     // 3 | 7 awkward
    };
    score += class_penalty;

    // Integer-division thresholds: how many size-10 units remain
    let units = post_residual / 10;
    score -= (units as f64).min(4.0) * 2.5;

    // Tightness: reward when item fills most of the bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fill_ratio - 0.85).max(0.0) * 30.0;
    if fill_ratio > 0.95 { score -= 10.0; }

    // Lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual {
        // leaving dead space the next item cannot use
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin, less so early or when
    // the current item is large and open bins have poor fit potential
    if bin_residual == bin_capacity {
        let mut new_penalty = 12.0 + 6.0 * (open_bins_count as f64).ln().max(0.0);
        if item_size >= 60 { new_penalty -= 6.0; }
        if progress < 0.2 { new_penalty -= 4.0; }
        score += new_penalty;
    }

    // Prefer bins with below-average residual (more filled bins first)
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (items are >= 1, so gap < next plausible item
    // is waste; treat gaps below 12 as near-dead).
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit — strongly reward.
        score -= 60.0;
    } else if post_residual <= 10 {
        // Unusable dead space: penalize proportionally to how dead it is.
        score += (11.0 - pr) * 8.0;
    } else if post_residual <= 20 {
        score += (21.0 - pr) * 2.0;
    }

    // Reward tight fits: smaller post_residual relative to capacity.
    score -= (bin_capacity as f64 - pr) / bin_capacity as f64 * 10.0;

    // Lookahead synergy: if the next item fits exactly into the post_residual,
    // reward heavily; if it cannot ever fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a good
    // fit exists; encourage using existing bins when few are open.
    let pressure = open_bins_count as f64;
    if fitting_bins_count > 1 {
        // Competition: prefer bins where this item leaves a cleaner residual.
        score += pressure * 0.35;
    }

    // Last-chance bin: strongly favor using the only bin that can fit,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has maximal flexibility, but
    // opening new bins is costly. Only attractive if this item fits poorly
    // everywhere else (large dead space) or few bins are open.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if fitting_bins_count >= 1 {
            (post_residual as f64 / bin_capacity as f64).max(0.0)
        } else {
            0.0
        };
        score += 30.0; // base cost of opening a new bin
        score -= poor_fit_elsewhere * 40.0; // worth it if fits elsewhere are terrible
        score -= (total_items as f64 - step_index as f64).max(0.0) / (total_items.max(1) as f64) * 5.0;
    }

    // Mean-residual coupling: if the average residual across open bins is
    // small (bins are nearly full), slightly favor this bin less; if large,
    // prefer consolidating into fuller bins.
    score += (mean_residual - pr) * 0.15;

    // Stream progression: late in the stream, be more conservative about
    // opening bins and more aggressive about filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: does next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size > post_residual {
            // dead space of size post_residual likely remains
            score += (post_residual as f64) * 0.5;
        } else {
            // next item fits, penalize remaining residual after pair placement
            let after_pair = post_residual - next_item_size;
            score += after_pair as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize leaving small unusable slivers (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // New-bin candidate: mild penalty so open bins are preferred unless they fit poorly
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64) * 2.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: exact fit is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Squared waste penalty: small residuals are fine, large ones bad.
        score += (post_residual as f64).powf(1.5) * 0.05;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mildly good, residual remains usable
            score -= 20.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize proportionally to the gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0 + 2.0 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin should only win when
    // open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (late in the stream, keeping many bins open is less useful).
        let mut new_bin_cost = 150.0 * (1.0 - 0.5 * progress);
        // If many bins are open and mean residual is large, opening new
        // bins is cheaper than fragmenting further.
        new_bin_cost -= 5.0 * open_bins_count as f64 * progress;
        // If the mean residual across open bins is small, prefer new bin.
        new_bin_cost -= (mean_residual - 20.0).max(0.0);
        score += new_bin_cost.max(0.0);
    }

    // Prefer bins whose residual deviates below the mean (consolidate
    // small holes into few bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.3 * dev;
        } else {
            score += 0.2 * (-dev);
        }
    }

    // Mild pressure to close out bins early in the stream: penalize
    // leaving moderate residuals when many bins are open.
    if open_bins_count > 4 && post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tiny residuals mildly less),
    // later, reward tight packing more aggressively.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (pr / (1.0 + progress)) * 0.5;

    // Interaction: post_residual vs mean residual across open bins
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing bins,
    // but relax penalty as stream progresses (avoid over-tight packing late).
    if bin_residual == bin_capacity {
        score += 15.0 - 8.0 * progress;
    }

    // Mild penalty for many open bins to discourage bin proliferation early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Small smooth tie-breaker
    score += 0.01 * (bin_residual as f64).sin() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover lands in
    // "small, well-quantized" classes are more valuable to keep tidy.
    let class_width = 12u32;
    let post_class = post_residual / class_width;          // 0..=8
    let post_phase = post_residual % class_width;          // intra-class offset

    // Reward low post_residual classes (tight fit), quadratically.
    score -= (8 - post_class.min(8)) as f64 * 9.0;
    // Small phase jitter: prefer residuals that are near the class lower edge.
    score -= (class_width - post_phase) as f64 * 0.15;

    // Perfect / near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item can exactly consume the leftover,
    // this bin becomes a chain anchor -> heavy reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual && (post_residual - next_item_size) <= 8 {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // leftover cannot serve the next item: mild penalty scaled by gap class
            let gap_class = (next_item_size - post_residual) / 15 + 1;
            score += gap_class as f64 * 4.0;
        }
        // If next item would perfectly fill a fresh bin, opening new is attractive
        if bin_residual == bin_capacity && next_item_size == bin_capacity {
            score -= 120.0;
        }
    }

    // Last-chance bin: this is the only open bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless they are fragmented.
    if bin_residual == bin_capacity {
        // Base hesitation: opening a bin is costly.
        score += 25.0;
        // If existing bins are fragmented (high mean residual) and many fit,
        // opening new is more acceptable.
        if mean_residual > 35.0 && fitting_bins_count > 2 {
            score -= 12.0;
        }
        // Early stream: keep bins open, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score += 15.0;
        }
        // Few open bins with low mean residual -> definitely reuse them.
        if open_bins_count <= 2 && mean_residual < 25.0 {
            score += 20.0;
        }
    } else {
        // Reusing a bin with a large residual for a small item wastes capacity;
        // harmonic penalty grows with bin_residual class.
        let res_class = bin_residual / class_width;
        if res_class >= 5 && item_size <= 25 {
            score += 8.0;
        }
    }

    // Mean-residual alignment: bins far below mean residual are "pre-loaded" for
    // future items; bins above mean are the natural dump targets.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.25;
    } else {
        score += (-diff) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize small non-zero gaps hard, non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead space that cannot host the lookahead item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 15.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones
    // (penalize the new-bin candidate and discourage spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the average residual (better fit quality).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when it enables a good pairing
    // with the lookahead item; otherwise keep it discouraged.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the leftover: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack * 0.08);
    }
    // Post-residual too small for next item: penalize dead space, worse when
    // the leftover is tiny (unusable) rather than moderately reusable.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.15;
    }
    if next_item_size == 0 && post_residual > 0 {
        // Last item: prefer filling bins as tightly as possible.
        score += 8.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "scarce"
    // space; using them is good (subtract), wasting them is bad (add).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr < mean_residual {
            score -= 6.0 * (1.0 - pr / mean_residual);
        } else {
            score += 3.0 * ((pr - mean_residual) / mean_residual).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to close out bins early in the stream; later, allow
    // opening fresh bins for better structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline so it only wins when open bins
    // score poorly (poor fits / dead space penalties above).
    if bin_residual == bin_capacity {
        score = 45.0 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that nothing (min size 1) can use, scaled by item size
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
            // bonus proportional to how tightly next item fits
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= (10.0 - gap) * 2.0;
            }
        } else {
            // next item won't fit here; penalize leaving large residual that fragments
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance: only one bin can fit the item; strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // tightness competition among fitting bins: prefer tightest fit
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 20.0;
    }

    // New-bin candidate handling: only open a new bin when item is large
    // relative to capacity or when open bins are mostly full (low mean residual)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // penalty that shrinks for large items / late stream / crowded bins
        let open_pressure = (open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64)).ln().abs();
        score += 25.0 - large_item * 30.0 - progress * 10.0 - open_pressure * 3.0;
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 5.0; // room for next item too
        }
    }

    // Global fragmentation: if mean residual is high, keep filling existing bins
    score += mean_residual * 0.05;

    // Time horizon: late in stream, avoid opening bins / prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Slight preference for bins with residual close to item (best-fit core)
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual

    // Base: post residual, scaled by progress (later => care more about tight fits)
    let mut score = pr * (0.5 + progress);

    // Smooth non-linear coupling: quadratic/cubic shaping of normalized residual
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like
    score += poly * cap * (0.15 + 0.35 * progress);

    // Penalize large dead space more aggressively as stream progresses (quartic term)
    score += x.powi(4) * cap * (0.2 + 0.6 * progress);

    // Reward tight fits (small post-residual) with smooth exponential bonus
    score -= (1.0 - x).powi(3) * cap * 0.25 * (1.0 - progress);

    // Coupling with mean residual: prefer bins whose residual deviates smoothly
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * cap * 0.1;
    score += dev * dev * cap * 0.15;

    // Lookahead: reward leaving space for next item (smooth quadratic fit)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        if diff >= 0.0 {
            let fit_quality = 1.0 - (diff / cap).powi(2).min(1.0);
            score -= fit_quality * n * 0.3;
        } else {
            // penalize blocking the next item, smoothly
            score += (-diff / cap) * cap * 0.4 * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.3 + 0.4 * progress);
    }

    // New-bin candidate: make empty bin mildly unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.9 - 0.5 * progress * avg_tightness);
    }

    // Mild penalty for too many open bins (encourages consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins grouped by capacity/8 classes.
    let class = (post_residual / 13) as f64;
    score += class * 3.0;

    // Perfect-fit harmonic classes: reward exact closures via modulo structure.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual % 13 == 0 {
        score -= 25.0; // residual matches harmonic grid -> likely reusable slot
    } else if post_residual % 7 == 0 {
        score -= 10.0;
    } else if post_residual < 10 {
        score += 60.0; // tiny dead space below smallest item size -> penalize
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits; reward proportionally to how snug it is
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 - snug.min(30.0) * 0.5;
            if post_residual == next_item_size {
                score -= 120.0; // chained perfect fit
            }
        } else {
            // next item won't fit here; penalize by the shortfall, harmonically scaled
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * (0.5 + (shortfall / bin_capacity as f64));
        }
    } else {
        // Last item: strongly prefer closing bins out.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, reduced when stream is early or many items remain
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 140.0 - 60.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin guarantees room for the next item too
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    }

    // Mild pressure toward filling bins with large residuals relative to mean.
    if bin_residual < bin_capacity {
        let gap = mean_residual - bin_residual as f64;
        score -= gap * 0.3;
    }

    // Integer-division threshold on post_residual: discourage mid-class leftovers.
    let rem = post_residual % 13;
    if rem > 0 && rem < 5 && post_residual > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the minimum item size (1..=5)
    // are pure waste; penalize them heavily with a nonlinear term.
    let dead_threshold = 6u32;
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual <= 12 {
        // Small but potentially usable gaps: mild penalty to prefer exact fits.
        score += 4.0 * (12 - post_residual) as f64;
    }

    // Reward tight fits: the smaller post_residual relative to item_size, the better.
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Make the empty bin's score depend on how wasteful the
    // current best option would be.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = item_size as f64 * 0.5 + 20.0;
        // If many bins fit the item, prefer reusing one of them.
        if fitting_bins_count > 0 {
            score += 15.0 + 2.0 * fitting_bins_count as f64;
        }
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the item is large relative to capacity, a new bin is more acceptable.
        score -= 0.2 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < dead_threshold {
            score -= 18.0;
        }
    }
    // If next item would be blocked by this placement's residual, slight penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mean residual context: prefer bins whose residual is below mean (tighter bins),
    // i.e. penalize bins that are looser than average.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (bin_res_f - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but keep score comparable to new-bin candidate (post_residual = capacity).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: exact match of post_residual with next item is perfect.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 60.0; // perfect 2-chain: fill bin with next item too
        } else if post >= nxt {
            let slack = post - nxt;
            // penalize leftover after hypothetical next placement
            score += slack * 0.35;
            // reward if next item leaves a small-but-usable gap
            if slack <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow: dead space risk, penalize proportionally
            score += (nxt - post) * 0.5;
        }
        // coupling with mean residual: bins far below mean residual are "valuable" to close out
        let dev = mean_residual - post;
        if dev > 0.0 {
            score -= dev * 0.25;
        } else {
            score += (-dev) * 0.15;
        }
    } else {
        // last item: purely minimize waste
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit well, unless item is huge
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral baseline is its residual (capacity), adjust
        if open_bins_count > 0 && next_item_size > 0 {
            score -= 10.0; // slight preference for new bins to keep flexibility
        }
        if item_size >= 70 {
            score -= 5.0; // big items fine in fresh bins
        }
    }

    // Stream progression: early on, be more exploratory (favor new bins slightly); late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        score -= 8.0 * progress;
    }

    // Prefer bins whose residual is small relative to mean (close-out bias)
    if bin_residual < bin_capacity {
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Reward near-perfect fits strongly (nonlinear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else {
        // Penalize residuals too small to ever be useful again.
        let min_useful = 10u32.min(bin_capacity);
        if post_residual < min_useful {
            score += 25.0;
        }
    }

    // Lookahead: penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * next_item_size as f64;
        } else if post_residual >= next_item_size && post_residual > 0 {
            score -= 6.0;
        }
        // Bonus if placing here lets the next item also fit this bin.
        if item_size + next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New-bin candidate: mild baseline penalty so we prefer reusing bins,
    // but relax it when many open bins already have large residuals (fragmentation).
    if is_new_bin {
        let frag = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 15.0 - 10.0 * frag - 10.0 * progress;
        // If no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for bins below mean residual (keeps big spaces available).
    if !is_new_bin {
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    // Late in the stream, tighten up: prefer exact packing, avoid spreading.
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, mildly damped by stream progress
    let mut score = norm_pr * (1.0 + 0.5 * progress * (1.0 - progress) * 4.0);

    // Non-linear polynomial coupling: penalize large residuals quadratically/cubically
    score += 0.8 * norm_pr * norm_pr + 0.6 * norm_pr * norm_pr * norm_pr;

    // Reward tight fits: smooth sigmoid-like bonus for very small post_residual
    let tight = (-norm_pr * 12.0).exp();
    score -= 1.5 * tight * (1.0 + progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = (pr - ni) / cap;
            score -= 1.2 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 0.5 * ((ni - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening a bin unless residuals are very fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score = 3.0 + 2.0 * fragmentation * (1.0 - progress) - 1.0 * progress;
    }

    // Mild penalty tied to open bin count to encourage consolidation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 equal classes.
    let class = (post_residual * 10) / bin_capacity; // 0..=9
    // Dead-space penalty grows super-linearly for small unusable remainders.
    let dead_threshold = bin_capacity / 10; // 10
    if post_residual > 0 && post_residual < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward exact/near fills (post_residual in low classes).
    score -= match class {
        0 => 8.0,
        1 => 5.0,
        2 => 3.0,
        _ => 0.0,
    };

    // Harmonic coupling with next item: reward if lookahead fits the post residual,
    // penalize if lookahead fits nowhere else but not here.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic pair: residual class matches next item size class.
            let next_class = (next_item_size * 10) / bin_capacity;
            if next_class == class { score -= 6.0; } else { score -= 2.5; }
        } else if next_item_size > bin_residual {
            // Next item cannot fit this bin either way; neutral.
        }
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 2.0; // placing here breaks a harmonic continuation
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Prefer tighter bins: deviation from mean residual.
    let residual_f = bin_residual as f64;
    score += 0.5 * (residual_f - mean_residual).max(0.0);

    // Modulo-based tie-breaking on post_residual granularity of 5.
    let rem = post_residual % 5;
    score += match rem {
        0 => -1.0,
        4 => 1.5,
        _ => 0.5,
    };

    // Late in the stream, consolidate: favor existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline plus pressure from open bins.
        score = bin_capacity as f64 * 0.5 + 4.0 * open_bins_count as f64 * (0.5 + progress);
        if fitting_bins_count > 0 {
            score += 6.0 * progress; // discourage new bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    // Items are 1..=100; small gaps (< ~10) are effectively dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Gaps that cannot fit the lookahead item waste the lookahead advantage.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward a residual that still fits the lookahead item (keeps future options open).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Perfect fit reward: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness ratio: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bin pressure: many open bins -> prefer filling existing bins, avoid spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 5.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    // (no fitting bins, or current bin fit would be terrible).
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 70.0; // must open a new bin
        }
        // Opening a new bin is more acceptable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Mean residual coupling: if open bins are already slack-heavy, discourage
    // leaving yet another moderately loose residual.
    if post_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect 2-step fit: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item could still fit here; reward proportional slack match.
            let diff = pr - ns;
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            // Penalize leaving a residual slightly larger than next item (wasted sliver).
            if diff > 0.0 && diff < 10.0 {
                score += 12.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to overshoot.
            score += 8.0 * (ns - pr).min(40.0) / 40.0;
        }

        // Coupling with mean residual: prefer bins whose post-residual tracks mean
        // (keeps bin residuals homogeneous, easier for future matches).
        let dev = (pr - mean_residual).abs();
        score += 0.15 * dev;
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.35 * mean_residual;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base + pressure - 10.0 * (1.0 - progress);
        // If next item exactly matches a fresh bin's leftover after this item, mild bonus.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Tight fits are always good: reward small post_residual relative to item size.
    score -= 20.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible future item are nearly worthless.
    if post_residual < 10 {
        score += 6.0;
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        // Residual can't hold the lookahead item -> mild penalty.
        score += 2.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 8.0; // perfect two-item packing
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish baseline; only prefer a new bin
    // when every open bin would leave large unusable residue.
    if bin_residual == bin_capacity {
        score = 45.0
            - 0.15 * mean_residual
            + 2.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item would fit with near-zero waste in an existing bin,
        // the tightness rewards above already push those bins below this.
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer reusing bins (consolidation), penalize spreading.
    if bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 4.0 * fit_ratio; // reward dense fills
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    }

    // Late-stream caution: as the stream progresses, slightly prefer keeping
    // residuals flexible (avoid ultra-tight but awkward splits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: mildly prefer tighter fits (quadratic in pr_norm).
    // Late in the stream: strongly penalize large residuals (cubic/quartic growth),
    // since fewer items remain to fill leftover space.
    let tightness = 1.0 - pr_norm;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress)
             + pr_norm * pr_norm * pr_norm * (4.0 * progress)
             + pr_norm * pr_norm * pr_norm * pr_norm * (6.0 * progress * progress);
    score += 20.0 * poly;

    // Smooth reward for near-perfect fits (small residual), stronger late in stream.
    score -= 10.0 * (1.0 - pr_norm * pr_norm) * (0.5 + 0.5 * progress);

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 unknown,
    // so use a smooth sigmoid around pr_norm < ~0.15) — waste regardless of progress.
    let dead = 1.0 / (1.0 + (pr_norm * 12.0 - 1.8).exp());
    score += 15.0 * dead * (0.6 + 0.4 * progress);

    // Lookahead coupling: if the next item could exactly fill the leftover,
    // strongly favor this bin (smooth Gaussian-like match).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 12.0 * (-(diff * diff) / 0.02).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the residual is truly unusable (smooth interaction with pr_norm).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // Slight preference to consolidate when many bins are open (smooth in count).
    let open_f = open_bins_count as f64;
    score += 0.5 * (open_f / (open_f + 5.0)) * pr_norm * cap;

    // Mild attraction toward bins with residual near the current mean residual
    // (keeps residual distribution homogeneous, smooth quadratic term).
    let mean_diff = (pr - mean_residual).abs();
    score += 0.05 * mean_diff * mean_diff / (cap.max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual in low classes is dead space
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residual classes that are hard to fill (post_residual in 1..=9)
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    }

    // Reward post_residual that is a "nice" harmonic fraction of capacity
    let fractions = [0u32, 10, 20, 25, 33, 40, 50, 60, 66, 75, 80, 90];
    for f in fractions {
        if post_residual == f {
            score -= 25.0;
        }
    }

    // Modulo-10 alignment: residuals divisible by 10 pair well with typical sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division thresholds: post_residual / 10 class
    let class = post_residual / 10;
    score -= class as f64 * 2.0;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            score -= 10.0 + (npost as f64) * 0.5;
            if npost <= 9 {
                score -= 20.0; // chain ends in small dead space, good
            }
        } else {
            // next item cannot follow here
            score += 30.0;
            if post_residual > 0 && post_residual < 20 {
                score += 30.0; // tiny dead space blocks lookahead
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size > 50 {
            score -= 55.0; // big items are fine in fresh bins
        }
        if post_residual > 0 && post_residual < 20 {
            score -= 25.0; // but avoid leaving tiny residuals in a fresh bin
        }
        // late in stream, prefer compacting into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Prefer fuller bins relative to mean residual
    score -= (mean_residual - pr) * 0.3;

    // Mild pressure to reuse existing bins when many are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item (<= 12) are nearly worthless; punish them hard.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    } else if post_residual < 40 {
        score += 4.0;
    } else {
        // Large residual is fine but slightly discourage wasting big space on small items
        score += 0.05 * (post_residual as f64 - item_size as f64).max(0.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual exactly anticipates the next item (lookahead k=2)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 15 {
        score -= 8.0;
    }

    // Open-bin pressure: fewer open bins preferred when fits are comparable,
    // but the LAST fitting bin should be strongly favored over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild pressure to close bins: penalize spreading across many open bins
    score += 0.8 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it unattractive unless the item fits terribly everywhere.
    // New bin has bin_residual == bin_capacity; post_residual = C - item is large,
    // so add a fixed penalty that tight fits overcome via their bonuses.
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post-residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - match_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space that will be wasted.
        score += 15.0;
    }

    // Perfect-fit bonus: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small unusable residuals (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, favor it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive if no open bin fits well (large item, low residual elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 8.0
            + 10.0 * (1.0 - progress)
            + if fitting_bins_count == 0 { -30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large dead space quadratically: small post_residual is best,
    // but perfect fits (0) should be strongly rewarded.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward near-perfect fits with a sharp bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement
    // (creates a useful residual). Otherwise penalize residuals that are too small
    // to be useful (dead space trap).
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
        // Chain fit: next item leaves room again -> very good packing.
        if post_residual >= next_item_size && (post_residual - next_item_size) >= 10 {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty for wasting a scarce resource when
    // alternatives exist; prefer tightest fit anyway via post_residual term.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state coupling: bins whose residual deviates favorably from the
    // mean residual are more attractive (balanced packing).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Early in the stream, allow opening new bins more freely to build a
    // diversified pool; late in the stream, squeeze into existing bins.
    let new_bin_bias = 8.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // Opening a new bin is bad if many bins already fit the item.
        score += 3.0 * fitting_bins_count as f64;
    } else {
        // Existing-bin discount grows over time.
        score -= 4.0 * progress;
    }

    // Prefer filling bins that are already mostly full (small residual relative to capacity).
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack (favor tight fits less); later, tighten aggressively.
    let coupling = 1.0 + progress * progress * (3.0 - 2.0 * progress); // smoothstep in [1,2]
    score *= coupling;

    // Dead-space penalty: residuals too small to be useful, smoothly weighted.
    let dead = (1.0 - norm_pr).powi(6); // peaks when post_residual ~ 0
    score += dead * cap * 0.05;

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual; penalize near-miss.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - (nxt / (pr + 1.0)).powi(2));
        } else {
            score += (nxt - pr).min(cap) * 0.06;
        }
    }

    // Prefer filling bins that are already below-average residual (more full).
    score -= (mean_residual - pr) * 0.15;

    // Mild dispersion pressure: many open bins -> prefer consolidating into fuller bins.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 0.5;

    // New-bin candidate handling: empty bin gets a calibrated handicap so it's
    // chosen only when open bins would leave poor fits.
    if bin_residual == bin_capacity {
        score += cap * (0.35 + 0.25 * progress) - 4.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual modulo 10 — small residues are dead space
    let r = post_residual % 10;
    if r == 0 {
        score -= 12.0; // perfectly harmonic residual, ideal for future items
    } else if r <= 3 {
        score += (4 - r) as f64 * 3.0; // tiny unusable slivers
    }

    // Integer division thresholds on post_residual
    if post_residual == 0 {
        score -= 20.0; // perfect fit
    } else if post_residual <= 10 {
        score += 6.0; // residual too small for min-size item
    } else if post_residual <= 20 {
        score += 2.0;
    }

    // Coupling with next item: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 8.0;
            }
            score += slack as f64 * 0.1;
        } else {
            // next item won't fit here anyway; penalize large leftover
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * progress;
        if item_size >= 50 {
            score -= 8.0; // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer bins tighter than the mean residual (better fill)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Penalize wasting a large residual on a small item when other bins could fit.
    if fitting_bins_count > 1 && fill_ratio < 0.5 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 - progress);

    // Prefer bins whose residual deviates from the mean (consolidate space).
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would NOT fit after this placement but would fit a new bin, penalize.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: keep it moderately attractive so poor fits open fresh bins,
    // but not so attractive that we ignore usable open bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is better when many bins already fit the item poorly.
        if fitting_bins_count > 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item almost fills the remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward small slack quadratically (tight packing for the future item).
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).powi(3);
    }
    // Post-residual too small for the next item: dead space risk.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }
    if next_item_size == 0 {
        // Last item: just prefer tightest fill.
        score -= 20.0;
    }

    // Compare against mean residual of open bins: bins with residual below
    // mean are "tight" — packing into them preserves large residuals elsewhere.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel); // tighter-than-average bin favored
        } else {
            score += 4.0 * (rel - 1.0); // looser-than-average bin penalized
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }
    // Many fitting bins: mild penalty to keep options open, avoid splashing.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // New-bin candidate: only attractive when item is large relative to
    // residual space or stream is early and bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else {
            0.0
        };
        // Penalize opening a new bin normally...
        score += 30.0;
        // ...but reward it when existing residuals are large/fragmented
        // (item won't pack well anywhere) or late in the stream is irrelevant.
        score -= 35.0 * fragmentation;
        // Large items relative to capacity favor a fresh bin.
        score -= 0.15 * item_size as f64;
    }

    // Slight global preference to fill existing bins as stream progresses.
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is the base; amplify small residuals.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the next item.
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin offers a decent fit. Penalize the empty bin moderately;
    // the tightness bonus can still let it win for very poor fits.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln_1p();
        score += 10.0 + 8.0 * open_pressure * (1.0 - 0.5 * progress);
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 40 {
            score -= 6.0;
        }
    }

    // Slight preference for bins deviating from the mean residual:
    // prefer filling bins that are already below-average full? Actually
    // prefer bins whose residual is below mean (more filled) to consolidate.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Small penalty for very large post-residuals that waste capacity.
    if post_residual > 50 {
        score += 0.2 * (post_residual - 50) as f64;
    }

    // Mild time-horizon coupling: early on, be more conservative (favor
    // consolidation); late, prioritize any fit to reduce waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear post_residual shaping: penalize large dead space super-linearly.
    score += (post / cap) * (post / cap) * 12.0;

    // Smooth interaction: tight fits rewarded more as stream progresses.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bin bonus (smoothly weighted).
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below mean residual (consolidating space).
    score += 0.08 * (mean_residual - bin_residual as f64).max(0.0);

    // Lookahead: reward leaving room for the next item if it fits after placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Mild penalty for opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes: residuals that are multiples of common item sizes are reusable
        let pr = post_residual;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= 15.0;
            }
        }
        // Small dead space (< 10, cannot hold any item) is pure waste
        if pr < 10 {
            score += 60.0;
        }
        // Lookahead coupling: reward if next item fits exactly into post_residual
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 250.0;
            } else if next_item_size < pr {
                let nr = pr - next_item_size;
                score -= 20.0;
                if nr % 10 == 0 {
                    score -= 10.0;
                }
                if nr < 10 {
                    score += 25.0; // chain would create dead space
                }
            } else {
                score += 12.0; // next item won't fit here either
            }
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize spreading across too many open bins when mean residual is high
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 8.0;
    }

    // Tight-fit reward: item nearly fills the bin
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.9 && bin_residual < bin_capacity {
        score -= 40.0 * fill;
    }

    // Mild exploration pressure over stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity (low waste fraction).
    score -= 50.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin before opening a new one: favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Penalize if post residual is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean in a useful way
    // (tighter-than-average bins get priority to close them out).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // New-bin candidate: only attractive when no open bin is a decent fit or bins are crowded.
    if bin_residual == bin_capacity {
        let bad_open = if fitting_bins_count == 0 { 0.0 } else {
            // penalty grows if open bins could fit well
            25.0 + (post_residual as f64) * 0.5
        };
        score += 20.0 + bad_open + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly
            let slack_after_next = post_residual - next_item_size;
            score -= 50.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize leaving a gap smaller than next item (dead space)
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 2.0 * gap;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize wasting a large bin on a small item when many bins are open
    let utilization = item_size as f64 / bin_residual as f64;
    score -= 100.0 * utilization;

    // Slight preference to fill existing bins more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * utilization;

    // New-bin candidate: make it attractive only when current bin fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many bins already open and mean residual is fragmented
        score = 120.0 - 0.3 * mean_residual;
        if post_residual == bin_capacity {
            // exact fit of next item in fresh bin
            if next_item_size as f64 >= mean_residual {
                score -= 150.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Penalize dead space: post residuals too small for any future item (min size 1, typical 10+).
    let dead = if post_residual < 10 { (10 - post_residual) as f64 } else { 0.0 };
    score += 8.0 * dead;

    // Lookahead: if next item fits exactly in post residual, strongly reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: only one fitting bin — avoid wasting it unless fit is excellent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 15.0 + 20.0 * (1.0 - progress) * scarcity;
        // Allow new bin late in stream if mean residual across bins is low (fragmented state).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins (larger item fraction used).
    score -= 5.0 * (item_size as f64 / bin_residual as f64);

    // Spread pressure: many open bins -> prefer consolidating into low-residual bins.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits with a smooth quartic of normalized post-residual
    let norm_post = post / cap;
    score -= 60.0 * (1.0 - norm_post).powi(4);

    // Non-linear penalty on residual relative to mean residual across open bins
    let mean = if mean_residual > 0.0 { mean_residual } else { cap };
    let ratio = post / mean;
    score += 12.0 * (ratio - 1.0).powi(2);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    } else {
        score += 5.0 * (fit - 1.0).sqrt();
    }

    // Lookahead coupling: reward leaving space that fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let tightness = (post - nxt) / cap;
            score -= 25.0 * (1.0 - tightness).powi(3);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Smooth stream-progress coupling: as stream advances, prefer filling existing bins
    score -= 20.0 * progress * (1.0 - norm_post);
    score += 8.0 * progress * (open / (open + 5.0));

    // Mild penalty for opening a new bin when others fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 18.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    // Penalize post-residuals that are "odd" harmonic classes (hard to fill later)
    if pr > 0 {
        score += residue * 0.6;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Small post_residual classes (1..=9) are dead space unless item is tiny
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Integer division thresholds: post_residual in [10,20) is a good harmonic band
    let band = pr / 20; // 0,1,2,3,4
    score -= (band as f64) * 3.0;

    // Next-item coupling: harmonic match between next_item_size and post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // exact lookahead fit
        } else if next_item_size < pr {
            let leftover = pr - next_item_size;
            // reward if leftover lands in a nice harmonic class (multiple of 10)
            if leftover % 10 == 0 {
                score -= 15.0;
            } else {
                score += (leftover % 10) as f64 * 0.5;
            }
        } else {
            // next item won't fit here; mild penalty scaled by excess
            score += ((next_item_size - pr) as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 && mean_residual < 25.0 { 1.0 } else { 0.0 };
        let base = 30.0 - frag * 45.0 + (open_bins_count as f64) * 0.5;
        score += base;
    }

    // Progress-scaled tiebreak: slight preference to fill older bins late in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0;

    // Deviation from mean residual: prefer bins below mean (fill fuller bins)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

