    // hold a future item (min size 1..=10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Bonus if the leftover gap can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap that just barely fails to fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a good fit exists; mild penalty per open bin.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Discourage new-bin candidate unless it's genuinely useful
    // (i.e., current bin fits are all terrible dead-space makers).
    if bin_residual == bin_capacity {
        // A fresh bin is fine when open bins are crowded or the fit is bad.
        let fit_quality = (bin_capacity as f64 - item_size as f64);
        score += 12.0 - fit_quality * 0.1;
        score += mean_residual * 0.15;
    } else {
        // Prefer bins tighter than average.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Slight stream-progression coupling: pack tighter as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
