    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tight the chain is
            score -= 200.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover space: penalize dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
