    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening new bins when open bins exist, more so early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 150.0 * (1.0 - 0.5 * progress);
        // but allow a new bin if no open bin can fit and item is large
        if fitting_bins_count == 0 && item_size > bin_capacity / 2 {
            score -= 100.0;
        }
    }

    // Mild preference for filling larger items into bins with less slack
    score += 0.1 * (item_size as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
