    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 15.0 * (-slack / 10.0).exp();
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = mean_residual / bin_capacity as f64;
        // Penalize new bins, less so when bins are nearly full or stream is late.
        score += 25.0 - 18.0 * crowdedness - 10.0 * progress;
        // If many bins can fit, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Mild preference for bins below mean residual (balance fragmentation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Open-bin count pressure: with many bins open, prefer filling existing ones.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: penalize leftover space, scaled by stream progress (dead space hurts more later)
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: tight fits rewarded, quadratic in normalized post-residual
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize bins with post-residual too small to ever be useful (dead space)
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 3.0 } else { 0.0 };
    score += dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // mild penalty when many alternatives exist, smooth in fit count
        score += 2.0 * (fit - 1.0).ln().max(0.0);
    }

    // Prefer bins with smaller residual overall (best-fit bias), smoothly weighted
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: reward if next item can use the post-residual, penalize otherwise
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Early stream: encourage opening fresh bins slightly less (consolidate early)
    score += 5.0 * (1.0 - progress) * (open / (open + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity-fraction bands.
    let q = post_residual / 10; // 0..10 classes
    let class_bonus: f64 = match q {
        0 => -60.0,                       // perfect fit
        1 => -35.0,                       // tiny gap, very reusable by small items
        2 => -20.0,
        3 => -8.0,
        4 => 0.0,
        5 => 6.0,                         // half-empty: awkward mid class
        6 => 2.0,
        7 => -5.0,
        8 => -12.0,
        9 => -18.0,
        _ => -25.0,                       // nearly empty bin: huge flexibility
    };
    score += class_bonus;

    // Modulo coupling: does post_residual + next_item_size land on a "nice" class?
    if next_item_size > 0 {
        let sum = post_residual + next_item_size;
        if sum <= bin_capacity {
            // lookahead fits: reward bins that can also host the next item
            score -= 10.0;
            // exact harmonic alignment: sum divisible by 25 (quarter-capacity lattice)
            if sum % 25 == 0 { score -= 12.0; }
            else if sum % 10 == 0 { score -= 6.0; }
        } else {
            // next item cannot use leftover: penalize dead space proportionally
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // prefer the tightest fit among many candidates (post_residual already does)
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline penalty so existing bins are preferred unless they are poor
        score += 25.0;
        // late in the stream, opening fresh bins is less attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // if many bins already open, discourage sprawl
        score += 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer using them
    score -= 0.05 * mean_residual;

    // Small-item guard: tiny items should fill the smallest residual available
    if item_size <= 15 {
        score += 0.1 * (bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // accept a meaningful item (min item size = 1, but "useful" threshold ~10)
    // are pure waste. Penalize small-but-nonzero gaps super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable sliver: heavy penalty growing as the gap shrinks.
            score += (10.0 - gap) * (10.0 - gap) * 3.0;
        } else if gap < 25.0 {
            // Marginal gap: likely to become dead space.
            score += (25.0 - gap) * 1.5;
        }
    } else {
        // Perfect fit: zero waste, strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: fill fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // If this bin is the ONLY fitting bin, strongly prefer using it over
    // opening a new bin (last-chance pressure).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another
    // one (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0 * open_bins_count as f64;
        // But if the lookahead item could pair with the leftover, a new bin
        // can be attractive: mild discount.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Mild pressure to consolidate into existing bins as bin count grows.
        score += open_bins_count as f64 * 0.3;
    }

    // Lookahead synergy: if the post-placement residual exactly matches the
    // next item, this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Early in the stream, slightly favor opening bins to build a good spread;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 8.0 - progress * 10.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // avoiding one bin absorbing all slack.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) super-linearly.
    if post_residual > 0 {
        score += 20.0 / (post_residual as f64).sqrt();
    } else {
        score -= 15.0; // perfect fit bonus
    }

    // 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + diff);
        // If next item fits exactly after this placement, strong reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize if next item cannot fit afterwards (dead end).
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 30.0;
    }

    // Prefer bins with residual below mean (dense bins) to keep spread bins usable.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Early in stream: keep bins open loosely; late: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Mild penalty on very high fragmentation potential.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // New-bin candidate: penalize slightly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the resulting residual, reward heavily;
    // if the residual is too small for any plausible next item, penalize dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.2 * pair_waste;
        } else {
            // Residual unusable by the known next item: penalize proportionally.
            score += 0.35 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize wasting space in nearly-empty bins unless it's a great fit:
    // a fresh bin should be kept for large future items.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    if fill_ratio < 0.5 && residual_ratio > 0.9 && post_residual > 20 {
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (post_residual large everywhere else
    // or few fitting bins) and the item is large.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 && fitting_bins_count > 0;
        let pressure = if decent_fit_exists {
            // If some open bin fits reasonably, discourage new bin...
            if (mean_residual - item_size as f64) <= 15.0 { 40.0 } else { 5.0 }
        } else {
            -15.0 // no good alternative: new bin is fine
        };
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let time_term = if progress > 0.8 && next_item_size > post_residual {
            8.0
        } else {
            0.0
        };
        score += pressure + time_term + 2.0 * open_bins_count as f64;
    }

    // Mild coupling with global mean residual: prefer bins below mean residual
    // (i.e., fuller bins) to consolidate packing.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic in normalized residual modulated by progress
    let coupling = (norm_pr * norm_pr) * (1.0 + progress) * cap;
    score += 0.35 * coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight = (1.0 - norm_pr).powi(3);
    score -= 18.0 * tight * (0.4 + 0.6 * progress);

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 6.0 + 0.25 * waste * (1.0 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still serve the lookahead item
        score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap).powi(2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (prefer balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference to consolidate into fewer bins early
    score -= 2.0 * (open_bins_count as f64).recip() * (1.0 - progress);

    // New-bin candidate: neutral baseline with smooth progress-dependent bias
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * progress * (1.0 - progress) * 4.0;
        score += 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: dead space in small classes is worse
    let r10 = post_residual % 10;
    let class_penalty: f64 = match r10 {
        0 => -4.0,          // perfectly quantized leftover
        1..=3 => 3.0,       // nearly unusable slivers
        4..=7 => 0.0,
        _ => 1.5,
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: waste tiers
    let q = post_residual / 10;
    score += match q {
        0 => 25.0,          // post_residual < 10: nearly dead bin
        1 => 8.0,
        2 => 2.0,
        3..=5 => 0.0,
        _ => -1.0,          // large leftover still usable
    };

    // Tight fit reward: post_residual small relative to capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score -= 12.0;
    } else if frac < 0.15 {
        score -= 4.0;
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;  // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic class of the post-chain residual
            let chain_r = (post_residual - next_item_size) % 10;
            if chain_r >= 1 && chain_r <= 3 {
                score += 2.5;
            }
        } else {
            score += 4.0;   // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin when it's not needed
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; cheaper early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress;
        // but attractive if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // fresh bin can host the next big item too
        }
    }

    // Mild preference to consolidate into bins below mean residual (balance avoidance)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Slight bias toward using more-opened bins to close them out
    if open_bins_count > 8 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 12.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += (21 - post_residual as i32) as f64 * 2.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the lookahead item could use this bin's residual better, discourage new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good open bin: opening is fine
        }
    }

    // Open-bin pressure: mild penalty scaling with number of open bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only when not a perfect fit.
    if post_residual > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead synergy: if the next item exactly fits the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step match: post_residual exactly fits the next item
        if post_residual == next_item_size {
            score -= 60.0 + 40.0 * (1.0 - progress);
        } else if next <= post {
            // Next item still fits in the leftover space: reward proportionally
            let fit_ratio = next / post.max(1.0);
            score -= 30.0 * fit_ratio * (1.0 - progress);
        } else {
            // Next item won't fit in the leftover: penalize large dead space
            let dead = (post - next).abs();
            score += 0.15 * dead;
        }

        // Coupling with mean residual: bins far from mean residual get adjusted
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect closure of the bin is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: mildly discouraged unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space less than moderate dead space (small gaps may combine later).
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + 0.05 * next_item_size as f64;
        } else {
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many fitting bins: mild penalty to prefer the tightest among them (handled by fit term),
    // but discourage wasting near-empty bins when alternatives exist.
    if fitting_bins_count > 2 && post_residual as f64 > mean_residual {
        score += 1.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let poor_fit = (post_residual as f64 > 30.0 && next_item_size > post_residual) as i32 as f64;
        let penalty = 15.0
            - 10.0 * scarcity
            - 6.0 * poor_fit
            - 2.0 * (1.0 - progress);
        score += penalty.max(-5.0);
    }

    // Slight preference for consolidating into bins with low mean residual (filling fuller bins).
    score += 0.02 * (mean_residual - post_residual as f64);

    // Mild penalty per open bin to encourage closure of nearly-full bins.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = 1.0 + progress * (x - 0.5) * (x - 0.5) * 4.0 - (1.0 - progress) * x * (1.0 - x) * 2.0;
    score *= poly;

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tight = (1.0 - x).powi(3);
    score -= tight * (10.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0);
        score += waste * (0.3 + 0.5 * progress) * (waste / cap);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 50.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild pressure to close out many open bins early
    score += open_bins_count as f64 * (0.5 + 1.0 * progress);

    // Penalize bins far from mean residual (encourage uniformity)
    score += (pr - mean_residual).abs() * 0.4;

    // Discourage opening new bins unless residual is truly unusable
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress + (x - 1.0).abs() * 0.0;
        score -= tight * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: bins whose post-residual falls into
    // "nice" residue classes mod 10 are more reusable by typical items.
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus: f64 = match class {
        0 => -18.0,           // exact multiple: perfect future fit
        1 | 9 => -6.0,
        2 | 8 => -3.0,
        3 | 7 => 2.0,
        4 | 6 => 5.0,
        _ => 9.0,             // class 5: half-capacity dead zone
    };
    score += class_bonus;

    // Integer-division thresholds: post_residual buckets by quarter capacity.
    let quarter = bin_capacity / 4;
    if pr < quarter / 2 {
        score += 25.0;        // tiny sliver: near-dead space
    } else if pr < quarter {
        score += 8.0;
    } else if pr <= bin_capacity / 2 {
        score -= 4.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
            // harmonic match of next item with post-residual class
            if pr % 10 == next_item_size % 10 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 3.0 * (next_item_size as f64 - pr as f64).min(40.0) / 40.0;
        }
    } else {
        // last item: just minimize waste
        score -= 15.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let open_penalty = (open_bins_count as f64).ln() * 6.0;
        if fitting_bins_count == 0 {
            score -= 40.0 + open_penalty;
        } else {
            score += 35.0 + open_penalty - 10.0 * pressure;
        }
    }

    // Prefer consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Mild preference toward bins below mean residual (balance avoidance of fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    // Treat residual < 10 (or < next item) as dead weight -> heavy penalty.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 1000.0; // perfect fill, excellent
    } else if (post_residual as f64) < dead_threshold + 15.0 {
        // small, likely-unusable gap: penalize hard on top of raw residual
        score += (dead_threshold + 15.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making new-bin candidate (bin_residual == bin_capacity) less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 25.0 + (open_bins_count as f64) * 6.0;
        // If lookahead item could combine with current item's leftover, soften slightly.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight reward scaled by how many bins are open.
        score -= (open_bins_count as f64) * 1.5;
    }

    // Prefer bins whose residual is close to the mean (keeps residual distribution balanced),
    // penalize outliers far below mean (fragments).
    let dev = bin_residual as f64 - mean_residual;
    score += dev.abs() * 0.3;

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (builds a better portfolio).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if the next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Prefer placements where next item consumes most of the remaining space.
            let next_tightness = 1.0 - (slack_after_next as f64) / (bin_capacity as f64);
            score -= 30.0 * next_tightness;
            // Bonus if next item leaves a near-zero residual (perfect 2-step chain).
            if slack_after_next <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use the leftover space: penalize dead space.
            score += 12.0;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals
    // close to (below) the mean to keep bin states homogeneous.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when good open bins exist, unless current
    // bin would leave large unusable dead space.
    if bin_residual == bin_capacity {
        // New empty bin: post_residual = capacity - item_size, large => high base
        // score already; add mild penalty so it's chosen only on tight fits.
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin can host this item and then the next one comfortably.
            let combined = item_size + next_item_size;
            if combined <= bin_capacity {
                score -= 35.0;
            }
        }
    } else {
        // Slight bonus for reusing existing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Small penalty proportional to number of open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily favor small post_residual (best-fit core).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Lookahead: if the next item can use the leftover space, bonus; otherwise penalize dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain-friendly placement: leftover can host next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: dead space penalty grows with tightness
            let waste = post_residual as f64;
            score += waste * waste / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global pressure: many open bins with small mean residual -> consolidate into existing bins.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += pressure * 0.05;

    // New-bin candidate handling: empty bin gets a base penalty so it's chosen only
    // when all existing fits are poor (high post_residual / dead space).
    if bin_residual == bin_capacity {
        score += 30.0;
        // early in stream, opening bins is cheaper; late in stream, avoid proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if next item is large, a fresh bin may be valuable
        if next_item_size >= item_size && next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild reward for filling bins that are already mostly full (fragmentation avoidance).
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * used * used;

    // Slight time-horizon modulation: as stream nears end, tighten packing aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a non-linear convex penalty
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);

    // Polynomial coupling with stream progress: waste matters more later
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * 8.0 * pr_norm * (1.0 - pr_norm);

    // Reward tight fits (post_residual small relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness;

    // Penalize residual that cannot fit the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 * ((next_item_size - post_residual) as f64) / cap;
    }
    // Reward residual that fits next item snugly
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit = next_item_size as f64 / pr.max(1.0);
        score -= 3.0 * fit * (1.0 - fit);
    }

    // Last-chance bonus: avoid opening new bins when few fit
    if fitting_bins_count <= 1 {
        score -= 5.0 * (1.0 - late);
    }

    // Slight preference for consolidating into bins below mean residual
    score += 0.5 * (mean_residual - pr);

    // New-bin candidate: make it attractive only when item is large and late
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score = 20.0 * (1.0 - late) + 30.0 * (1.0 - size_frac) * size_frac * 4.0
            - 10.0 * late * size_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: dead space quantization.
    // Residuals that are multiples of small units are more reusable.
    let pr = post_residual;
    let class_bonus = match pr % 10 {
        0 => 8.0,
        5 => 4.0,
        1 | 9 => 1.0,
        _ => 0.0,
    };
    score -= class_bonus as f64;

    // Integer-division thresholds: residuals in "useful bands".
    let band = pr / 20; // 0..5
    let band_reward = match band {
        0 => -6.0,          // 0..19: nearly full, great
        1 => 2.0,           // 20..39: awkward zone
        2 => 0.0,
        3 => -1.0,
        _ => 3.0,           // 80..100: barely used bin
    };
    score += band_reward;

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap_f);
        if pr == next_item_size {
            score -= 12.0; // perfect chaining
        }
    } else if next_item_size > pr {
        // next item won't fit here: penalize leaving a residual too small for it
        if pr > 0 && pr < next_item_size {
            score += 4.0 * (next_item_size as f64 - pr as f64) / cap_f;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap_f * 0.85;
        // Cheaper to open a bin early when many bins already open and mean residual is high.
        score -= 0.05 * open_bins_count as f64;
        score += 0.1 * (mean_residual - cap_f / 2.0).max(0.0);
        // If the item is large relative to capacity, opening fresh is fine.
        score -= 0.2 * item_size as f64;
        // Lookahead synergy: fresh bin accommodates next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.02 * open_bins_count as f64;

    // Slight progression bias: later in stream, tighten more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (1.0 - post_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 18.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tight fit bonus relative to bin capacity.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 8.0;

    // Open bins pressure: prefer spreading when many bins are open,
    // but keep compactness when few bins exist.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (open_bins_count as f64).powf(0.65) * 1.5 * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size > 60 && post_residual < 40 && open_bins_count > 0 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual gap,
    // this placement chains nicely; otherwise penalize leaving a gap
    // that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Mean residual coupling: bins far below the mean residual are less
    // attractive targets when the mean is small (compact streams).
    if (bin_residual as f64) < mean_residual * 0.5 && mean_residual < 30.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can host the next item exactly or nearly so.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 300.0 - (slack as f64) * 15.0;
            }
            // Penalize large leftover after a hypothetical next placement.
            score += (slack as f64) * 0.4;
        } else {
            // Next item cannot fit here after placement; mild penalty scaled
            // by how far off it is.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 1.5;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins that end up tighter than average (wasting less space).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when this item would leave a bad
    // fit in every existing bin (large dead space) or few fitting bins.
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        score += 60.0; // base cost of opening a new bin
        if dead < 20.0 {
            score += 400.0; // don't open a bin for a near-perfect existing fit
        }
        if next_item_size > 0 && (next_item_size as f64) <= dead {
            score -= 150.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Slight preference for filling bins earlier in the stream to keep
    // open-bin count low.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward low post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        let exact = if gap < 0.5 { 25.0 } else { 12.0 * (1.0 - gap / bin_capacity as f64) };
        score -= exact;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover: penalize proportionally to wasted space.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
        if post_residual < 10 {
            score -= 6.0; // nearly perfect fill, very strong reward
        }
    }

    // Penalize opening new bins when open bins have plenty of room; encourage new bin when fragmented.
    if bin_residual == bin_capacity {
        // New-bin candidate: base score is high; only attractive when existing bins are fragmented
        // or the item is large relative to typical residual.
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0;
        score -= 18.0 * fragmentation * fragmentation;
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        score -= 5.0 * (1.0 - progress); // early stream: new bins more acceptable
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
    } else {
        // Existing bin: prefer bins with residual below mean (consolidate small leftovers),
        // penalize bins far above mean (keep large spaces for large future items).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * dev;
        // Very large leftover after placement is dead space unless lookahead uses it.
        if post_residual > 50 && (next_item_size == 0 || next_item_size > post_residual) {
            score += 4.0;
        }
        // Mild bonus for using bins when many are open (bin consolidation).
        score -= 0.3 * open_bins_count as f64;
    }

    // Time horizon: late in stream, be greedier about tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: residual waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in stream: mildly favor larger residuals (keep bins flexible).
    // Late in stream: strongly favor tight fits (small post_residual).
    let prn = pr / cap; // normalized post residual in [0,1]
    let phase = progress * std::f64::consts::PI;
    let early_weight = 0.5 * (1.0 + phase.cos()); // 1 -> 0
    let late_weight = 0.5 * (1.0 - phase.cos());  // 0 -> 1

    score += early_weight * 8.0 * prn * prn;
    score -= late_weight * 12.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Smooth coupling: quadratic interaction between fill ratio and progress
    let fill = 1.0 - prn;
    score -= 6.0 * fill * fill * progress;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_quality = 1.0 - gap / cap;
        if pr >= nxt {
            score -= 10.0 * fit_quality * fit_quality * (1.0 - progress);
        } else {
            score += 4.0 * (gap / cap);
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn * prn);
    }

    // Crowd penalty: many open bins -> prefer filling existing ones
    let crowd = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score += 5.0 * crowd * prn;

    // Mean residual coupling: penalize bins far from mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls in
    // "useful" residue classes (multiples of 10, and small leftovers) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // exact decade leftovers are highly reusable
        if class == 0 {
            score -= 12.0;
        } else if class <= 3 {
            // tiny dead space: penalize proportionally
            score += (4 - class) as f64 * 3.0;
        } else if class >= 7 {
            score -= 4.0; // close to next decade, still usable
        }
    } else {
        // perfect fit
        score -= 40.0;
    }

    // Integer-division thresholds on post_residual: chunk the leftover space.
    let chunk = pr / 20; // 0..5
    score -= chunk as f64 * 5.0;

    // Coupling with lookahead item: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0;
            // extra reward when next item exactly matches a residue class of pr
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // leftover cannot host the next item: penalize dead space
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large and no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins mildly, more so early when bins are cheap to keep open
        score += 30.0 + 20.0 * (1.0 - progress);
        // but if the item is huge and would leave a bad residue, opening fresh helps
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean residual context: if this bin's residual is far below mean, it is
    // already tight — prefer filling tight bins first.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Slight preference for bins that are already committed (fewer open bins better)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward residual that can still hold the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize wasting a nearly-full bin when other bins fit
    if bin_residual < 25 && fitting_bins_count > 1 {
        score -= 15.0;
    }
    // Last-chance bin pressure: strongly favor using it rather than opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Open-bin pressure: with many open bins, discourage opening new ones
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }
    // Mean residual coupling: if average slack is high, prefer filling bins with slack
    if !new_bin && (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 10 {
                score -= 250.0 - (chain_residual as f64) * 10.0;
            } else {
                score -= 60.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to the mismatch.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    }

    // Compare residual against mean residual: tighter-than-average bins are precious.
    let dev = (bin_residual as f64) - mean_residual;
    if dev < 0.0 {
        score += dev * 0.8; // tighter bins get lower score
    } else {
        score += dev * 0.3; // looser bins mildly penalized
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when current bin would leave large dead space
    // or when the item fits almost perfectly elsewhere is impossible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 + 50.0 * (1.0 - progress);
        // If lookahead chains perfectly into a fresh bin, discount the opening cost.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0;
        }
        // If no open bin can fit the item, new bin is natural.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for filling existing bins as the stream progresses.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can fit into the leftover space -> reward.
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Bad: leftover is unusable for the next item -> penalize dead space.
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean residual (tighter bins first).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more willing to open fresh bins for large items;
    // later, consolidate aggressively to avoid fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (60.0 - 40.0 * progress);

    // A new bin is attractive only if the item is large relative to capacity.
    score -= new_bin * 40.0 * (item_size as f64 / bin_capacity as f64);

    // If the next item is large and this bin would be nearly emptied, keep space for it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 12.0 * x * x * (1.0 - progress);
    score += 9.0 * x * x * x * progress;
    score -= 6.0 * x * (1.0 - x) * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_quality * fit_quality * (0.4 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress) + 4.0;
    }
    // Reward residual that accommodates the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - x);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Mean residual alignment: prefer bins near the mean
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (1.0 + progress);

    // Mild preference for consolidation as open bins grow
    score += 0.5 * open_bins_count as f64 * x * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse modulo partition of the capacity space
    let item_class = item_size / 10;           // 1..=10 (0 possible for size<10)
    let residual_class = post_residual / 10;   // how much usable space remains in classes

    // Reward tight fits: post_residual near zero is ideal
    score -= 15.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // Penalize post_residuals that fall into "dead zones": small but unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // fragments below the minimum item size are dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // only tiny items can use it later
    }

    // Harmonic coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain packing possible; reward proportionally to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize more if leftover is nearly dead
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    } else {
        // Last item: prefer any bin, minimize residual
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Mean residual coupling: bins with residual far below mean are "almost full";
    // filling them fully is good, but leaving them near-mean waste is bad
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev; // prefer bins with lower-than-mean residual (closer to full)

    // Modulo-threshold logic on residual class: residuals that are multiples of
    // common item sizes (10/20/25/50) are more reusable
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 2.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Perfect fit is a hard win
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: neutralize its raw residual advantage so it only wins
    // when no open bin offers a decent fit. Bias scales with stream progress and
    // how many bins can otherwise take the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * (1.0 - progress) + 5.0 * (fitting_bins_count as f64);
        // If even the best existing fit leaves a dead fragment, allow new bin
        if fitting_bins_count >= 1 && post_residual == 0 {
            // (post_residual==0 can't happen for empty bin; keep guard for symmetry)
        }
        // Penalize opening a new bin when the item is small (wastes capacity)
        if item_size <= 30 {
            score += 15.0;
        }
    }

    // Early stream: be slightly more conservative with fragmentation
    if step_index < total_items / 4 && post_residual > 0 && post_residual < 15 {
        score += 5.0;
    }

    // Small tie-breaking on residual class for determinism-free smoothness
    score -= 0.01 * residual_class as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward fits that leave room for the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap the next item cannot use is dead space.
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // opening a new one (empty candidate) is relatively more attractive.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or fit is poor elsewhere.
        score -= 20.0 - pressure * 2.0;
        if post_residual > 20 {
            score += 10.0;
        }
    } else {
        // Slight bonus for using existing bins as pressure grows.
        score -= pressure.min(10.0) * 1.5;
    }

    // Prefer bins tighter than the current mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Late in the stream, tighten up: penalize wasted space more heavily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 / (1.0 + diff);
        // Strong reward for exact match with next item.
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize post_residual that is too small for the next item
        // (dead space unusable by lookahead item).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    // (fill crowded bins first, keep loose bins flexible).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for wasting a fresh bin.
        score += 400.0;
        // If several bins fit, definitely prefer reusing one.
        if fitting_bins_count >= 1 {
            score += 100.0 * fitting_bins_count as f64;
        }
        // But if the item is large relative to capacity, a fresh bin
        // may be worthwhile to avoid fragmentation.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 300.0 * frac;
        // Early stream: keep bins open, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
        // If next item is large and nothing fits it well later, fresh bin
        // with room for it is good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 120.0;
        }
    } else {
        // Slight preference for bins that remain useful for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // Penalize leaving very small unusable slivers.
        if post_residual > 0 && post_residual < 10 {
            score += 50.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit tightness: reward placements that leave little waste, but only
    // when the waste is truly unusable (dead space < typical small item).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Dead-space penalty: residual space that is too small to hold even the
    // smallest plausible future item is pure waste; penalize it extra hard.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Lookahead: strongly reward bins whose post_residual exactly accommodates
    // the next item (perfect chaining), mildly reward if next item fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; the leftover is likely dead space,
            // but severity scales with how close it came (near-miss is worse).
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.5 * gap;
        }
    } else {
        // Last item in stream: minimize waste as much as possible.
        score -= 15.0 * tightness;
    }

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global pressure: when many bins are open, discourage opening new bins
    // and encourage consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * pressure * (1.0 - progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier bin; using it consolidates small leftovers.
    let bin_res_f = bin_residual as f64;
    let deviation = mean_residual - bin_res_f;
    score += 0.15 * deviation;

    // Time horizon: late in the stream, be more conservative about leaving
    // awkward residuals (fewer chances to fill them).
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: an empty bin has maximal residual; make it moderately
    // attractive when nothing fits well, but not preferred over decent fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream with many open bins, opening new bins is costly.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear reward for tight fits: post_residual^2 normalized by capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tight = (pr * pr) / (cap * cap);
    score -= 40.0 * tight;

    // Smooth coupling of tightness with stream progress:
    // late in the stream, tight fits matter even more
    score -= 25.0 * tight * (progress * std::f64::consts::PI).sin().abs();

    // Penalize residuals that are too small to ever fit the smallest item (dead space)
    let dead = if pr < 1.0 { 0.0 } else { ((pr - 1.0).max(0.0) / cap).powf(0.5) };
    score += 10.0 * (1.0 - dead);

    // Lookahead: reward when next item fits the post-residual (chaining)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 15.0 * (1.0 - (ni / cap)) * (1.0 + progress);
        } else {
            // gap between next item and residual: mild penalty scaled by gap
            score += 8.0 * ((ni - pr) / cap);
        }
    }

    // Last-chance bin: strong bonus so we don't waste the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: only prefer opening a new bin when
    // existing bins fit poorly (post_residual high relative to capacity)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty for proliferation, relaxed when many bins are open
        let mut nb = 20.0;
        nb -= 10.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
        // If this bin would leave a very poor residual in every other bin,
        // opening fresh is fine: smooth relaxation via mean_residual
        let mean_gap = ((mean_residual - item_size as f64).max(0.0)) / cap;
        nb -= 25.0 * mean_gap * mean_gap;
        // Late in the stream, prefer closing bins out (keep new-bin penalty)
        nb *= 1.0 + 0.5 * progress;
        score += nb;
    } else {
        // Mild reward for using already-open bins, stronger with progress
        score -= 3.0 + 4.0 * progress;
        // Penalize bins far below mean residual (fragmentation avoidance)
        let dev = (mean_residual - pr) / cap;
        score += 6.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: quadratic in post_residual (small residual strongly favored).
    score -= (cap - post) * (cap - post) / (4.0 * cap);

    // Harmonic classes on post_residual: bins whose residual lands in "usable"
    // classes (multiples of 10, or >= 30) are more valuable to keep tight.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 6.0,
            1..=5 => 2.0,
            _ => 0.5,
        };
        score -= class_bonus;
        // Residuals that can still host common future sizes (>= 20) keep value.
        if pr >= 20 {
            score -= 3.0;
        }
        // Integer-division thresholds: residual bucket by quarter-capacity.
        let quarter = (pr * 4) / bin_capacity.max(1);
        score -= quarter as f64 * 1.5;
    } else {
        // Perfect fill: huge reward.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize leaving a mid-sized dead zone.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // bins would leave large residuals or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_if_open = post; // = capacity - item_size
        // Penalize new bins proportionally to wasted space and mean residual slack.
        score += waste_if_open * 0.8;
        score += mean_residual * 0.3;
        score -= (1.0 - progress) * 5.0;
        // If item is large relative to capacity, a fresh bin is more acceptable.
        score -= (item_size as f64 / cap) * 10.0;
        // Many open bins with slack => avoid opening another.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Slight preference for more-filled bins among open candidates.
        score += (bin_residual as f64 / cap) * 2.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter than average).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32; // interface allows items down to 1
    let dead = post_residual < min_item;
    if dead {
        score -= 1000.0; // perfectly sealed bin is ideal
    } else {
        // Penalize small unusable gaps super-linearly: a gap that can't fit
        // typical mid-size items is likely dead space later.
        let gap = post_residual as f64;
        if gap <= 20.0 {
            score += 40.0 * (20.0 - gap);
        } else if gap <= 40.0 {
            score += 8.0 * (40.0 - gap) + 0.5 * (gap - 20.0);
        }
    }

    // Reward exact/waste-free fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness reward: prefer bins where the item consumes a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: fewer open bins is better; penalize spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: only allow opening a new bin when existing fits are poor
    // (high mean residual fragmentation or no tight fit available).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin.
        score = 150.0 + post_residual as f64;
        // If current bins are fragmented (mean residual low but many bins), opening
        // a new bin is attractive.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If the next item is large, a fresh bin preserves flexibility.
        if next_item_size > 50 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the post residual exactly fits the next item, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 20.0; // next item can still fit comfortably
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if next item exactly fills remaining space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large leftover space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 50.0;
        }
    }

    // Penalize small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * 0.35;

    // Penalize dead space: small but nonzero post_residual is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 - (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item cannot use this bin's leftover: mild penalty for large leftover.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Prefer filling bins that are already small-residual (consolidate).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += residual_frac * residual_frac * 10.0;

    // Time horizon: early on, be more willing to open new bins (explore);
    // late in the stream, strongly prefer existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    // Global state: many open bins with high mean residual -> favor using them.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no good fit exists; penalize default new-bin slightly otherwise.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 12.0 - item_frac * 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize wasted space, with non-linear (quadratic/cubic) shaping
    let mut score = pr as f64;
    score += 20.0 * x * x * (1.0 - x); // penalize mid-range waste, tolerate tiny residuals
    score -= 15.0 * x * x * x;          // reward near-full packing

    // Smooth stream-progress coupling: tighten packing as stream advances
    score *= 1.0 + 0.6 * progress * (1.0 - x);

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 25.0 * nx * (1.0 - progress) + 12.0 * nx * progress;
    } else if next_item_size > post_residual && post_residual > 0 {
        // penalize leaving residual that cannot host the next item
        score += 8.0 * (1.0 - x) * (0.5 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln_1p();
    }

    // New-bin candidate: only attractive when open bins are poorly utilized
    if bin_residual == bin_capacity {
        let gap = (mean_residual - item_size as f64).abs();
        score = 60.0 + 0.5 * gap + 30.0 * progress * (1.0 - mean_residual / cap);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with a large follow-up item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let quarter = bin_capacity / 4;              // 25
    let eighth = bin_capacity / 8;               // 12
    let pr = post_residual;

    // Dead-space penalty: residuals that no plausible item (1..100) can use well.
    if pr == 0 {
        score -= 60.0; // perfect fit — strongly reward
    } else if pr <= eighth {
        // 1..12: nearly full, small waste
        score -= 20.0 - (pr as f64) * 0.5;
    } else if pr <= quarter {
        // 13..25: usable by small items, moderate
        score -= 8.0;
    } else if pr <= quarter * 2 {
        // 26..50: half-empty bin, risky
        score += 6.0;
    } else {
        // >50: leaves a big hole
        score += 14.0;
    }

    // Modulo-arithmetic coupling: residual divisible classes
    let rem8 = pr % 8;
    if rem8 == 0 {
        score -= 3.0; // nicely aligned residual
    } else if rem8 <= 2 {
        score -= 1.0;
    } else if rem8 >= 6 {
        score += 1.5;
    }

    // Lookahead: can the next item fit exactly into the resulting residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // chained perfect fit
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= eighth {
                score -= 6.0; // near-perfect chain
            } else if slack > quarter * 2 {
                score += 4.0; // next item leaves a big hole
            }
        } else {
            // next item can't fit here: residual must serve future items
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Tightness preference among multiple fitting bins: reward best fit
        score += (bin_residual - item_size) as f64 * 0.15;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost; make it unattractive unless
        // all open bins would be badly fragmented by this item.
        let mut bad_fragmentation = true;
        if fitting_bins_count == 0 {
            bad_fragmentation = true; // forced anyway
        } else if post_residual <= quarter {
            // placing in an open bin leaves a small residual -> keep it
            bad_fragmentation = false;
        }
        score = if bad_fragmentation { 20.0 } else { 120.0 + mean_residual * 0.3 };
        // Late in the stream, slightly prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference to fill bins more evenly when many bins are open
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Small stream-progress modulation: early on, keep residuals flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.25 && pr > quarter {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // (min item size is 1, but tiny gaps waste capacity). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward near-perfect fits superlinearly.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling with next item lookahead: if the next item fits exactly in
    // the post-residual, this placement is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0; // leaves another dead sliver for the next item
        }
    }

    // New-bin candidate detection: strongly discourage opening a new bin
    // when any open bin fits, unless pressure is high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 15.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        // If this bin is the last chance, allow new bin more readily.
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 30.0;
        }
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it to avoid opening a new bin.
        score -= 30.0;
    }

    // Open-bins pressure: prefer filling already-open bins, especially when
    // many are open (fragmentation risk grows with count).
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if mean residual is large, prefer bins with
    // residual far from mean (consolidate waste in one place).
    let bin_resid = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (bin_resid - mean_residual).abs();
    }

    // Mild reward for using tighter bins (smaller residual before placement).
    score += 0.05 * bin_resid;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: does the NEXT item fit into the post-residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item fits here after this placement: reward chaining.
            let chain_quality = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 12.0 * chain_quality;
        } else {
            // Next item will NOT fit here: penalize leaving a near-miss gap.
            let miss_gap = nxt - post_residual as f64;
            if miss_gap < 15.0 {
                score += 8.0 * (1.0 - miss_gap / 15.0);
            } else {
                score += 1.5;
            }
        }
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Compare against mean residual: avoid consuming bins with large residuals badly,
    // favor bins whose residual is close to the item size (good match).
    let match_quality = 1.0 - ((bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64);
    score -= 4.0 * match_quality;

    // Penalize bins whose residual is far above the mean (hoarding large residuals).
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 2.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 6.0;
        // If many bins fit, discourage opening new bins.
        if fitting_bins_count > 0 {
            score += 4.0 * (fitting_bins_count as f64).min(6.0);
        }
        // Late in stream, prefer closing out open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 40 {
            score -= 3.0;
        }
    }

    // Mild penalty for many open bins (consolidation pressure).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits non-linearly.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Penalize small useless post_residual gaps that can't host typical items.
    if post_residual > 0 && post_residual < 12 {
        score += 8.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for near-perfect chaining.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to leftover.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidating into emptier ones.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is much emptier than average, slight penalty (save it for big items).
    let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * diff * (item_size as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline; only chosen when all fits are bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.65 - 10.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // new bin accommodates future large items
        }
        if progress > 0.9 {
            score += 5.0; // avoid spawning bins near the end
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth progress coupling: tighten residual tolerance as stream advances.
    let progress_pressure = 1.0 + 3.0 * progress * progress;
    score *= progress_pressure;

    // Lookahead: reward if next item fits into post_residual (smooth sigmoid-like term).
    if next_item_size > 0 {
        let fits = pr >= next_item_size as f64;
        let margin = (pr - next_item_size as f64) / cap;
        let bonus = if fits {
            -2.5 * (1.0 - margin).max(0.0)
        } else {
            1.5 * (-margin).min(1.0)
        };
        score += bonus * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Among many candidates, mildly prefer tighter fits.
        score += 0.5 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // New-bin candidate: make it attractive only when residuals across bins are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_gap = (mean_residual / cap - 0.5).max(0.0);
        score = cap * 0.6 + mean_gap * cap - 3.0 * progress;
    } else {
        // Penalize placements leaving residuals close to but below typical small items.
        let dead_zone = (norm_pr - 0.15).abs();
        score += 0.8 * (-dead_zone * 12.0).exp();
    }

    // Mild open-bin economy: discourage spreading across too many bins early.
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals divisible by common item sizes
    // (or their halves) are more reusable, so reward them.
    let r = post_residual;
    if r > 0 {
        let mut reuse_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 {
                reuse_bonus += 6.0;
            }
        }
        // exact power-of-two-like fractions of capacity are prime targets
        if r == bin_capacity / 2 { reuse_bonus += 8.0; }
        if r == bin_capacity / 4 { reuse_bonus += 5.0; }
        score -= reuse_bonus;
    }

    // Penalize tiny dead space that nothing (min size 1..10) can use well
    if r < 10 && r > 0 {
        score += 25.0;
    }

    // Perfect fit: zero residual is ideal
    if r == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == r {
        score -= 90.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // next item fits: reward proportional to tightness
        score -= 20.0 * (1.0 - (r - next_item_size) as f64 / r as f64);
    } else if next_item_size > r && r > 0 {
        // next item cannot use the leftover: penalize by leftover size class
        let leftover_class = (r / 10) as f64;
        score += 3.0 * leftover_class;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening bins when decent fits exist,
    // unless the item is huge and residuals are all poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = fitting_bins_count == 0
            || (item_size as f64 / bin_capacity as f64) > 0.6 && mean_residual < item_size as f64;
        if poor_fits {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 35.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Prefer filling bins with larger mean residual (consolidate emptier bins)
    score -= 0.05 * mean_residual;

    // Slight preference for bins whose residual class matches item class
    if bin_residual != bin_capacity && (bin_residual / 10) == ((item_size + 9) / 10) {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable dead space (gaps below typical min item size)
    if post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // tiny gaps: near-zero residual is actually perfect fit
        if post_residual == 0 {
            score -= 200.0; // perfect fit reward
        }
    }

    // Penalize moderate dead space that likely can't be filled by lookahead
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.9 {
        score += 25.0;
    }
    // Reward when lookahead item fits into post_residual
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones, avoid new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 2.0; // opening a new bin gets costly as bins accumulate
    } else {
        score -= pressure * 0.3;
    }

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Slightly prefer bins below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let perfect_fit = (post_residual as f64 / bin_capacity as f64).powi(4);
    score -= 60.0 * perfect_fit;

    // 2-step lookahead: reward residuals that exactly accommodate the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Small slack after next item is good; large slack wastes space.
            score -= 20.0 * (-slack / 15.0).exp();
            score += 0.15 * slack;
        } else {
            // Next item cannot follow into this residual: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 10.0 * perfect_fit;
    }

    // Relative to mean residual: bins tighter than average are precious, use them well.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize the fresh-bin candidate mildly unless it enables an exact two-item pack.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    } else {
        // Last item in stream: prefer filling existing bins maximally.
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Prefer filling bins that are already relatively full compared to mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early in the stream, be more willing to open new bins; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
        score += 30.0 * progress;
    }

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by small common item sizes (e.g. 10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus -= 60.0; // perfect fill, ideal
    } else if pr % 10 == 0 {
        bonus -= 12.0;
        if pr % 20 == 0 { bonus -= 6.0; }
        if pr % 50 == 0 { bonus -= 6.0; }
    } else if pr % 25 == 0 {
        bonus -= 9.0;
    } else if pr < 10 {
        bonus += 25.0; // dead space below minimum item size
    }

    score += bonus;

    // Harmonic compatibility with the next item (lookahead k=2)
    if next_item_size > 0 && pr >= next_item_size {
        // next item fits exactly or into a harmonic class of the residual
        if pr == next_item_size {
            score -= 40.0;
        } else if (pr - next_item_size) % 10 == 0 {
            score -= 15.0;
        } else if (pr - next_item_size) < 10 {
            score += 20.0; // leaves dead space after next item
        } else {
            score -= 5.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here regardless; slight penalty scaled by overflow
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Integer-division threshold on post_residual: prefer residuals >= 50 (half capacity)
    let half_class = pr / 50; // 0 or 1
    score -= half_class as f64 * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are fragmented
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = bin_capacity as f64 * 0.9;
        // discount if open bins are too full/fragmented to absorb item well
        let frag = mean_residual / bin_capacity as f64;
        if frag < 0.25 {
            score -= 20.0; // bins nearly full, new bin fine
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // existing bin: reward tight fits (small post_residual) already in base score
        // mild penalty if many bins compete, prefer spreading via tightness only
        score += (item_size as f64 / bin_capacity as f64) * 5.0;
    }

    // Prefer bins below mean residual (consolidate emptier space)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are pure waste — penalize them quadratically.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 4.0 + 20.0;
    }

    // Perfect fits are golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose leftover can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover too small for the next item: mild dead-space penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh bins; favor consolidating into existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // and the item would fit somewhere else.
        score += 25.0 + pressure * 6.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Existing bin: mild reward proportional to how full it already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 12.0;
    }

    // Prefer bins tighter than average (better consolidation).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (best-fit core).
    score += (bin_residual as f64 - item_size as f64) * 0.01;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect match: post_residual exactly fits the next item -> big reward.
        if post == next {
            score -= 40.0;
        } else if post > next {
            // Next item fits after this placement: reward closeness of match.
            let slack = post - next;
            score -= 15.0 / (1.0 + slack / 20.0);
            // Penalize leaving a large gap larger than next item can't use.
            score += slack * 0.05;
        } else {
            // Next item won't fit in the leftover: penalize dead space, more so
            // if the gap is small (wasted potential) relative to mean residual.
            let gap = next - post;
            score += gap * 0.08;
            if post < 10.0 {
                score += 8.0; // nearly unusable sliver
            }
        }

        // Coupling with mean residual: if this bin's post-residual deviates
        // favorably (smaller) from mean residual, prefer it.
        score += (mean_residual - post) * 0.03;

        // Late in the stream, tighten lookahead influence to consolidate bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += post * 0.02 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins among many open bins (reduce fragmentation).
    if open_bins_count > 4 && post_residual > 0 {
        score += (post_residual as f64) * 0.01 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 0.6 * (next_item_size - post_residual as u32) as f64;
        }
        // Reward bins whose leftover can exactly accommodate the next item
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bonus: only one fitting bin, prefer using it over opening new
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: make fresh bins moderately attractive only
    // when no good fit exists (post_residual large means poor current fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = 1.0 + 0.5 * (1.0 - progress);
        // Base new-bin score slightly above a perfect fit, below bad fits
        score = 0.5 * (bin_capacity as f64) * openness
            + 0.3 * mean_residual
            - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin can host the bigger next item too
        }
    }

    // Mild preference for bins below mean residual (consolidating fuller bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight penalty for very small leftovers that are hard to ever fill
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth polynomial coupling with stream progress:
    // early on, keep bins flexible (moderate residuals OK); late, demand tight fits.
    let tightness = 0.5 + 1.5 * progress;
    score += tightness * pr * x;

    // Cubic term: heavily punish large dead space as stream matures
    score += 60.0 * x.powi(3) * (0.3 + progress);

    // Reward using a bin that is the only fitting option (avoid opening new bin needlessly)
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_ratio = nx / pr.max(1.0);
            score -= 20.0 * fit_ratio * (0.5 + progress);
        } else {
            // post residual too small for next item: slight penalty proportional to waste
            score += 5.0 * (1.0 - pr / nx.min(cap));
        }
    }

    // Prefer bins below mean residual (denser bins first) with smooth coupling
    score += 0.3 * (pr - mean_residual) * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin gets a smooth adaptive penalty
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let new_bin_cost = 15.0 + 40.0 * (1.0 - progress) * scarcity;
        // allow opening a new bin if item is large and would leave tiny waste elsewhere
        let waste_elsewhere = (bin_residual as f64 - item_size as f64).max(0.0);
        score = new_bin_cost + waste_elsewhere * 0.1;
        if fitting_bins_count == 0 {
            score = -100.0; // must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: coarse classes of 25 (capacity quarters)
    let class = post_residual / 25;

    // Reward near-perfect fits strongly (waste < 10 is gold)
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 25.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 are "harmonic"
    // with typical item sizes and easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Penalize dead-space classes: residual in (0,10) exclusive is unusable
    // for most items; residual in (10,20) only fits tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space trap despite small absolute value
    }

    // Lookahead coupling: if the next item exactly fills this bin's
    // post_residual, this placement is part of a perfect chain.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits into post_residual, mild bonus; if it cannot,
    // penalize leaving a residual that strands the lookahead item.
    if next_item_size > 0 {
        if next_item_size < post_residual {
            score -= 5.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when existing bins would
    // leave bad harmonic classes; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let spread_pressure = mean_residual / bin_capacity as f64;
        // open new bin if open bins are already crowded
        score += 20.0 * spread_pressure - 25.0 * (1.0 - spread_pressure);
        // early stream: consolidate; late stream: allow new bins
        score += 15.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual class matches mean state
    let class_gap = (class as f64 * 25.0 - mean_residual).abs();
    score += 0.05 * class_gap;

    // Small tie-breaker on exact fill
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest item size (10)
    // are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Residual that cannot fit the lookahead item: penalize proportionally,
    // unless it is essentially zero waste.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 5 {
            // Perfect setup for the next item: strong reward.
            score -= 25.0;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: penalize creating new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if nothing fits well elsewhere.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Attractive if mean residual across open bins is tiny (all nearly full).
        score -= 1.5 * mean_residual;
        // But if the mean residual is large, opening new bins is wasteful.
        if mean_residual > 30.0 {
            score += 50.0;
        }
    } else {
        // Using an existing bin relieves pressure slightly.
        score -= 0.5 * open_bins_count as f64;
    }

    // Late in the stream, avoid leaving awkward gaps; prefer exact fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 30.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward when the next item can exactly fill the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - chain_waste * 0.5; // partial chain reward decaying with waste
        } else {
            // next item cannot follow into this bin; penalize proportional to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.6;
        }
    } else {
        // last item: prefer tightest fit only
        score += 5.0;
    }

    // Penalize dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.35;
    } else {
        score -= (mean_residual - pr) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = (bin_capacity as f64) * 0.8;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin pairs well with a large upcoming item
        }
        if fitting_bins_count <= 1 {
            score -= 35.0; // opening a new bin is fine when alternatives are scarce
        }
    }

    // Tight fit bonus: near-exact filling of the bin.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Prefer compacting many bins early, spreading later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.1 * (1.0 - progress);

    // Slight penalty for accumulating too many open bins with large residuals.
    if open_bins_count > 8 && pr > 40.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus as post_residual approaches 0.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * (1.0 - tight) * (1.0 - tight) * (post_residual as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose residual after placement matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += diff as f64 * 0.9;
        if post_residual == next_item_size {
            score -= 40.0; // perfect pairing
        }
        // Penalize leaving residual that next item cannot use but another bin could.
        if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score += post_residual as f64 * 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // When many bins fit the item, prefer the one minimizing waste; add mild
    // penalty proportional to open bins count to discourage spreading.
    if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: if mean residual is high, we have slack — prefer
    // keeping large residuals intact for big future items.
    let slack = mean_residual - post_residual as f64;
    if slack > 0.0 {
        score += 0.35 * slack;
    }

    // Time horizon: early in the stream, be conservative with near-full bins
    // (keep them for emergencies); later, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 20 {
        score += (1.0 - progress) * 12.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive
    // only when the item is large or no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.25 * (open_bins_count as f64);
        // Large items deserve fresh space when residual fragmentation is high.
        let frag = (mean_residual / (bin_capacity as f64)).max(0.0).min(1.0);
        score = base - 30.0 * (item_size as f64 / bin_capacity as f64) - 15.0 * frag;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Mild normalization to keep scales comparable.
    score *= 1.0 + 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    // Base: penalize leftover space, with non-linear (quadratic) coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * fit_ratio * fit_ratio * (0.5 + progress);
    // Reward tight fits: smooth saturating term on fill fraction
    let fill = 1.0 - fit_ratio;
    score -= 25.0 * fill * fill * fill;
    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly (smooth)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_term = (-gap / 20.0).exp();
        score -= 18.0 * match_term * (1.0 - progress);
        // Penalize post_residual that is too small to be useful for the next item
        if pr < next_item_size as f64 {
            score += 6.0 * (next_item_size as f64 - pr) / cap;
        }
    }
    // Last-chance bonus: only one bin fits the item
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }
    // Mild penalty for many open bins with large mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);
    // Prefer bins whose residual deviates smoothly from the mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space (integer division buckets of 10)
    let res_class = post_residual / 10;
    let item_class = item_size / 10;

    // Reward placing items so post_residual falls on small "harmonic" buckets
    // (dead space of 0..9 is nearly unusable for items >= 10 in the classic regime)
    if post_residual < 10 {
        score -= 45.0; // perfect closure
    } else if post_residual < 20 {
        score -= 18.0;
    } else if post_residual < 30 {
        score -= 6.0;
    }

    // Modulo coupling: reward residuals that are multiples of common item classes
    let m = post_residual % 10;
    score -= (10 - m) as f64 * 0.6;

    // Next-item lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= (30.0 - gap.min(30) as f64) * 0.8;
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: penalize large leftovers mildly
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well
    if bin_residual == bin_capacity {
        // neutral baseline; add penalty that shrinks as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter fills)
    score += (mean_residual - post_residual as f64) * 0.2;

    // Class-match bonus: item class equal to residual class implies tight fit
    if item_class == res_class && item_size <= bin_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: small unusable gaps are heavily penalized.
        // A residual below the minimum item size (1..100 range -> threshold ~12)
        // is likely dead space; the smaller it is relative to capacity, the worse.
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 40.0;
        }
        // Penalize moderate leftover space that is unlikely to fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else if next_item_size > 0 {
            // Reward leaving room exactly for the next item.
            score -= ((post_residual - next_item_size) as f64).min(10.0) * 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but discourage opening new bins even more when many already exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to existing open bins.
        score += 15.0 + open_bins_count as f64 * 3.0;
        // But if no open bin fits well, allow new bin via slight relaxation.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly favoring tighter-than-average bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild stream-progression coupling: later in the stream, be more tolerant
    // of imperfect fits to avoid opening bins near the end.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item must fit: strong reward
        if next_item_size <= post_residual {
            score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; penalize leaving awkward residue
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Penalize tiny dead space that nothing (min size 1..100) can usefully fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when a decent fit exists in open bins
    if bin_residual == bin_capacity {
        score += 5.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees next fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin before placement
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let item_frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: quadratic bonus for small post_residual
    let pr = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - pr) * (1.0 - pr) * item_frac;

    // Perfect-fit reward: residual exactly zero after placement
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit leaves almost no dead space
    }

    // Penalize leaving dead space that nothing typical can use:
    // if post_residual is small but nonzero, it's likely unusable
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fit)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nfrac = next_item_size as f64 / bin_capacity as f64;
            score -= 20.0 * nfrac * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into bins with below-average residual (denser bins)
    if open_bins_count > 1 {
        let rel = mean_residual - bin_residual as f64;
        score -= 0.15 * rel;
        // Encourage closing out bins as stream progresses
        score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin gets a baseline cost that scales
    // with how many bins are already open and how poor the alternative fits are
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheap; late in stream it's expensive
        score += 15.0 * progress;
        // But if item is large relative to capacity, new bin is more acceptable
        score -= 12.0 * item_frac;
    }

    // Mild preference for fuller bins overall
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.6 * progress) - 0.5 * x * x * (1.0 - progress);

    // Tight fits rewarded more strongly as stream progresses
    let tight = 1.0 - x;
    score -= 0.8 * tight * tight * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = if x >= nx { 1.0 } else { x / nx };
        score -= 0.5 * usable * (1.0 - progress);
        // Penalize residuals that neither fit next item nor stay useful
        if x < nx {
            score += 0.4 * (nx - x) * (1.0 + progress);
        }
    }

    // Last-chance bin bonus: strongly prefer using a bin that would otherwise be wasted
    if fitting_bins_count == 1 {
        score -= 1.2 * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty when bin is far from the mean residual (encourage homogeneity)
    score += 0.05 * ((pr - mean_residual).abs() / cap);

    // Encourage closing bins (small post residual) when many bins are open
    score += 0.05 * x * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 0.9 - 0.4 * tight + 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable" sizes
    // (multiples of common item granularity), penalize tiny dead space.
    let pr = post_residual;
    let gran: u32 = 10;
    let in_class = pr % gran == 0 && pr > 0;
    if in_class {
        score -= 6.0;
    }
    // Dead-space penalty: residuals that are too small for even the smallest item
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64 * 2.0;
    }

    // Modulo-5 harmonic sub-class: residuals divisible by 5 are half-usable
    if !in_class && pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item can exactly use post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: residual quality scales with leftover after next
            let after_next = pr - next_item_size;
            if after_next < 10 {
                score += 8.0; // creates new dead space
            } else {
                score -= 4.0 + (after_next / 10) as f64;
            }
        } else {
            // next item cannot use this residual: penalize large wasted residuals slightly
            score += (pr.min(next_item_size)) as f64 * 0.05;
        }
    }

    // Integer-division threshold: bins with residual in "large" class are valuable,
    // don't waste them on small items unless it's a near-perfect fit.
    let residual_class = bin_residual / (bin_capacity / 4).max(1); // 0..4 quartile class
    if residual_class >= 3 && item_size < bin_residual / 2 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // prefer tighter fits among many candidates: relative fill ratio
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        // penalize opening new bin, less so if existing residuals are tiny/fragmented
        score = 60.0 - frag * 45.0;
        if fitting_bins_count == 0 {
            score = -10.0; // nothing fits, must open
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 12.0; // next item needs a big bin anyway
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: residuals below 10 are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals that can still fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // this bin becomes dead after this placement
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, discourage opening another.
    // For the new-bin candidate (bin_residual == bin_capacity), add pressure;
    // for existing bins, give a small reward so they beat the new bin.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mild preference for tighter bins (best-fit flavor) relative to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            // Reward closeness of post_residual to next item size.
            score -= (30.0 / (1.0 + diff)).min(25.0);
        }
        // If next item cannot fit after placement, penalize proportionally.
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0;
    }

    // Relative to mean residual: placing into a tighter-than-average bin is good.
    score -= 0.25 * (mean_residual - bin_residual as f64);

    // Dead-space penalty: small unusable post-residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when residuals elsewhere are poor.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * mean_residual;
        if fitting_bins_count <= 1 {
            score -= 25.0; // no real alternative, new bin is fine
        }
    }

    // Mild late-stream tightening: prefer tight fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, especially dead space below smallest item.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0;
    }
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize wasting a nearly-full bin on a small item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.35 && bin_residual < bin_capacity {
        score += 18.0 * (0.35 - fill_ratio);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins where the item fits snugly.
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leaving awkward leftover after that.
            let after2 = post_residual - next_item_size;
            score -= 12.0 - 0.15 * after2 as f64;
        } else {
            // next item won't fit here; slight penalty for leaving medium dead space.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state: when many bins are open relative to progress, discourage opening new bins
    // (handled by the new-bin candidate's residual == capacity: add penalty there).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score += 10.0 + 6.0 * progress + 0.5 * crowding;
        // But if nothing fits well elsewhere, opening new is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Prefer filling bins below mean residual (balancing toward consolidation).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference for high fill fraction early in stream.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - t) * (item_size as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize waste, but weight waste more as stream progresses
    let mut score = x * (1.0 + 3.0 * progress * progress);

    // Non-linear penalty for small-but-nonzero residuals (dead space)
    score += 2.5 * (1.0 - x) * x * x * (1.0 + progress);

    // Reward tight fits (post residual near zero) with smooth decay
    score -= 4.0 * (-pr / 8.0).exp() * (1.0 + progress);

    // Lookahead coupling: if next item fits in the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0);
        let fit_quality = 1.0 - (fits / cap).powf(2.0);
        score -= 3.0 * fit_quality * (1.0 - progress);
        // penalize if next item barely misses (creates temptation to strand bin)
        let miss = (nxt - pr).max(0.0);
        score += 1.5 * (-miss / 10.0).exp() * (1.0 - x);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Mild penalty for leaving very large residuals unused early (hoarding)
    score += 0.5 * x * x * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish baseline, penalize opening bins late in stream
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularity (e.g. multiples of 10) are reusable "harmonic" gaps.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= 12.0 * harmonic;

    // Small dead space is bad: post_residual in awkward low band gets penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly / at all?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can also land here -> chain bonus, stronger on exact fit
            let chain = if post_residual % next_item_size == 0 { 18.0 } else { 9.0 };
            score -= chain;
        } else {
            // post_residual too small for next item: penalize proportionally to waste
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * waste;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a needless bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so we prefer decent existing bins...
        score += 30.0;
        // ...but relax it when mean residual is small (bins nearly full).
        score -= 0.4 * mean_residual;
        // and when many bins are open (fragmentation), a fresh bin is fine.
        score -= (open_bins_count as f64).min(20.0);
    }

    // Late in the stream, tighten packing (fewer future chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * harmonic;

    // Prefer bins whose residual is below the mean (consolidate waste).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are permanently unusable -> heavy penalty proportional to wasted space.
    if post_residual >= 1 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fills that leave room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that just barely fails the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading when many bins are open,
    // but allow opening a new bin early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost grows with open bins and stream progress.
        score = 55.0 + open_bins_count as f64 * 4.0 + progress * 25.0;
        // Opening a bin is acceptable if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Mild pressure to consolidate into fewer bins.
        score += open_bins_count as f64 * 0.6;
        // Prefer bins below mean residual (filling emptier bins first keeps tight bins flexible).
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize large dead space
            score += 0.5 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Relative tightness against mean residual of open bins
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (residual_f - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins that are already mostly empty (consolidation)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Late in the stream, be more aggressive about closing gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - residual_f / bin_capacity as f64);

    // New empty bin candidate: make it unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual) with a non-linear coupling.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // hard-to-fill zone
    }

    // Lookahead: if the next item fits in the post-residual, this is a great pairing.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 4.0; // near-miss wastes pairing potential
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage opening new bins when existing bins are underutilized.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        let waste = mean_residual / bin_capacity as f64;
        score += 20.0 + 10.0 * waste + 2.0 * open_pressure - 5.0 * (1.0 - progress);
        // Opening a new bin is more attractive late in the stream when open bins are full-ish.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Slight preference for bins already below-average fullness to balance load,
        // but only mildly so tight-fit dominance remains.
        score += 0.02 * (bin_residual as f64 - mean_residual).abs();
    }

    // Time-horizon modulation: early stream, be pickier about dead space; late stream, just close bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 0.1 * post_residual as f64; // late: favor filling anything
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (pr / bin_capacity as f64).powi(3) * (1.0 + 2.0 * progress);
    score += poly * 20.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * (1.0 + progress) * 30.0;

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + progress * 15.0;
    } else if next_item_size > 0 {
        score -= (next_item_size as f64 / 100.0) * 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
    }

    // Interaction with mean residual: prefer bins deviating favorably
    score += (pr - mean_residual) * (0.2 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets capture common capacity fractions
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows for residuals in "awkward" classes (1..9 small slivers)
    if pr > 0 {
        if class == 0 {
            score -= 8.0; // perfectly divisible residual, very reusable
        } else if class >= 7 {
            score += 3.0 + (class as f64 - 6.0) * 2.0; // large awkward sliver
        } else if class <= 2 {
            score += 6.0; // tiny unusable sliver
        }
    } else {
        score -= 15.0; // perfect fill: strongly reward
    }

    // Integer-division threshold: residual usable by next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // exact-fit lookahead bonus (harmonic pairing)
            if pr == next_item_size {
                score -= 20.0;
            } else {
                score -= (next_item_size as f64).min(20.0);
                // leftover after next item also in a good class
                let pr2 = pr - next_item_size;
                if pr2 % 10 == 0 { score -= 5.0; }
                if pr2 < 10 && pr2 > 0 { score += 4.0; }
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // neutral base; becomes attractive if open bins are crowded/fragmented
        score = 55.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big item coming, fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Late-stream tightening: consolidate more aggressively as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (mean_residual / bin_capacity.max(1) as f64);

    // Prefer bins whose residual diverges favorably from mean (tighter packing)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10 minimum size) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small unusable gap: penalty grows as gap shrinks toward 10.
        score += (20 - post_residual) as f64 * 3.0;
    } else {
        // Larger residuals are more reusable: mild reward.
        score -= (post_residual as f64 - 20.0) * 0.3;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Dead-space coupling: waste relative to residual.
    let waste = (bin_residual - item_size) as f64 / bin_residual as f64;
    score += waste * 15.0;

    // Open-bin pressure: discourage spreading across many open bins;
    // prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when this item would leave
    // a very small gap in existing bins, or when open bins are congested.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 1.2;
        // Perfect-fit lookahead: if next item exactly fills this bin, new bin is great.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 50.0;
        }
        // Late in stream, opening new bins is less costly.
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Lookahead synergy: if post_residual exactly fits next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 30.0; // next item will perfectly consume this bin
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item fits current residual but not post_residual: mild penalty
        // for fragmenting.
        score += 6.0;
    }

    // Mean-residual context: if this bin's post placement is far below mean,
    // it's creating an outlier gap.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match with the next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            // next item fits, but penalize leftover dead space after the chain
            let chain_left = (post_residual - next_item_size) as f64;
            score += 0.25 * chain_left;
            // reward a tight chain
            if chain_left < 10.0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here: dead space is likely unusable soon
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small post_residual that no plausible item (min size 1..10) can use,
    // unless it is exactly zero (perfect closure).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    if post_residual == 0 {
        score -= 40.0; // bin closed perfectly
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (good fits), avoid the emptiest bins
    // unless nothing else works.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty for spreading across many bins: keep fills concentrated.
    score += 0.05 * open_bins_count as f64;

    // Slight bias toward opening fresh bins early in the stream when fits are poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if this would be a very poor fit elsewhere
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use is worse.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin so we only do it
    // when no open bin offers a decent fit; the penalty grows late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;

        // But if mean residual across open bins is tiny (all bins nearly full),
        // opening fresh is actually fine.
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer reusing
    // existing capacity rather than spreading items.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Late-stream consolidation: as the stream ends, squeeze into existing bins.
    score -= 6.0 * progress * (bin_residual == bin_capacity) as i32 as f64 * -1.0;

    // Small bonus for using bins with larger residuals when item is large.
    if item_size >= 50 && bin_residual >= item_size {
        score -= 2.0 * (item_size as f64 / 80.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits mildly; Late: strongly prefer tight fits.
    let pr_norm = pr / cap;
    let tight_poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += (1.0 + 3.0 * progress) * 8.0 * tight_poly;

    // Reward near-perfect fills super-linearly.
    if post_residual == 0 {
        score -= 25.0 + 20.0 * progress;
    } else if post_residual <= 10 {
        score -= 10.0 * (1.0 - pr_norm) * (1.0 + progress);
    }

    // Penalize small unusable dead space, more strongly as stream progresses.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress) * (10.0 - post_residual as f64) / 10.0;
    }

    // Last-chance bin: reward heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when post_residual is large (fresh space)
    // and open bins are relatively full; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let fullness_gap = mean_residual / cap;
        score = 0.6 * cap - 0.5 * mean_residual + 30.0 * (1.0 - progress);
        score -= 10.0 * fullness_gap * fullness_gap;
        // If next item could fit into the fresh space, slight bonus.
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 5.0;
        }
    } else {
        // Reward bins whose residual will still be useful for the next item.
        if next_item_size > 0 {
            let next = next_item_size as f64;
            if pr >= next {
                score -= 4.0 * (1.0 - (pr - next) / cap);
            } else {
                score += 3.0 * (next - pr) / cap;
            }
        }
    }

    // Mild penalty proportional to number of open bins to discourage bin sprawl.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "usable" bands
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Small residuals are dead space; penalize non-zero tiny residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-arithmetic harmonic classes on post_residual
    let m = post_residual % 10;
    // Residuals that are multiples of 10 pair well with the 10..80 item range
    if m == 0 && post_residual > 0 {
        score -= 8.0;
    } else if m == 5 {
        score += 3.0;
    }

    // Integer-division thresholds: residual thirds of capacity
    let third = bin_capacity / 3;
    let two_thirds = 2 * third;
    if post_residual <= third {
        score += 6.0; // low residual band: bin nearly full, keep it attractive
    } else if post_residual >= two_thirds {
        score += 4.0; // large leftover: mild penalty to avoid wasting big space
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chains nicely
            // extra harmonic bonus if (post_residual - next) is a multiple of 10 or zero
            let r2 = post_residual - next_item_size;
            if r2 == 0 || r2 % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += (next_item_size as f64 - pr) * 0.15; // near-miss penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: baseline cost so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if nothing fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Progression-aware tightening: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr) * 0.1;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 11.0);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Moderate gaps (11..=20) are semi-dead: mild penalty.
    if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a residual too small for it.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: fewer open bins is better; discourage spreading.
    score += (open_bins_count as f64) * 0.35;

    // Prefer bins whose residual is near mean (balanced packing) slightly.
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    // New-bin candidate handling: only attractive early in the stream or when
    // the fit into this new bin would be very tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = (bin_capacity - item_size) as f64 <= 10.0;
        if tight_fit && post_residual == 0 {
            score -= 30.0;
        } else {
            score += 25.0 + 40.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: exact match of post_residual to next item is golden.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for next item -> big reward (subtract).
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how large the next item is relative to capacity.
            score += gap * (0.4 + 0.6 * (next_item_size as f64 / cap));
        }
        // If next item cannot fit here anyway, mild penalty for wasting the slot.
        if (post_residual as u32) < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Dead-space penalty: residuals too small for any item (min size 1..100 unknown, assume small items exist)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is generally costly unless
    // current fits are all poor. Penalize fresh bin, but relax when many bins
    // are open and mean residual is large (fragmentation high).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap; // 0..1
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let mut new_bin_penalty = 45.0 - 20.0 * fragmentation - 10.0 * pressure.min(1.0);
        // If lookahead suggests next item is large, a fresh bin is more attractive.
        if next_item_size as f64 > 0.6 * cap {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty.max(5.0);
    }

    // Mild preference for bins tighter than average (use up crowded space).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: square the post-residual penalty so near-perfect fills win strongly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize by default, more when open bins are already plentiful.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
        if scarcity > 0.0 {
            score -= 20.0; // no open bin fits at all: new bin is fine
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Lookahead: penalize leaving a residual that cannot host the next item
    // (dead space), reward residuals that can exactly host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + slack * 0.1);
            if post_residual == next_item_size {
                score -= 20.0; // perfect two-item pairing
            }
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (keeps bin residuals balanced), unless it's the last-chance case.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins with smaller residuals first (best-fit flavor),
    // scaled by how many bins compete for this item.
    score += 0.1 * (fitting_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: waste after placement
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, small residuals are acceptable; late, they become costly.
    let progress_penalty = x.powi(2) * (1.0 + 3.0 * t) * cap * 0.5;
    score += progress_penalty;

    // Reward tight fits smoothly: cubic term favoring small x, stronger late.
    score -= (1.0 - x).powi(3) * cap * (0.2 + 0.6 * t);

    // Dead-space term: residuals too small for typical future items are penalized
    // via smooth interaction with mean residual.
    let dead = (mean_residual / cap - x).abs();
    score += dead.powi(2) * cap * 0.3;

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= (1.0 - (nxt / cap)) * 5.0 * (1.0 + t);
        } else {
            let gap = (nxt - pr as f64) / cap;
            score += gap.powi(2) * cap * (0.5 + 0.5 * t);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + t);
    }

    // Slight penalty for many open bins, encouraging consolidation.
    score += open_bins_count as f64 * 0.05 * x;

    // New-bin candidate: neutral-ish baseline, mildly discouraged early,
    // more attractive late when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - t) - 1.5 * t * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify dead space into decile bands ---
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i32; // 0..10 harmonic class

    // Reward small residuals (tight fits) with a non-linear bonus.
    match class {
        0 => score -= 30.0,               // near-perfect fit
        1 => score -= 22.0,
        2 => score -= 14.0,
        3 => score -= 7.0,
        4 => score -= 2.0,
        5 => score += 3.0,                // half-full: mediocre
        6 => score += 6.0,
        7 => score += 9.0,
        8 => score += 13.0,
        9 => score += 18.0,               // mostly empty: wasteful
        _ => score += 25.0,
    }

    // Modulo arithmetic: residuals divisible by small integers are more "usable"
    // by typical item sizes (harmonic divisibility bonus).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr % 4 == 0 { score -= 1.5; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly — strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits but leaves a new residual: partial chain reward
            let chain_waste = pr - next_item_size;
            score -= 10.0 - (chain_waste as f64).min(10.0);
        } else {
            // next item cannot use this bin's remainder: penalize large leftover
            score += (pr as f64 - mean_residual).max(0.0) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish but discourage when open bins are tight
    // (few fitting bins) or when stream is late (consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress); // cheaper to open early
        if fitting_bins_count == 0 { score -= 25.0; }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 40.0 && post_residual > 40 {
        score += 4.0;
    }

    // Integer-division threshold: tiny residuals are essentially dead space.
    if pr > 0 && pr / 10 == 0 {
        score -= 8.0; // pr in 1..9: negligible waste, excellent
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are the worst outcome.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 && post_residual > 0 {
        score += 200.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 150.0; // perfect closure
    }

    // Non-linear dead-space coupling: penalize gaps that can't fit the
    // lookahead item if it would otherwise need a fresh bin.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            // gap wasted relative to lookahead
            score += 30.0 * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64));
        } else {
            // lookahead fits in the gap: reward
            score -= 25.0 * ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few bins, opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it's a "loose" bin — mildly discourage leaving it looser.
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: an empty bin should only win when remaining open
    // bins have poor fits. Penalize the fresh bin moderately so it is chosen
    // only when all existing bins score badly.
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
