        score += 30.0 + 8.0 * (fitting_bins_count as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If the next item is large and this fresh bin would serve it perfectly, opening
        // becomes more attractive.
        if next_item_size > 0 {
            let next_fit = (bin_capacity as f64 - next_item_size as f64) / (bin_capacity as f64);
            score -= 20.0 * next_fit * next_fit;
        }
    }

    // Lookahead synergy: if the current item's placement leaves room exactly suited for
    // the next item, reward it.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 15.0 / (1.0 + diff as f64);
    }

    // Global-state coupling: when mean residual across open bins is high, prefer packing
    // into existing bins (penalize new bins implicitly); when low, allow spreading.
    score += 0.05 * mean_residual * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mild penalty for proliferating bins.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, keep residuals flexible; late, punish waste harder.
    let w = 1.0 + 3.0 * progress * progress;
    score += 0.35 * w * (pr / cap) * pr;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tight = 1.0 - (pr / cap).min(1.0);
    score -= 12.0 * tight * tight * tight;

    // Penalize bins whose residual deviates strongly from the mean residual
    // (keeps bin population homogeneous, eases future packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward;
    // smooth quadratic affinity between post_residual and next item size.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - (gap / cap).min(1.0)).powi(2);
    }

    // New-bin candidate: neutral baseline with slight late-stream penalty
    // so open bins are preferred unless their fit is truly poor.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation early.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are "nice" divisors
    // of the capacity (multiples of 10, 20, 25) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit — ideal
    } else if pr % 10 == 0 {
        score -= 18.0;
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 6.0; }
    } else if pr % 25 == 0 {
        score -= 12.0;
    } else {
        // awkward leftover: penalize small dead space harshly
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match bonus if next item aligns with leftover class
            if pr % next_item_size.max(1) == 0 || next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 14.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover; leftover likely dead
            score += (pr.min(40) as f64) * 0.35;
            if pr < next_item_size && pr < 15 {
                score += 12.0;
            }
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Many open bins with high mean residual: favor consolidation into fuller bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - desperation * 90.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward near-perfect fits (small but usable gaps are fine).
    if post_residual > 0 && post_residual <= 5 {
        score -= 20.0;
    }

    // If the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item cannot fit in the post residual, mild penalty for blocking lookahead.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the mean
    // residual is already large (bins are underfilled).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Favor bins whose residual is below the mean (denser bins get filled first).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual > (item_size as f64 * 1.2);
        if decent_fit_exists {
            score += 30.0; // prefer existing bins
        } else {
            score -= 10.0; // allow opening a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect closure
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0;
        score += slack * 0.8;
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize proportionally to the gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Penalize leaving large unusable dead space relative to mean residual
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.6 * (0.5 + t);
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Slight preference for keeping many open bins consolidated
    score += open_bins_count as f64 * 0.05;

    // Small bias toward larger items closing big residual bins
    score -= item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftovers.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Perfect fit jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: penalize leftovers that could have hosted the next item
    // (i.e., we burn space the future could use), reward when leftover is unusable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // leftover stays useful — good
        } else {
            score += 6.0; // leftover becomes dead space relative to lookahead
        }
        // If this placement leaves exactly what the next item needs, reward strongly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: minimize leftover aggressively.
        score -= 30.0 * tight;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when the item is large and open bins have poor residuals (would waste a lot).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 45.0 + 3.0 * open_bins_count as f64;
        // If no open bin fits well (post_residual here equals capacity - item),
        // and item is big, opening a fresh bin is cheap insurance.
        let wasted_elsewhere = mean_residual - item_size as f64;
        if wasted_elsewhere > 0.0 {
            new_bin_penalty -= 0.2 * wasted_elsewhere;
        }
        // Early in the stream, keep bins consolidated; late, allow spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty *= 1.0 + 0.5 * (1.0 - progress);
        score += new_bin_penalty.max(10.0);
    } else {
        // Using an open bin: slight reward scaled by how full the bin becomes.
        let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill * fill;
        // Prefer bins whose residual is below mean (consolidate emptier space elsewhere).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Global pressure: many open bins -> favor placements that close bins out.
    if post_residual < 10 && bin_residual != bin_capacity {
        score -= 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: quadratic dead-space penalty scaled by stream progress.
    let tight = (pr / cap) * (pr / cap);
    score += (1.0 + 3.0 * progress) * 40.0 * tight;

    // Smooth coupling: penalize bins whose residual deviates from mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward leaving space usable by the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 5.0 * (1.0 - pr / cap) * (1.0 - progress);
        }
    }

    // Mild preference for fewer open bins early in the stream.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // Prefer using existing bins over opening new ones, especially late.
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo bands
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Penalize dead space: residual too small for any plausible item (min size 1..100 unknown; assume >=10 style)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Harmonic modulo classes of post_residual (capacity fractions)
    // Residuals in "half" band (40-60) are highly reusable; reward them
    if post_residual >= 40 && post_residual <= 60 {
        score -= 40.0;
    }
    // Quarter bands
    if post_residual >= 20 && post_residual <= 30 {
        score -= 15.0;
    }

    // Integer-division threshold: post_residual / next_item_size
    if next_item_size > 0 {
        let k = post_residual / next_item_size.max(1);
        score -= (k as f64) * 8.0; // more future fits in this bin -> better
        // Perfect chain: next item exactly fills what remains
        if next_item_size == post_residual {
            score -= 250.0;
        }
        // Next item leaves another harmonic half-band residual
        let pr2 = post_residual as i64 - next_item_size as i64;
        if pr2 > 0 {
            let pr2u = pr2 as u32;
            if pr2u >= 40 && pr2u <= 60 {
                score -= 25.0;
            }
            if pr2u % 10 == 0 {
                score -= 10.0; // aligned residuals are reusable
            }
        } else if pr2 < 0 && pr2 > -10 {
            score += 60.0; // next item barely doesn't fit: bad dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if current item is huge and leaves awkward residual in any bin, new bin is fine
        if item_size >= 80 {
            score -= 30.0;
        }
    }

    // Tightness reward: favor bins whose residual is close to item size
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 60.0;

    // Progress modulation: early in stream, be pickier about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (frac * 10.0);

    // Mean-residual coupling: prefer bins below mean residual (denser bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< min item size 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Large gaps are somewhat acceptable; slightly soften raw residual.
        score -= 4.0;
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += (post_residual as f64) * 0.9;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual reusable by the lookahead item -> reward.
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (6.0 + 8.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure and mean residual context.
        score += 25.0 + pressure + mean_residual * 0.15;
    } else {
        score -= pressure * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ni = next_item_size as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        if pr >= ni {
            // Next item fits after this placement: reward tight chains.
            let diff = pr - ni;
            score -= 45.0 * (1.0 - diff / cap);
        } else {
            // Placement creates dead space relative to the lookahead item.
            score += 30.0 * (ni - pr) / cap;
        }
    }

    // --- Mean-residual coupling: prefer bins near the fleet average ---
    score += 0.4 * (pr - mean_residual);

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Increasingly reluctant to open new bins as the stream progresses.
        score += 55.0 + 60.0 * progress;
        // If no open bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Early stream: allow a fresh bin to stay attractive for big items.
        if item_size > bin_capacity / 2 {
            score -= 20.0 * (1.0 - progress);
        }
    } else {
        // Last-chance existing bin: strong reward to use it before opening new.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Slight preference for tighter fits overall.
    score -= 10.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (post_residual as f64).sqrt();

    // Penalize dead space: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins: compare residual to mean residual across open bins.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Mild penalty per open bin to encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 0.1;

    // New-bin candidate handling: empty bin gets a baseline penalty so we only open
    // a new bin when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If item is large relative to capacity, opening fresh is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
    }

    // Dynamic time horizon: late in the stream, favor closing gaps tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * tightness * 5.0;

    // Slight preference for bins whose residual is close to a multiple-friendly size.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post_residual, but penalize leaving tiny unusable gaps
    let mut score = pr;

    // Non-linear dead-space penalty: gaps that are small but nonzero are bad
    let dead = pr / cap;
    score += 12.0 * dead * (1.0 - dead) * (1.0 - dead) * (dead * 20.0).min(1.0);

    // Smooth quadratic coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (spread items); late, demand tight fits
    let tightness = 1.0 + 2.0 * progress * progress;
    score += tightness * pr * pr / cap;

    // Lookahead: reward if next item fits into the post_residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_bonus = (1.0 - (gap / cap).min(1.0)).powi(3);
        score -= 8.0 * fit_bonus * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - dead);
    }

    // Mean residual interaction: if this bin is far from the mean, mild penalty
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score = 30.0 + 25.0 * (1.0 - fragmentation) - 10.0 * progress * (1.0 - fragmentation);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of 10, or small enough to be near-dead) get adjusted.
    let r = post_residual;
    let cap = bin_capacity as f64;

    // Reward exact filling
    if r == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals too small to hold the smallest item (1..100 range)
    if r > 0 && r < 10 {
        score += 40.0;
    }

    // Harmonic class: r % 10 == 0 residuals are "aligned" and more reusable
    if r % 10 == 0 && r > 0 {
        score -= 12.0;
    }

    // Integer-division threshold classes on post_residual
    let class = r / 25; // 0..4 harmonic quartiles of capacity
    score -= match class {
        0 => 8.0,          // residual <= 24: small leftover, tight fit is good
        1 => 2.0,          // 25..49
        2 => 0.0,          // 50..74
        _ => 4.0,          // 75..99: wasteful placement into a nearly full bin
    };

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / cap;
    score -= 15.0 * fill_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if next_item_size <= r {
            let gap = (r - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / cap);
            // harmonic alignment between next item and residual
            if r % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalize large leftovers mildly
            score += 0.05 * r as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when it's genuinely better
    if bin_residual == bin_capacity {
        // Base preference for existing bins: new bin slightly penalized
        score += 30.0;
        // But if open bins are fragmented (high mean residual spread) and crowded,
        // opening fresh can win: reduce penalty as open_bins_count grows
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        score -= 10.0 * progress;
        // If item is large and mean residual is small, new bin is attractive
        if (mean_residual < item_size as f64) && item_size >= 50 {
            score -= 45.0;
        }
    }

    // Mild preference for bins with residual close to item (tight fit)
    let tight = (bin_residual - item_size) as f64;
    score += 0.03 * (tight - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a future item (>= 1) are pure waste; the worst zone is tiny gaps.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Penalize small unusable gaps super-linearly.
        if pr < 10.0 {
            score += (10.0 - pr) * 6.0;
        } else if pr < 20.0 {
            score += (20.0 - pr) * 2.5;
        }
        // Reward leaving a gap that plausibly fits the lookahead item exactly.
        if next_item_size > 0 && (pr as u32) >= next_item_size {
            let slack = pr - next_item_size as f64;
            score -= slack * 0.8;
        }
        // Perfect fill is gold.
        if pr == 0.0 {
            score -= 15.0;
        }
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 8.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 3.0 + 5.0;
        // But if mean residual across open bins is small (fragmented bins),
        // opening a fresh bin becomes more attractive.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 10.0;
        }
        // Late in the stream, avoid carrying many near-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 2.0;
    } else {
        // Slight preference for bins that are already well-filled.
        score += (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    // Coupling: if the lookahead item can't fit this bin's post_residual but
    // the gap is moderate, mild penalty (fragmentation risk for k=2 chain).
    if next_item_size > 0 && (pr as u32) < next_item_size && pr > 0.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
