pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) dead-space cost
    let mut score = post + 40.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: later in the stream, tolerate residual less (tighten packing)
    let tighten = 1.0 + 0.8 * progress * progress;
    score *= tighten;

    // Interaction: post_residual vs mean_residual — prefer bins below mean residual (tighter bins)
    let mean_gap = (mean_residual - post) / cap;
    score -= 15.0 * mean_gap;

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post residual (smooth compatibility term)
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let compat = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 12.0 * compat;
    } else if next_item_size > 0 {
        // penalize leaving residual that blocks the lookahead item
        score += 8.0 * (1.0 - ((next_item_size as f64 - post) / cap).abs().min(1.0));
    }

    // Mild penalty for proliferation of open bins, smoothed by progress
    score += (open_bins_count as f64).ln() * (2.0 + 3.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residues divisible by small class sizes
    // (e.g., 10, 20, 25, 50) are more reusable by typical item sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else {
        // Harmonic divisibility rewards: residual that many item sizes can exactly fill.
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 10.0; }
        else if pr % 20 == 0 { score -= 8.0; }
        else if pr % 10 == 0 { score -= 5.0; }
        else if pr % 5 == 0 { score -= 2.0; }
        // Penalize awkward residues (prime-ish, non-multiples of 5)
        if pr % 5 != 0 { score += 6.0; }
        if pr % 3 != 0 && pr % 2 != 0 { score += 3.0; }
    }

    // Integer-division thresholds: classify residual into usable size bands.
    let band = pr / 10; // 0..10 bands
    score -= (band as f64) * 0.5; // larger residuals are generally more useful

    // Coupling with lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 25.0; // next item leaves a harmonic residue
        } else if next_item_size < pr {
            score -= 8.0;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when existing residuals are poor fits (item leaves non-harmonic waste).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) % 10;
        score = 45.0 + (waste as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // Late in the stream, prefer closing existing bins rather than opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Many open bins with small mean residual -> avoid opening more.
        if mean_residual < 25.0 && open_bins_count > 3 {
            score += 15.0;
        }
    }

    // Mild penalty for very tight bins that leave 1..9 dead space.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100) are pure waste,
    // and small gaps below typical item sizes are nearly unusable.
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space: heavy penalty.
        score += 40.0;
    } else if post_residual < 25 {
        // Marginal gap: moderate penalty.
        score += 12.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Open-bins pressure: penalize using bins when many are open, to discourage bin sprawl.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is far from the mean (consolidation of small leftovers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mildly reward.
            score -= 5.0;
        } else {
            // Next item won't fit here: penalize slightly.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave large dead space
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin.
        score += 45.0;
        // But if the fit in existing bins is terrible (huge post_residual), new bin wins.
        if post_residual > 50 && item_size > 0 && bin_residual == bin_capacity {
            // This is the new-bin call itself; post_residual == bin_capacity - item_size.
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Core: 2-step lookahead matching ----
    // Reward bins whose post_residual matches the next item size well.
    if next_item_size > 0 {
        let look_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fit: post_residual == next_item_size -> strong bonus
        score -= 40.0 * (1.0 - look_gap / bin_capacity as f64).max(0.0);

        // Perfect exact 2-step closure
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item cannot fit here: penalize leaving a large unusable gap
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fill
        score -= 30.0;
    }

    // ---- Relative-to-mean-residual coupling ----
    // Bins with residual close to the mean are "average" candidates;
    // prefer bins that are tighter than average (small residual before placement).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel); // tighter than average: reward
        } else {
            score += 5.0 * (rel - 1.0).min(2.0); // looser than average: penalize
        }
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 {
        // Only this bin can fit the item: strongly favor using it
        // unless a new bin gives a near-perfect fit.
        score -= 35.0;
        if post_residual > 0 && post_residual < 5 {
            score -= 10.0; // nearly perfect fill in the only option
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost that shrinks with stream progress
        // (early on, opening bins is fine; late, avoid waste).
        score = 100.0 - 60.0 * progress;
        // If the new bin would fit both this and the next item perfectly,
        // allow it to compete.
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 45.0;
        }
        // If no existing bin fits well, new bin is more attractive
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // ---- Waste penalty: dead space too small for typical items ----
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Mild preference to consolidate into fewer bins
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 14.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space risk: leftover smaller than next item.
        score += 6.0 * (post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize many open bins with large mean residual spread (fragmentation).
    score += 0.15 * open_bins_count as f64;
    score -= 0.05 * mean_residual;

    // Time horizon: late in the stream, favor filling existing bins; early, allow opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * (1.0 - progress) * tight;

    // New-bin candidate: only attractive when current bin would leave large dead space.
    if bin_residual == bin_capacity {
        score += 12.0 * tight; // empty bin has post_residual = capacity - item; tight ~ item/capacity
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with mild convexity
    let mut score = x * (1.0 + 1.5 * x * x);

    // Stream-progress coupling: later in stream, tighten further (dead space more costly)
    score += progress * 2.0 * x * (1.0 - x);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * (1.0 - x);
    }

    // New-bin candidate: penalize opening a new bin unless the item fits very poorly everywhere.
    // New bin gets post_residual = capacity - item_size, which is large, so base score is high;
    // subtract a term that scales with how "wasteful" current alternatives would be.
    if bin_residual == bin_capacity {
        let waste = (mean_residual - item_size as f64).max(0.0) / cap;
        score -= 1.0 + 2.0 * waste;
        // early stream: slightly prefer new bins to build spread
        score -= 1.5 * (1.0 - progress);
    }

    // Lookahead coupling: if next item would fit the post residual, reward this bin
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 0.5 + 1.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving awkward residual
        score += 0.5 * x;
    }

    // Mild penalty when many bins open and this placement leaves large residual
    score += 0.1 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes are reusable
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that lie in "harmonic" classes (multiples of 10, 20, 25, 50)
    let harmonic = ((pr % 10 == 0) as i32) * 2 + ((pr % 20 == 0) as i32) + ((pr % 25 == 0) as i32) + ((pr % 50 == 0) as i32);
    score -= 6.0 * harmonic as f64;

    // Penalize awkward residual classes (prime-ish / odd small leftovers)
    if pr > 0 && pr < 10 {
        score += 12.0; // dead space zone
    }
    if pr % 2 == 1 && pr < 30 {
        score += 4.0;
    }

    // Perfect fit: massive reward
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_fit_class = pr - next_item_size;
            // Reward if next item also leaves a harmonic residual
            if next_fit_class % 10 == 0 {
                score -= 8.0;
            }
            score -= 3.0;
        } else {
            score += 5.0; // this placement strands the next item
        }
        // Exact pairing: item + next fills bin completely
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are bad
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // average fill slack
        score = cap as f64 * 0.55 + 20.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 10.0; // next item is big, fresh bin useful
        }
    }

    // Late in stream: consolidate, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / cap);

    // Many open bins: discourage spreading, reward filling existing ones
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size of 1..100 stream, treat <10 as dead) are heavily penalized.
    let dead_threshold: u32 = 9;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Non-linear penalty on moderately small leftovers that few item sizes can use.
    if post_residual > 0 {
        let usable = (post_residual as f64 / bin_capacity as f64).sqrt();
        score += (1.0 - usable) * 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item cannot use the leftover; penalize creating stranded space
        score += 8.0;
    }

    // Prefer bins already below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when no good fit exists
    // (many fitting bins) or stream is early; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_bins_count as f64 * 2.0 - progress * 5.0;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: if the next item exactly fills the post residual,
    // this is a perfect chained placement -> heavily reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: reward proportionally to how much residual it consumes.
        let frac = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * frac;
    } else if next_item_size > 0 {
        // Next item does NOT fit in the post residual: penalize wasted space
        // scaled by how close the next item is to fitting (near-miss is worst).
        let gap = (next_item_size - post_residual) as f64;
        let near_miss = (1.0 - (gap / 100.0)).max(0.0);
        score += 8.0 + 12.0 * near_miss;
    }

    // Penalize leaving tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: only bin that can fit this item -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let open_bonus = if fitting_bins_count > 0 { 30.0 + 5.0 * fitting_bins_count as f64 } else { 5.0 };
        score += open_bonus;
        // Opening a new bin is more acceptable early in the stream or when
        // open bins are already quite full on average.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);
    }

    // Mild preference for tighter bins relative to the fleet mean residual.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that can
    // never fit a typical item is wasted. Penalize post_residual that is too
    // small to be useful (fragmentation), reward very tight fits.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if frac < 0.35 {
        score -= 15.0 * (0.35 - frac); // moderately small residual is reusable
    } else {
        score += 5.0 * (frac - 0.35); // large leftover is meh
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the fullest bin (smallest residual) —
        // classic best-fit; slight extra pull.
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward heavily; if next item would be blocked, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 { score -= 40.0; }
            else if slack < 10.0 { score -= 20.0; }
        } else {
            // Next item can't fit here; leaving big residual wasted relative to lookahead
            score += 0.10 * ((post_residual - next_item_size) as f64).min(60.0);
        }
    }

    // Time horizon: early in the stream, be conservative with new bins
    // (long future to exploit tight packing); late in the stream, prefer
    // closing bins out (use existing space more aggressively).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by state.
        let mut new_bin_cost = 70.0;
        // If item is large and no tight option exists, opening is fine.
        new_bin_cost -= 0.2 * item_size as f64;
        // If many bins are open and mean residual is high, prefer reusing.
        new_bin_cost += 0.3 * mean_residual;
        // Late in the stream, avoid opening bins (no time to fill them).
        new_bin_cost += 50.0 * progress;
        // If several bins already fit, opening a new one is rarely good.
        if fitting_bins_count > 0 {
            new_bin_cost += 25.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Last item: never open a new bin if any bin fits.
        if next_item_size == 0 {
            new_bin_cost += 100.0;
        }
        score += new_bin_cost;
    }

    // Small global-state coupling: when open bins are numerous, tighten
    // selection pressure toward fullest bins to consolidate.
    score -= 0.02 * open_bins_count as f64 * (bin_capacity - bin_residual) as f64 / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = item_size as f64 / cap;
    let norm_post = post / cap;

    // Reward tight fits: quadratic coupling between fill fraction and progress
    score -= fit_norm * fit_norm * (1.0 + progress) * 40.0;

    // Penalize large post-residual non-linearly, stronger late in stream
    score += norm_post * norm_post * (20.0 + 30.0 * progress);

    // Interaction: small post_residual is valuable if it matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - (post - nxt).abs() / cap;
        if match_term > 0.0 {
            score -= match_term * match_term * 15.0 * (1.0 - progress);
        }
        // Penalize leaving residual too small for next item (dead space)
        if post > 0.0 && post < nxt {
            score += (1.0 - post / nxt.max(1.0)) * 10.0 * (0.5 + progress);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (consolidate emptier bins)
    score += (mean_residual - post) * 0.3;

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 8.0 - 6.0 * progress - fit_norm * 10.0 * progress;
        score += open.min(10.0) * 0.5 * (1.0 - progress);
    }

    // Smooth sigmoidal congestion term: many open bins -> favor filling existing ones
    let congestion = 1.0 / (1.0 + (-0.2 * (open_bins_count as f64 - 5.0)).exp());
    score -= congestion * fit_norm * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let pr_class = post_residual % 10;
    // Reward small post_residual strongly (non-linear, quadratic decay).
    score -= 12.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2);

    // Dead-space penalty: residuals in awkward classes (1..9 mod 10) are hard to fill.
    if pr_class > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if pr_class != 0 && pr_class < 5 {
        score += 4.0 * pr_class as f64;
    }

    // Coupling with next item: perfect pairing reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact fill next step
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack / 10.0); // next item fits here too
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 * over / 20.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64
            - 18.0 * fragmentation
            - if next_item_size > 0 && next_item_size <= post_residual { 10.0 } else { 0.0 }
            + 8.0 * progress;
        if fitting_bins_count <= 1 {
            score += 30.0; // prefer using the last fitting bin
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Early stream: be pickier about waste; late stream: just fill.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress) - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving gaps that can still fit typical items (>= 10).
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead coupling: penalize if post_residual cannot fit the next item
    // but is large enough that it feels wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins are open (early stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + open_bins_count as f64 * 4.0 - progress * 10.0;
        if post_residual == 0 { score -= 30.0; }
    }

    // Slight preference for bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial match: reward closeness of next item to leftover space.
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap / 10.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to overshoot.
        let overshoot = (next_item_size - post_residual) as f64;
        score += overshoot * 0.3;
    }

    // Reward small post_residual (tight packing), non-linearly.
    score -= 25.0 / (1.0 + post_residual as f64);

    // Compare against mean residual: placing into a bin with residual below
    // mean (a "small" hole) is good; large-holes-first is avoided.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for wasting a fresh bin.
        score += 45.0;
        // But if next item matches a fresh bin's post-fit residual, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 35.0 / (1.0 + gap / 10.0);
        }
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // Many open bins: prefer consolidating instead of new bins.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness).powi(3) * 12.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is nearly unusable.
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Post-residual too small for next item: slight penalty unless tiny.
            if post_residual >= 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins among many open bins (encourage consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin is a good fit
    // or stream is early with few bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            // Compete with the single fitting bin; keep new bin slightly worse
            // unless that bin would leave large waste.
            score = 15.0 + post_residual as f64 - fill_ratio * 0.0;
        } else {
            score += 20.0; // plenty of options: discourage opening new bins
        }
    }

    // Time horizon: early in the stream, be slightly more liberal with new bins
    // to preserve flexibility; late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (best fit), non-linearly scaled
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of tightness with stream progress:
    // late in the stream, tight fits matter more (dead space penalized more)
    let tightness = 1.0 - norm_pr; // how full the bin becomes
    score -= tightness * tightness * (1.0 - progress) * 10.0;
    score += norm_pr * norm_pr * progress * 20.0;

    // Penalize bins whose residual after placement cannot host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= (1.0 - (pr - ns) / cap) * 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual usage
    let mean_res = mean_residual;
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_res) * 0.05 * (1.0 - progress);
    }

    // Slight preference to keep few open bins early on
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless it's a great deal
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity-fraction buckets.
    // Classes near multiples of common item sizes (10..80 grid) are "usable" slots.
    let class = (post_residual / 10) as f64; // integer-division threshold class
    let class_bonus = match post_residual % 10 {
        0 => 0.0,                       // perfectly harmonic slot
        r if r <= 3 => 2.0,             // nearly harmonic, small dead space
        r if r >= 7 => 6.0,             // awkward slot
        _ => 4.0,
    };
    score += class_bonus;

    // Reward large usable classes (a slot that can host a future big item).
    if class >= 4.0 {
        score -= 3.0 + 0.5 * class;
    } else if class == 0.0 {
        score -= 5.0; // perfect fill is ideal
    }

    // Lookahead coupling: does the residual left behind fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic match: post residual can host next item exactly or with small waste.
            let waste = post_residual - next_item_size;
            score -= 8.0 - (waste as f64) * 0.25;
            if waste == 0 {
                score -= 6.0; // perfect two-item chain
            }
        } else if next_item_size > post_residual && bin_residual >= next_item_size {
            // Next item would fit this bin but we consumed the space: penalize mildly.
            score += 3.0;
        }
    } else {
        // Last item: any placement is fine; prefer tightest fill.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin candidate (empty bin) unless current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open a new bin only if open bins are too full/fragmented to be useful.
        if fragmentation < 0.25 && open_bins_count > 0 {
            score += 15.0; // keep using existing space
        } else {
            score -= 4.0; // fragmented state: fresh bin is attractive
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild pressure against many open bins with idle capacity.
    score += 0.15 * open_bins_count as f64;

    // Nudge toward bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small to fit typical future
    // items are unusable dead space -> strong penalty.
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            // The smaller (and thus more useless) the gap, the bigger the penalty.
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Reward tight fits generally: prefer bins where item fills a large fraction
    // of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage scattering across many open bins when
    // plenty are already open; encourage consolidation.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: if open bins are on average quite full
    // (low mean residual), opening a new bin is more acceptable; if mean
    // residual is large, prefer filling existing bins.
    score += mean_residual * 0.4;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item would fit in the post-residual, reward this
    // placement (keeps usable space for the future).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space -> mild penalty.
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // moderate fallback. It should win only when all open bins would create
    // severe dead space. Base cost plus pressure from stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheap; later, prefer reuse.
        score = bin_capacity as f64 * 0.9 + progress * 10.0 + (open_bins_count as f64) * 0.3;
        // If the new bin would still leave a large usable residual for the
        // lookahead item, keep it competitive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into post_residual: moderate reward, scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    }

    // Penalize residuals too small for the next item (likely dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Prefer bins tighter than the mean residual
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when other bins fit, especially early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        // New bin less attractive if it can't host the next item either
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Small bonus for very tight fits (small absolute waste)
    score -= (bin_capacity as f64 - (bin_residual as f64)) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 25.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size == post_residual {
            score -= 25.0;
        } else {
            // penalize leaving residuals that are awkward for the next item
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += waste * 0.3;
        }
    }

    // Penalize leaving large dead space when many bins are open (fragmentation)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when few fitting bins exist (prefer consolidation)
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        score += 35.0 + 20.0 * progress + 5.0 * open_pressure;
        // allow new bin if item is large and nothing tight exists
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild preference for filling bins that are already partially full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Penalize small unusable residuals (dead space < typical min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Non-linear penalty on wasted residual: quartic waste term, stronger later in stream
    score += 40.0 * x * x * x * x * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential coupling
    score -= 25.0 * (-(pr * pr) / (cap * cap)).exp() * (1.0 + progress);

    // Penalize residuals that are too small to hold typical future items but not zero
    // smooth valley: penalty peaks when residual ~ 10..30, decays elsewhere
    let mid = (x - 0.2) * (x - 0.2);
    score += 15.0 * (-mid * 50.0).exp() * (1.0 - progress * 0.5);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly (smooth)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-diff * diff / 100.0).exp();
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more when many bins open or early stream
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Slight preference to keep mean residual balanced: avoid very unbalanced bins
    score += 3.0 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (or large enough) are valuable.
    let cap = bin_capacity as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    }

    // Harmonic divisibility: leftover divisible by small classes (10,20,25,50) is reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 15.0; }
        if pr % 25 == 0 { score -= 10.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Odd dead-space penalty for awkward residues
        if pr % 10 != 0 && pr < 30 { score += 25.0; }
    }

    // Lookahead harmony: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match bonus
            if post_residual % next_item_size.max(1) == 0 {
                score -= 40.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Fraction-of-capacity threshold on residual: bins below 1/4 capacity residual
    // are nearly closed; encourage finishing them.
    let residual_frac = bin_residual as f64 / cap;
    if residual_frac < 0.25 {
        score -= 30.0 * (0.25 - residual_frac) * 4.0;
    }

    // Prefer filling bins with below-average residual (consolidation).
    score -= (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Mild pressure to keep the number of open bins low early on.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40 || (fitting_bins_count == 0);
        if poor_fit {
            score -= 25.0;
        } else {
            score += 60.0;
        }
    }

    // Stream progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64) * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post residual).
    let pr = post_residual as f64;
    score += pr;

    // Dead-space penalty: post_residual in "unusable" small gaps.
    // A gap is dead if it is small (below typical item size) and non-zero.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if the leftover gap is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage reuse.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate logic: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when no open bin fits well
        // (i.e., this item would otherwise create heavy dead space).
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            // Mild penalty so we prefer reusing bins unless the fit is bad.
            score += 15.0 + mean_residual * 0.05;
        }
    }

    // Slight preference toward bins with residual close to item (tight packing).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // 2-step lookahead: strongly reward when next item fits the post_residual exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: reward proportional to how perfectly it fills
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // exact fill of two items is ideal
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // next item cannot fit here: penalize, worse the larger the leftover
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.5;
        }
    } else {
        // last item: prefer minimal final residual
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: placing into a bin with residual above mean
    // helps balance; penalize dipping far below mean (creating many tiny residuals)
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mr * 0.5 {
        score += (mr * 0.5 - post_residual as f64) * 0.3;
    }

    // Penalize leaving dead space that nothing (min size 1) could ever pair with
    if post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Early in stream: slightly favor consolidating into fewer bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if open_bins_count > 4 && progress < 0.5 && bin_residual < bin_capacity {
            score -= 3.0;
        }
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        score += 15.0 + (fitting_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more than linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize stranding small dead space that the next item can't use.
        score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // no open bin fits: new bin is the only option
        } else {
            // Penalize opening a new bin when alternatives exist, scaled by how
            // well the item would fit in existing bins.
            let waste_elsewhere = (bin_capacity as f64 - item_size as f64);
            score += 30.0 + 0.2 * waste_elsewhere;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // reduce fragmentation (i.e., bins with residual near item_size).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64).max(0.0);
    score -= 5.0 * tightness * (mean_residual / bin_capacity as f64);

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for placing into already-open bins vs. growing bin count.
    if bin_residual != bin_capacity {
        score -= 3.0 / (open_bins_count as f64).sqrt().max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward small post residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Non-linear polynomial coupling of post residual with stream progress:
    // late in the stream, tighter packing matters more.
    let tight = (1.0 - x).powi(3);
    score -= 12.0 * tight * (0.4 + progress);

    // Penalize dead space that cannot fit the (known) next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += 18.0 * waste * waste * (1.0 + 2.0 * progress);
        // Reward if post residual still fits the next item.
        if nx <= pr {
            score -= 8.0 * (1.0 - x) * (1.0 + progress);
        }
    }

    // Last-chance bonus: only one open bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        // Mild penalty when many bins compete, to prefer best fit naturally.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin has x == 1.0.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; relax the penalty as open bins grow
        // and stream progresses (diversification late in stream).
        score += 25.0 + 0.6 * open_bins_count as f64 - 10.0 * progress;
        // If nothing else fits well (large item), opening new bin is fine.
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Coupling with mean residual: prefer bins deviating smoothly from mean
    // to balance load, weighted by a smooth quadratic term.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild smooth preference for larger items filling bins snugly.
    score -= 4.0 * (item_size as f64 / cap) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (hard to fill later) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows superlinearly for tiny unusable leftovers.
    if post_residual > 0 {
        let dead = (cap - pr) / cap; // fraction filled
        score -= 12.0 * dead * dead; // reward tight fits
        if post_residual < 10 {
            score += 25.0; // near-unusable sliver
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Modulo-class logic on post_residual: leftovers in [1..=5] or
    // exactly divisible by large divisors are typically dead space.
    let m = post_residual % 10;
    if m != 0 && m <= 5 {
        score += 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0; // clean quarter-class residue, reusable
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let after2 = post_residual - next_item_size;
            score -= 10.0 * (1.0 - after2 as f64 / cap);
            if after2 < 10 {
                score += 10.0; // leaves another sliver
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins unless current residual
    // is small relative to the item and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0; // only open new bins when nothing decent fits
        }
    }

    // Prefer bins with residual close to item size (tight packing).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    // Mild pressure to consolidate: prefer bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit the
    // minimum item (size 1..=10) are pure waste — penalize hard.
    if post_residual < 10 {
        score += 25.0;
    }
    // "Awkward gap" zone: 10..=20 can only hold tiny items; mild penalty
    // unless the next item actually fits into it.
    if post_residual >= 10 && post_residual < 20 {
        if (next_item_size as u32) > post_residual || next_item_size == 0 {
            score += 8.0;
        } else {
            score -= 5.0; // lookahead confirms the gap is usable
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.05 * item_size as f64;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when it enables a better packing
    // (e.g., current best fits are all sloppy and next item is large).
    if bin_residual == bin_capacity {
        let sloppy = (post_residual as f64) > 0.35 * bin_capacity as f64;
        if sloppy && next_item_size >= 40 {
            score -= 10.0;
        } else {
            score += 10.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Slight nudge toward bins whose residual deviates from the mean
    // (prefer filling unusually empty bins when mean is high).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

