}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: best-fit core (prefer tight packing)
    let mut score = post;

    // Fill-ratio coupling: reward bins that end up well-utilized
    let fill = (bin_residual as f64 - post) / cap; // == item/cap, but keep form
    score -= 12.0 * fill * fill;

    // Dead-space penalty: small post_residual that cannot hold typical future items
    if post > 0.0 && post < 10.0 {
        score += 8.0 * (10.0 - post);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if nxt > 0.0 && nxt <= post_residual {
        score -= 15.0 + 0.2 * nxt;
    } else if nxt > 0.0 && nxt > post_residual && nxt <= bin_residual {
        // next item would have fit this bin now but not after placement
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global residual pressure: many open bins with slack -> consolidate
    let pressure = mean_residual / cap;
    score += 10.0 * pressure;

    // Time horizon: late in stream, avoid opening new bins
    let t = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New-bin candidate: penalize, but relax when item is large or no alternatives
        let big_item = item / cap;
        let no_choice = (fitting_bins_count as f64 - 1.0).max(0.0) == 0.0;
        let mut new_bin_pen = 55.0 + 60.0 * t;
        new_bin_pen -= 45.0 * big_item;
        if no_choice {
            new_bin_pen = 15.0;
        }
        // If item is huge and would leave big dead space elsewhere anyway
        if item >= 70 {
            new_bin_pen -= 20.0;
        }
        score += new_bin_pen;
    } else {
        // Reward using existing bins, more so early (keeps options open later)
        score -= 5.0 * (1.0 - t);
        // Mild reward proportional to how well the item plugs the residual gap
        score -= 3.0 * (item / res);
    }

    // Open-bin count regularization: discourage bin proliferation
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), scaled by polynomial in progress
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear polynomial coupling: penalize mid-range dead space more as stream progresses
    let mid = (x - 0.5).abs();
    score += 40.0 * mid * mid * (1.0 + 2.0 * progress);

    // Penalize residuals too small to be useful for typical items (dead space)
    let useless = (1.0 - (x * 10.0)).max(0.0);
    score += 60.0 * useless * useless * x;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap >= 0.0 {
            score -= 12.0 * gap * (1.0 - gap);
        } else {
            score += 8.0 * (-gap) * (1.0 + progress);
        }
    }

    // Slight preference for consolidating into fewer bins early on
    score += 0.5 * open_bins_count as f64 * progress;

    // Deviation from mean residual: prefer bins near the mean to balance load
    score += 0.05 * (pr - mean_residual).abs();

    // Mild bonus for tight fits relative to item size
    score -= 10.0 * (item_size as f64 / cap) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    // Residuals that are multiples of 10 are "harmonic" — highly reusable by typical item sizes.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0; // reward leaving a clean multiple-of-10 gap
    } else {
        // penalize awkward leftovers proportional to how far from a multiple of 10
        let dist = (post_residual % 10).min(10 - post_residual % 10);
        score += dist as f64 * 1.5;
    }

    // Integer division thresholds on post_residual: tiny dead space is wasted capacity.
    if post_residual < 10 {
        score += 25.0; // unusable dead space
    } else if post_residual / 10 == 1 {
        score += 8.0; // 10..19 barely usable
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 15.0; // perfect pair closure
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for blocking a better split
        score += 3.0;
    }

    // Last-chance bin: strongly favor filling the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Perfect fit bonus: closing a bin exactly is always optimal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer tighter (smaller residual) bins among fitting bins.
    score += (bin_residual as f64) * 0.05;

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when current bins would leave bad dead space or nothing fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // cheaper to open a new bin when many bins are open with fragmented space
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // if the next item is large and current mean residual is small, new bin is good
        if (next_item_size as f64) > mean_residual + 10.0 {
            score -= 8.0;
        }
        // late in the stream, opening new bins is less costly (fewer future pairings lost)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good tight fit.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a typical item are wasted -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 40.0;
    }
    // Small unusable gaps (cannot fit even a modest future item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward very tight fits (low post residual relative to item size).
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let tightness = post_residual as f64 / (item_size.max(1) as f64);
        score -= 20.0 / (1.0 + tightness);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // filling existing bins; few open bins -> new bins are cheap.
    let pressure = open_bins_count as f64;
    score += 0.6 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean residual (compact bins),
    // penalize placing into already-large-residual bins when many are open.
    score += 0.15 * pressure * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 / (1.0 + slack / 10.0);
    }
    // If next item would NOT fit here, mild penalty so chains stay coherent.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate handling: empty bin should win only when current
    // bins are poor fits or nearly full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are open
        // and residual space is fragmented.
        score = bin_capacity as f64 * 0.9
            + 4.0 * pressure
            - 10.0 * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin is useful for the upcoming big item
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (perfect chained fit).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits here afterwards: reward tightness of the chain.
            let chain_tightness = 1.0 - ((post - nxt) / bin_capacity as f64);
            score -= 30.0 * chain_tightness;
            // Exact match bonus: post_residual == next_item_size.
            if (post - nxt).abs() < 0.5 {
                score -= 40.0;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            let dead = post / bin_capacity as f64;
            score += 25.0 * dead * dead;
        }
    }

    // Compare residual against the mean residual of open bins:
    // prefer placing into bins that are below-average full (large residual)
    // so tight bins stay available for small items.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 10.0 * rel;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // the item is large relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        let new_bin_score = 60.0 - 40.0 * large_item - 20.0 * progress;
        score = score.max(new_bin_score);
    }

    // Small penalty for very tight fits that leave slivers (< 10 units),
    // which are nearly unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= 2.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * item_size as f64;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin if this one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving a gap just below next item size.
        score += 4.0;
    }

    // Time horizon: early in stream, prefer consolidating (favor fuller bins);
    // late in stream, be more tolerant of opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins with high mean residual: prefer reusing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when current bin residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // But if this bin is the only fitting one and lookahead is awkward, new bin less bad.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 12.0; // new bin leaves room for big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: reward small post_residual with polynomial decay
    let x = pr / cap; // normalized post-residual in [0,1]
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Penalize large dead space non-linearly (cubic)
    score += 8.0 * x * x * x * (1.0 + 2.0 * progress);

    // Perfect fit bonus (smooth gaussian-like kernel around zero residual)
    score -= 15.0 * (-(x * 12.0) * (-(x * 12.0)));

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (x - nx).abs();
        score -= 10.0 * (-(fit_gap * 8.0) * (-(fit_gap * 8.0)));
        if nx > x {
            score += 6.0 * (nx - x); // next item won't fit: mild penalty
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Mean residual context: prefer bins below mean residual (tighter packing)
    let mr = mean_residual / cap;
    score += 5.0 * (x - mr) * (x - mr);

    // Stream-progress drift: later in stream, be more tolerant of new bins
    score -= 3.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod small integers
    // capture "nice" leftover sizes that future items (10..80) can pair with.
    let pr = post_residual;
    let r8 = (pr % 8) as f64;
    let r10 = (pr % 10) as f64;
    let r16 = (pr % 16) as f64;

    // Reward residuals that are multiples of common size classes (harmonic fits).
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 20 == 0 { score -= 4.0; }
    if pr % 25 == 0 { score -= 3.0; }
    if pr % 50 == 0 { score -= 3.0; }
    // Penalize awkward residues far from any multiple of 10.
    score += (r10 - 5.0).abs() * 0.4;
    score += (r8 - 4.0).abs() * 0.2;
    score += (r16 - 8.0).abs() * 0.1;

    // Dead space penalty: tiny unusable leftovers.
    if pr > 0 && pr < 10 {
        score += 12.0 * (10 - pr) as f64;
    }
    if pr == 0 { score -= 15.0; } // perfect fit is excellent

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let nxt_res = pr - next_item_size;
            score -= 5.0;
            if nxt_res % 10 == 0 { score -= 4.0; }
            if nxt_res < 10 { score += 6.0; }
        } else {
            // next item won't fit here; leftover must stand alone.
            score += 2.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin only late in the stream or when few bins fit,
        // or when the current item is huge and would leave a bad remainder elsewhere.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_leftover = (pr > 0 && pr < 10) as f64;
        score += 30.0; // base cost of opening a new bin
        score -= 25.0 * bad_leftover;
        if fitting_bins_count == 0 { score -= 40.0; }
        if item_size >= 80 { score -= 5.0; }
        if progress > 0.8 && open_bins_count > 0 { score -= 2.0; }
        // Keep new-bin attractive if it would preserve tight packing elsewhere.
        if mean_residual > 40.0 && pr > 40 { score -= 3.0; }
    }

    // Mild preference for tighter (fuller) bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;
    // Slight tie-break toward bins whose residual is below the mean (consolidation).
    if (bin_residual as f64) < mean_residual { score -= 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_useful = if next_item_size > 0 { next_item_size.min(item_size).min(20) } else { 20 };
    if post_residual < min_useful {
        // Dead space penalty scales with how close we are to wasting the whole gap.
        score += 30.0 * (1.0 - post_residual as f64 / min_useful as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (bin_capacity as f64 / item_size.max(1) as f64).max(1.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; but relax if existing residuals are large/wasteful.
        score += 20.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    // Lookahead: if next item would fit exactly in the resulting residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // residual likely dead for next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus (2-step lookahead: next item exactly fills post_residual)
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 60.0; // chainable perfect fit: strongly prefer
        } else if post_residual >= next_item_size {
            // next item fits after this one: mild bonus scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - tight * 0.3;
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 {
                score += gap * 0.4;
            }
        }
    } else {
        // last item: maximize packing tightness
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward tight fits relative to mean residual
    let mr = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let tightness = (post_residual as f64) / mr;
    score -= (1.0 - tightness) * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny dead space (< 10) that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // more open bins => prefer reusing; scale penalty
        score += open_bins_count as f64 * 1.5;
        // if other bins fit the item, discourage new bin more
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // if no other bin fits (fitting_bins_count == 1 means only this new bin),
        // opening is necessary: reduce penalty
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // lookahead: if next item also fits in a fresh bin alongside, encourage
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (bin consolidation)
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Slight preference to pack earlier bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: penalize less when item nearly fills the bin
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Perfect fill gets a big reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 3.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        let mut nb = 15.0 + post_residual as f64; // post_residual == capacity here
        // open new bin more willingly early, or when mean residual of open bins is large (fragmented)
        nb -= 10.0 * (1.0 - progress);
        nb += 0.15 * mean_residual;
        nb -= 2.0 * open_bins_count as f64;
        // if next item is large and open bins are fragmented, new bin is attractive
        if next_item_size >= 60 && mean_residual < next_item_size as f64 {
            nb -= 20.0;
        }
        score += nb;
    }

    // Mild preference to fill bins with smaller residuals first (best-fit-like)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large post_residual super-linearly).
    // Late: dead space is costlier, so coupling intensifies with progress.
    let coupling = norm_post * norm_post * (0.5 + progress) * cap;
    score += coupling;

    // Smooth reward for near-perfect fits, stronger late in the stream.
    let fit_quality = 1.0 - norm_post;
    score -= fit_quality * fit_quality * (10.0 + 40.0 * progress);

    // Penalize tiny unusable residuals (dead space) smoothly.
    if post > 0.0 {
        let dead = (1.0 - post / item_size.max(1) as f64).max(0.0);
        score += dead * dead * 5.0;
    }

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 / cap).min(1.0);
        if post >= next_item_size as f64 {
            score -= 15.0 * fits_next * (1.0 + progress);
        } else {
            score += 8.0 * fits_next * (1.0 - progress);
        }
    }

    // Mild penalty for proliferating bins relative to mean residual.
    score += (open_bins_count as f64).ln() * mean_residual * 0.02;

    // New-bin candidate: mildly discourage unless residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" classes (small leftovers)
    // are rewarded; large dead-space classes are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Integer-division thresholds on post_residual (harmonic classes of 100):
    // class 0: 0..=5   (perfect fit)
    // class 1: 6..=15  (tiny item slot)
    // class 2: 16..=30 (medium slot)
    // class 3: 31..=50 (half bin)
    // class 4: >50     (dead space)
    let class = if post_residual <= 5 { 0 }
        else if post_residual <= 15 { 1 }
        else if post_residual <= 30 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    match class {
        0 => score -= 40.0,                       // near-perfect packing
        1 => score -= 18.0,                       // still very good
        2 => score -= 6.0,                        // acceptable
        3 => score += 10.0,                       // wasteful
        _ => score += 25.0,                       // severe dead space
    }

    // Smooth component: quadratic penalty on large leftover fraction.
    score += 20.0 * frac * frac;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    // (perfect chained fit), penalize if next item cannot use the leftover at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;                        // ideal chain
        } else if next_item_size <= post_residual {
            // how well the next item uses the leftover
            let use_frac = next_item_size as f64 / post;
            score -= 15.0 * use_frac;
        } else {
            // leftover too small for next item: dead space likely
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(50.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // is a decent fit. Penalize it when good alternatives exist.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open a bin early when few bins are open (spreading load)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress) * (1.0 - open_bins_count.min(8) as f64 / 8.0);
        // if the item is huge relative to capacity, new bin is fine
        score -= 0.4 * (item_size as f64 - cap * 0.5).max(0.0);
        // if open bins are crowded (low mean residual), new bin less costly
        score -= 0.25 * (cap * 0.5 - mean_residual).max(0.0);
    } else {
        // mild preference for filling more-open bins when many bins exist
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 9) are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 80.0;
    } else {
        // Larger gaps are more reusable; reward proportionally.
        score -= (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Reward tightness: small post_residual relative to residual.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 30.0;

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would not fit in the dead space left, penalize slightly.
    if next_item_size > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Early in stream: keep bins open and consolidated; late: prefer closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: baseline cost of opening a fresh bin, adjusted by pressure.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Reward tight two-item packing strongly.
        score -= 40.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        // Extra reward for perfect chain (post_residual == next_item_size).
        if slack_after_next == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placing current item; penalize proportionally
        // to how badly it misses, scaled by stream progression.
        let miss = (next_item_size - post_residual) as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.15 * miss * (0.5 + progress);
    }

    // Penalize creating tiny dead space that likely nothing can use (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer bins with residual already below mean (consolidating small residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // If item is big relative to capacity, opening fresh bin is more acceptable.
        let size_relief = item_size as f64 / bin_capacity as f64 * 35.0;
        let early_bonus = (1.0 - step_index as f64 / total_items.max(1) as f64) * 10.0;
        score += base + pressure * 25.0 - size_relief - early_bonus;
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of the fit: small post_residual relative to capacity is good
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness; // penalize large dead space quadratically

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is very valuable (perfect chaining)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) <= 8 {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 8 {
            // next item barely misses: leaving slightly more space could help
            score += 6.0;
        }
        // If next item is large and this bin would be left nearly empty anyway,
        // keep larger residual for it
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 4.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins as open-bin count grows (encourage consolidation)
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But if no open bin fits well (fitting bins exist but this is a fresh call),
        // opening a bin is fine early; reduce penalty late when mean residual is low
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in stream, prefer closing out existing bins
        score += 15.0 * progress;
        // If mean residual across open bins is small, new bin is justified
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Mild reward for using existing bins, scaled by how full they already are
        let used_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * used_fraction;
    }

    // Global pressure: when many open bins exist, tighten scoring to merge loads
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early on be exploratory (flatter scores), late be greedy (sharper)
    let sharpness = 1.0 + 2.0 * progress;
    score *= sharpness;

    // Small tie-breaker favoring bins with residual close to mean (balanced depletion)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear penalty for awkward leftovers
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * (1.0 - norm_pr)
        - 25.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Tight fits are strongly rewarded, smoothly
    let fit_tightness = 1.0 - norm_pr;
    score -= 30.0 * fit_tightness * fit_tightness * fit_tightness;

    // Stream progress coupling: later in the stream, waste matters more
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Dead-space penalty grows quadratically when residual is too small for typical items
    let dead_zone = (norm_pr * 100.0 / 80.0).min(1.0);
    score += 20.0 * (1.0 - dead_zone) * (1.0 - dead_zone) * progress;

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap);
    }

    // Penalize placements into bins far below mean residual (fragmentation signal)
    score += 0.15 * (mean_residual - pr).abs().powf(1.5) / cap;

    // Mild penalty for spreading across many open bins early
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral-ish, slightly penalized unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of small denominators) are more valuable.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that divide cleanly into small classes (2,4,5,10,20,25,50)
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr % 4 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -3.0
    } else {
        4.0 // odd residuals are awkward
    };
    score += harmonic_bonus;

    // Integer-division threshold: leftover >= 25 is "reusable", < 25 is dead space
    if pr >= 25 {
        score -= 6.0;
    } else if pr > 0 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after chain matters
            let chain_left = pr - next_item_size;
            score -= 8.0;
            if chain_left % 10 == 0 {
                score -= 5.0;
            }
            if chain_left < 10 && chain_left > 0 {
                score += 6.0;
            }
        } else {
            // next item won't fit here; penalize wasting a large residual on
            // a small item unless this is the last-chance bin
            if pr > next_item_size * 2 {
                score += 5.0;
            }
            if fitting_bins_count == 1 {
                score -= 15.0; // last chance: take it anyway
            }
        }
    }

    // Capacity-fraction penalty: avoid leaving residuals in the awkward band
    // (cap/4, cap/2) exclusive zone where few item classes fit.
    let frac = pr as f64 / cap;
    if frac > 0.25 && frac < 0.5 {
        score += 4.0;
    } else if frac >= 0.5 {
        score -= 4.0;
    }

    // Prefer filling bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score += 20.0 * tightness;

    // Slight preference to keep fewer open bins when residuals are healthy
    if open_bins_count > 3 && mean_residual > 40.0 {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 12.0 + (fitting_bins_count as f64) * 2.0;
            if next_item_size > 0 && next_item_size >= 50 {
                score -= 6.0; // big next item: fresh bin may help
            }
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 10 {
        // Usable residual: reward proportional tightness mildly.
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 9 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize if post-residual is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if this item is a last-chance fit nowhere else, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strongly favor using it.
        score -= 35.0;
    }

    // Mild pressure to fill bins with high residual relative to mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward closeness of post_residual to next item size.
        score -= 40.0 / (1.0 + gap * 0.15);
        // Penalize residuals that can never hold the next item (dead space risk)
        if post_residual < next_item_size {
            score += 8.0 + gap * 0.1;
        }
    } else {
        // Last item: prefer the tightest possible fit.
        score -= 20.0;
    }

    // Reward filling bins below mean residual (tightening crowded bins).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving large unusable chunks relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 30 {
        score += 3.0; // awkward medium dead space
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / (1.0 + progress);
        score += 30.0 - pressure * 2.0;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 12.0; // fresh bin can host current + next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract more as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: strongly reward leaving exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            // Mild reward proportional to how much slack remains after next item.
            let rem = post_residual - next_item_size;
            score -= 8.0 * (1.0 - rem as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty: next item cannot use the leftover.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 10.0 * waste * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins with large mean residual -> prefer consolidating into
    // already-open bins rather than spreading.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        let consolidation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 6.0 * consolidation;
    }

    // Late in the stream: tighten up, avoid leaving large unusable residuals.
    if progress > 0.7 {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: baseline cost of opening a fresh bin. It gets the raw
    // post_residual (large), plus an opening penalty that shrinks when existing
    // bins would leave big wasted space or when the item is large.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If no open bin can fit the item, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Large items waste less in a fresh bin relative to a cramped fit.
        score -= 4.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized leftover space
    let norm_left = pr / cap;
    score += 12.0 * norm_left * norm_left * cap;

    // Reward tight fits: subtract when post_residual is small relative to item
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Smooth stream-progress coupling: later in stream, penalize leftovers more
    let prog_coupling = progress * progress * (3.0 - 2.0 * progress);
    score += 15.0 * prog_coupling * norm_left;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - norm_left);
    }

    // Lookahead: penalize if post_residual can't fit next item but is non-trivial
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            // reward residual that can host the next item, scaled by how snugly
            score -= 6.0 * (nx / cap);
        } else {
            score += 5.0 * (1.0 - pr / nx.max(1.0)) * norm_left;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates usefully from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: discourage opening new bins unless leftovers elsewhere are bad
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * mean_residual / cap + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5 classes (0, (0,25], (25,50], (50,75], (75,100))
    let class = if post_residual == 0 {
        0u32
    } else if post_residual <= bin_capacity / 4 {
        1
    } else if post_residual <= bin_capacity / 2 {
        2
    } else if post_residual <= 3 * bin_capacity / 4 {
        3
    } else {
        4
    };

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward leaving residuals in "usable" harmonic classes (>=25 usable by any item size 10..80 in classic range;
    // for unknown 1..100 range, favor classes that next_item_size can fill exactly)
    let usable = (class as f64) * 8.0;
    score -= usable;

    // Dead-space penalty: post_residual smaller than the smallest plausible item (harmonic floor)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Modular coupling: if next_item_size exactly matches post_residual -> near-perfect lookahead fit
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // lookahead fits: reward by how much slack remains after next item
            let post2 = post_residual - next_item_size;
            score -= 40.0 - (post2 as f64).min(40.0);
            if post2 == 0 {
                score -= 120.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by mismatch class
            let mismatch = next_item_size - post_residual;
            score += (mismatch as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave tiny dead space
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = 100.0;
        // opening is attractive if item is large (fills new bin well)
        score -= (item_size as f64) * 0.9;
        // less attractive when many open bins still have room (mean residual high)
        score += (mean_residual / bin_capacity as f64) * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0; // room for lookahead item
        }
    }

    // Prefer tighter bins generally: scale by fullness
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight stream-progression modulation: later in stream, conserve bins more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Threshold scales with the lookahead item.
    let min_useful = if next_item_size > 0 {
        (next_item_size as f64 * 0.9).min(80.0)
    } else {
        10.0
    };

    if post_residual > 0 && (post_residual as f64) < min_useful {
        // Dead space penalty: quadratic in how far below the useful threshold.
        let gap = min_useful - post_residual as f64;
        score += gap * gap * 0.35;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if (post_residual as f64) >= min_useful {
        // Residual stays reusable for the lookahead item: mild reward.
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless the
    // fit is genuinely good. Scales with fraction of stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(0.6) * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates badly from the mean residual
    // (prefer consistent packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: neutral-ish baseline; only attractive when the best
    // existing option is poor. Give it a moderate default so tight fits in
    // open bins win, but very poor fits trigger a new bin.
    if bin_residual == bin_capacity {
        // New bin: residual after placement = capacity - item_size, usually
        // large, so base score is already high; add a fixed opening cost.
        score += 12.0;
        // If nothing fits well anywhere, make the new bin more attractive.
        if post_residual >= 20 && open_bins_count > 0 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item would fit exactly in the
    // post-residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: strongly reward small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly or nearly fills
    // the post_residual, this is an excellent chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward proportionally to how well next item nests in leftover.
            score -= 25.0 * (1.0 - gap / (post_residual as f64).max(1.0));
        } else {
            // Next item cannot fit in leftover: penalize relative to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.35 * overshoot;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 20.0 * tightness;
    }

    // Compare against mean residual: bins with residual well below mean are
    // the "small leftovers" we want to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 0.10 * ((bin_residual as f64) - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize creating tiny dead space (< ~10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: penalize moderately so we only open new bins when
    // no open bin offers a decent fit (post_residual near full capacity).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 15.0 * progress;
        // If the item leaves a large residual anyway, opening fresh is fine.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for bins that will become exactly full.
    if post_residual == 0 {
        score -= 35.0;
    }

    // Mild scaling with item size: large items should go into bins that can
    // still host them comfortably.
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual (chaining),
    // penalize if this placement strands space just above/below next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // wasted space relative to next item
            let gap = (next_item_size - post_residual).min(40) as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Penalize new-bin candidate unless it is genuinely better than all fits:
    // a fresh bin should only win when the item is large and fits are sloppy.
    if bin_residual == bin_capacity {
        let fit_slack = if fitting_bins_count > 0 {
            mean_residual
        } else {
            bin_capacity as f64
        };
        let sloppiness = (post_residual as f64) / bin_capacity as f64;
        // Opening a new bin is attractive when item is big and existing residuals are tight.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 30.0 * item_frac - 0.4 * fit_slack + 20.0 * sloppiness;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Too many open bins: discourage opening more.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild global pressure: when mean residual is high, prefer filling fat bins.
    score -= 0.15 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    // Small penalty for very small items going into large-residual bins early on.
    if item_size < 20 && post_residual > 50 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: quadratic waste penalty on normalized post residual
    let mut score = 1.0 + 2.0 * pr + 1.5 * pr * pr;

    // Smooth non-linear coupling with stream progress: late in stream, waste matters more
    let progress_coupling = (progress * std::f64::consts::PI).sin();
    score += 3.0 * pr * pr * (0.5 + 0.5 * progress_coupling);

    // Tight fit reward: strong bonus for small post_residual, amplified by progress
    let tightness = 1.0 - pr;
    score -= 2.5 * tightness * tightness * (0.5 + progress);

    // Penalize bins far below mean residual (bad global fit), smooth cubic coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev * dev.abs().sqrt() * (1.0 + progress);

    // Last-chance bin: reward strongly when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - pr);
    } else {
        // mild penalty spread across many fitting bins to prefer concentrated fills
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_q = (next_item_size as f64 / post.max(1.0)).min(1.0);
        score -= 2.0 * fit_q * fit_q;
    }
    // Penalize near-miss residuals that can't fit next item
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post {
        score += 0.5 * pr;
    }

    // New-bin candidate: neutral-ish score scaled by open bins count and progress
    if bin_residual == bin_capacity {
        score = 0.9 + 0.05 * (open_bins_count as f64) + 0.4 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "usable"
    // by common small-item classes (multiples of 10, then halves/quarters).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // class bonus by divisibility of post residual
        if pr % 10 == 0 { score -= 18.0; }
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 5 == 0 { score -= 4.0; }
        // dead-space penalty grows super-linearly for small unusable residuals
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        } else if pr < 20 {
            score += (20 - pr) as f64 * 1.5;
        }
    }

    // Integer-division threshold classes on residual before placement
    let cls = bin_residual / 25; // 0..=4 quartile class
    score -= cls as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally to how well it fills
            let fill = next_item_size as f64 / pr.max(1) as f64;
            score -= 12.0 * fill;
            if (pr - next_item_size) % 10 == 0 { score -= 6.0; }
        } else {
            // next item cannot use this residual: penalize small leftovers more
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 55.0;              // base cost of a fresh bin
        score -= 35.0 * progress;   // late in stream, consolidation matters more
        score -= crowding.min(30.0); // many open bins with small residuals -> prefer fresh
        if item_size > 60 { score -= 10.0; } // big items start fresh bins more readily
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // pair fits together in the new bin
        }
    }

    // Mild tie-break: prefer bins whose residual is closest to the item (tight fit)
    score += (bin_residual - item_size) as f64 * 0.05;
    // Slight preference for fewer open bins overall
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to fit any plausible future item
    // (items in [1,100], but small gaps below ~10 are nearly worthless).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0; // hard-to-fill gap
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room exactly for the lookahead item (k=2 lookahead synergy)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0; // kills the lookahead placement
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: consolidate when many bins are open
    score += 2.0 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit flavor)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty for leaving awkward gap
            score += 5.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with below-average residual
    // (denser bins) unless this is a last-chance bin.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // fitting bins exist or stream is early (many future items to place).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
        // opening a bin is more acceptable when it enables a perfect 2-step chain
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 45.0;
        }
    }

    // Mild preference to consolidate when many bins are open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to bin capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness * tightness);

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 35.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Dead space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.05 * next_item_size as f64;
            // chain fit: post residual after next item would be tiny
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; slightly penalize leaving awkward gap
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap < 15.0 {
                score += 6.0;
            }
        }
    }

    // Last chance: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer the tightest among many candidates (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - tightness);

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= 0.3 * (open_bins_count as f64).ln();
        if mean_residual > item_size as f64 {
            score -= 2.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline for opening a new bin: slightly worse than a decent fit,
        // better than a terrible fit (large post_residual with bad lookahead).
        score += 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can always host the next item
            score -= 4.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear penalty on post_residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (penalize waste harder).
    let coupling = 2.5 * progress * (1.0 - progress) * (1.0 - progress);
    score += pr * coupling;

    // Smooth reward for near-exact fills (post_residual near 0), stronger late.
    let tightness = (-norm_pr * 6.0).exp();
    score -= 12.0 * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-penalized so it is
    // chosen only when open bins would leave large unusable dead space.
    if bin_residual == bin_capacity {
        // Penalize opening new bins when plenty of open bins fit the item well.
        let fit_pressure = fitting_bins_count as f64;
        score += 8.0 + 2.0 * fit_pressure;
        // But if the item is large relative to capacity and mean residual is high,
        // opening a fresh bin becomes attractive (smooth term).
        let size_frac = item_size as f64 / cap;
        score -= 10.0 * size_frac * size_frac * (mean_residual / cap);
        // Late-stream smoothing: discourage hoarding empty bins near the end.
        score += 6.0 * progress;
    }

    // Lookahead: if next item fits exactly into this post_residual, reward strongly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let match_score = if (pr - next).abs() < 0.5 { 1.0 } else { 0.0 };
        score -= 15.0 * match_score * (1.0 - progress);
        // Smooth version: reward small gap between post_residual and next item.
        let gap = (pr - next).abs() / cap;
        score += 5.0 * gap * (1.0 - progress);
        // Penalize if next item would not fit here (post_residual too small).
        let no_fit = if pr < next { 1.0 } else { 0.0 };
        score += 3.0 * no_fit * (1.0 - progress) * (pr / cap);
    }

    // Mild global pressure: more open bins -> prefer consolidating into existing ones.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions
    // (multiples of 10, 25, 50) are "usable" for future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post-residuals that are multiples of common item granularity.
    if post_residual % 10 == 0 { score -= 12.0; }
    if post_residual % 25 == 0 { score -= 8.0; }
    if post_residual % 50 == 0 { score -= 6.0; }

    // Penalize awkward dead-space bands: 1..=9 leftover is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Mid-band dead space (11..=19) is also poor unless a small item follows.
    else if post_residual >= 11 && post_residual <= 19 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let new_pr = post_residual - next_item_size;
            score -= 10.0;
            if new_pr < 10 { score += 8.0; } // but avoid creating new dead space
        } else {
            // next item won't fit here: penalize proportionally to wasted space
            score += (next_item_size as f64 - pr).min(cap) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit win.
        score += 20.0;
        // But if the stream is early or many bins open with poor mean residual,
        // opening fresh is attractive: subtract based on mean residual tightness.
        let tight = (mean_residual / cap).clamp(0.0, 1.0);
        score -= tight * 35.0;
        if post_residual % 10 == 0 { score -= 5.0; }
    }

    // Progress modulation: later in stream, prefer tighter packing (lower post-residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += pr * (0.1 + 0.4 * progress);

    // Slight penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Integer-division threshold: reward post_residual in the "fillable" class [20..60]
    let cls = post_residual / 20; // 0..=5
    score -= match cls {
        1 => 6.0,        // 20..39: good for medium items
        2 => 4.0,        // 40..59: good for large-ish items
        3 => 2.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0 - pr as f64 * 3.0; // dead space in [1,9] is nearly worthless
    } else if pr < 20 {
        score += 12.0 - pr as f64 * 0.5;
    } else if pr == 0 {
        score -= 25.0; // perfect fit is strongly rewarded
    }

    // Reward using tight residual bins when they are the last chance.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5 + 20.0 * (1.0 - progress);
    } else {
        score -= open_bins_count as f64 * 0.4;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // creates a gap the next item can't use
    }

    // Slight preference toward bins below mean residual (consolidating emptier bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (low post_residual), but reward when the leftover
    // exactly matches the next item's size (2-step lookahead pairing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += gap * 0.9;                      // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 12.0;                       // perfect chaining: bin closes next step
        }
        // If next item cannot fit anywhere else, this bin's leftover matters more
        if post_residual < next_item_size {
            score += 4.0;                        // dead space relative to lookahead
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "almost full",
    // favor filling them to close them out.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + item_size as f64 * 0.05;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.2;
        if post_residual as f64 > mean_residual {
            score += 3.0; // opening a bin with big expected leftover is bad
        }
    }

    // Late in the stream, consolidate aggressively to avoid many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 * progress);

    // Small bonus for leaving residuals that are unlikely to be usable (below min item).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that nothing could ever use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // this bin is a great host for a two-item chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 22.0 * chain_fit;
    } else if next_item_size > 0 {
        // Next item cannot follow here: slight penalty, scaled by how much
        // of the stream remains (late in the stream, chains matter less).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer the best-fitting one, mildly penalize others.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: when many bins are open with fat mean residual, opening
    // new bins is wasteful — penalize the new-bin candidate.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let residual_pressure = mean_residual / (bin_capacity as f64);
    score += new_bin * (14.0 + 20.0 * residual_pressure + 1.5 * open_bins_count as f64);

    // But late in the stream, prefer consolidating into open bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += new_bin * 25.0 * progress;

    // Perfect-fill bonus: residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Time-horizon modulation: early on, keep bins flexible (avoid tiny
    // residuals); late, squeeze everything.
    score += (post_residual as f64).powf(0.5) * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize key quantities
    let pr = post_residual as f64 / cap;             // post residual in [0,1]
    let ir = item_size as f64 / cap;                 // item size in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_r = mean_residual / cap;                // mean residual normalized

    // Smooth non-linear polynomial coupling: penalize mid-range wasted space,
    // reward tight fits (small post_residual) with a quadratic-quartic blend.
    let tightness = (1.0 - pr) * (1.0 - pr);         // high when item fills bin well
    score -= 6.0 * tightness * (0.5 + 0.5 * progress);

    // Quartic penalty on residual near mid-capacity (awkward dead space zones)
    let mid = pr - 0.5;
    score += 2.5 * mid * mid * mid * mid;

    // Cubic decay reward: residual close to zero is excellent
    score -= 3.0 * (1.0 - pr).powi(3);

    // Lookahead coupling: if the next item fits the resulting residual, reward;
    // smooth quadratic interaction between next-item fit and post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            score -= 2.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * (0.4 + 0.6 * progress);
        } else {
            // next item won't fit here; mild penalty growing with how far off
            score += 1.5 * (-fit_gap) * (-fit_gap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * ir;
    }

    // Stream-progress scaling: as the stream advances, be greedier about
    // filling existing bins (smoothly increasing weight on post_residual).
    score += score * 0.25 * progress * pr;

    // Contextual pressure: many open bins with high mean residual -> prefer
    // packing into existing bins rather than opening new ones.
    let pressure = mean_r * (open_bins_count as f64).ln1p();
    score -= 1.2 * pressure * (1.0 - pr);

    // New-bin candidate penalty: an empty bin has pr == 1.0; discourage opening
    // a new bin unless the item is large and the stream is late.
    if bin_residual == bin_capacity {
        let large_item_bonus = ir * ir;
        let threshold = 0.55 - 0.25 * progress - 0.15 * large_item_bonus;
        if pr > threshold {
            score += 10.0 - 6.0 * progress - 5.0 * ir * ir;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (best-fit), but treat near-zero residual as ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals in (0,10] are "dead space" class -> penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64;
    }

    // Integer-division thresholds: classify post_residual into capacity eighths.
    let eighth = bin_capacity / 8; // 12
    let post_class = post_residual / eighth;
    match post_class {
        0 => score -= 20.0,          // residual < 12: nearly closed, good
        1 => score += 5.0,           // 12..24: awkward pocket
        2 => score -= 8.0,           // 24..36: can hold mid items
        3 => score += 2.0,
        4 => score -= 5.0,           // half-full: flexible
        5 => score += 0.0,
        6 => score -= 3.0,
        _ => score += 0.0,           // nearly empty bin
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward, scaled by tightness of chain.
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 + (post_residual as f64 - next_item_size as f64).min(20.0);
            let _ = slack_after_next;
        } else {
            // Next item cannot use leftover: penalize if leftover is small (dead space).
            if post_residual < next_item_size && post_residual > 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; slightly worse than a good fit, better than dead space.
        score = (bin_capacity - item_size.min(bin_capacity)) as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing potential with large items
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        return score;
    }

    // Reward bins that are already well-loaded (consolidation), via mean residual coupling.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Many open bins: encourage filling existing ones harder.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight-fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a gap that is too small for the lookahead item but large enough to be wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 12.0;
    }
    // Reward if the lookahead item fits exactly in the resulting gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: full residual plus a pressure term.
        score = bin_capacity as f64 + 8.0 * (open_bins_count as f64).sqrt();
        // Only allow new bin if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score += 10.0; // last-chance bin should be preferred over new bin
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that can fit: strong reward to use it.
        score -= 35.0;
    }

    // Mild preference for balancing residuals against the mean.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits comfortably in the leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use the leftover: penalize dead space more strongly
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits relative to bin capacity (small post_residual is good)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Compare against mean residual: bins with residual close to mean keep balance;
    // leaving residual far below mean wastes potential
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across too many open bins when a tight fit exists
    if open_bins_count > 4 && post_residual < 10 {
        score -= 10.0;
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when leftovers are large and unusable
        score += 30.0 + 40.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= 2.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 10.0;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward leaving exactly enough room for the next item (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Prefer bins below mean residual (keeps residual distribution balanced).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in stream, be conservative about filling bins tightly;
    // late in stream, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor filling existing ones.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when item is huge relative to
    // residual alternatives or nothing fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        // Fresh bin penalty grows with number of fitting alternatives.
        score += 10.0 + fitting_bins_count as f64 * 2.0;
        // But reward opening fresh bin for very large items late in stream.
        score -= progress * big_item * 12.0;
        // If post-residual would be tiny waste, fresh bin is bad; if item is huge
        // and would leave awkward residue elsewhere, fresh bin ok.
        if post_residual == 0 {
            score -= 15.0; // perfect fit anywhere is great, but fresh bin perfect fit is fine
        }
    }

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals more aggressively as stream progresses.
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth non-linear bonus.
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: favor bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 15.0 * (1.0 - diff).powi(3) * (0.5 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.6 + 0.4 * progress);
    }

    // Slight preference for consolidating into fewer bins early on.
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: penalize bins far from the mean residual.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make empty bins moderately attractive only when
    // no good fit exists (large post_residual in all fitting bins).
    if bin_residual == bin_capacity {
        score = pr as f64 + 20.0 * (1.0 - progress) + 10.0 * norm_pr * norm_pr;
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes: reward residuals that are "usable" (multiples of common item classes)
    let pr = post_residual;
    let class_bonus = match pr {
        0 => 30.0,                    // perfect fit, best possible
        1..=9 => 12.0,                // tiny dead space, nearly perfect
        10..=19 => 20.0,              // fits smallest class (10..19)
        20..=24 => 15.0,
        25..=49 => 10.0,              // medium class fits
        50..=79 => 6.0,               // large class fits
        _ => 0.0,                     // >80 residual: anything fits
    };
    score -= class_bonus;

    // Modulo-10 harmonic alignment of post_residual with next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u64 >= next_item_size as u64 {
            // lookahead fits: reward proportionally to tightness
            let tight = 1.0 - (post - nxt) / cap;
            score -= 8.0 * tight;
        } else {
            // lookahead will not fit here: penalize
            score += 5.0 + (nxt - post) / cap * 10.0;
        }
        // harmonic residue coupling: residual mod 10 near next item mod 10
        let rmod = (pr % 10) as f64;
        let nmod = (next_item_size % 10) as f64;
        if rmod <= nmod {
            score -= 3.0 * (1.0 - (nmod - rmod) / 10.0);
        } else {
            score += 2.0 * (rmod - nmod) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize fragmenting a bin that still has large usable residual when many bins open
    if post > 60.0 && open_bins_count > 3 {
        score += 4.0;
    }

    // Progress-scaled mild preference for filling bins tighter later in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post / cap);

    // New-bin candidate: neutral-ish baseline, penalize opening unless current fit is bad
    if bin_residual == bin_capacity {
        score += 18.0;
        // but if no open bin fits tightly, allow new bin
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Tie-break toward bins below mean residual (filling emptier bins less, tighter bins more)
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post residual (tightest fit).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals that are too small to be useful are heavily punished.
    // Since item sizes are unknown (1..100), treat gaps below a soft threshold as increasingly wasted.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        let depth = (dead_threshold - post_residual as f64) / dead_threshold;
        score += 30.0 * depth * depth; // quadratic penalty in the "unusable" zone
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling most of the bin (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill * fill;

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 40.0; // chain fit: item + next item perfectly fill the bin
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: mild penalty, worse if gap is tiny.
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, consolidate into existing bins rather than spreading.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: if this bin's residual is far below the mean, it's already
    // fragmented; prefer bins whose residual is near the mean (keeps others flexible).
    let res = bin_residual as f64;
    let dev = (res - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate calibration: an empty bin has residual == capacity. It should only win
    // when no open bin offers a decent fit. Give it a moderate baseline score that tight fits beat.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * progress; // later in the stream, slightly more reluctant to open bins
    }

    // Late-stream consolidation: as the stream progresses, tighten preference for high-fill bins.
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement is ideal — heavily favor it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this one: good chaining.
            score -= 0.6 * (next_item_size as f64);
            // Penalize large leftover after the hypothetical next placement.
            let residual_after_next = post_residual as f64 - next_item_size as f64;
            score += 0.4 * residual_after_next;
        } else {
            // Next item will NOT fit here: leftover is likely dead space.
            let waste = post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If no open bin fits, opening new bin is necessary — soften penalty.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in stream with many open bins, prefer consolidating.
        if open_bins_count > 5 {
            score += 20.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers are heavily favored.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate unless residuals are all large (fragmented state)
    // or this bin would leave an awkward residual the next item cannot use.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bin when existing bins are highly fragmented and many are open.
        let new_bin_bonus = 12.0 * fragmentation / bin_capacity as f64
            + 4.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0)
            + 6.0 * progress;
        score -= new_bin_bonus;
    } else {
        // Penalize placing into an open bin if the leftover dead space is "unusable"
        // relative to the next item: residual > 0 but smaller than next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
        // Reward when post-residual exactly accommodates the next item (chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0;
        }
        // Mild penalty when this bin is much emptier than average (save big bins).
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 5.0;
        }
    }

    // Early stream: be slightly conservative, favor filling fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: residual quality worsens quadratically with stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (2.0 + 6.0 * progress);

    // Penalize wasting a near-full bin when a smaller item could use it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 3.0 * (1.0 - pr / nxt) * (0.5 + progress);
        } else {
            score -= 2.0 * (1.0 - pr / nxt);
        }
    }

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins early, allow it late when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
    }

    // Coupling with mean residual: prefer bins deviating below mean (tighter bins)
    score += 1.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = pr / eighth; // 0..=8 harmonic band

    // Reward tight fits strongly (low post residual classes).
    match class {
        0 => score -= 60.0,
        1 => score -= 35.0,
        2 => score -= 18.0,
        3 => score -= 6.0,
        4 => score -= 2.0,
        _ => {}
    }

    // Penalize dead space that no typical item (1..=100) can use:
    // residuals of 1..=9 are nearly unusable.
    if pr > 0 && pr < 10 {
        score += 45.0;
    }

    // Modulo coupling: residual divisible by small sizes is reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual; evaluate chain
            let chain_res = pr - next_item_size;
            if chain_res < 10 {
                score -= 15.0;
            } else {
                score -= (chain_res as f64) * 0.15;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large waste
            score += (pr as f64) * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * (item_size as f64);
    }

    // New-bin candidate handling: empty bin gets a mild default score;
    // encourage opening a new bin only when all fits are poor.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; scale slightly with stream progress
        score = cap * 0.5 + (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        if fitting_bins_count == 1 {
            // an existing bin can take it with a decent fit; discourage new bin
            score += 30.0;
        }
        if post_residual == 0 {
            score -= 10.0; // never happens for empty bin but safe
        }
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 0.5 * (open_bins_count.min(20) as f64);
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // balances the pool.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fills (waste <= 5) strongly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Tightness ratio: fraction of the bin consumed by this placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Dead space relative to mean residual: placing into a bin whose residual
    // far exceeds the item leaves a large hole; penalize mismatch.
    let mismatch = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 12.0 * mismatch;

    // Open-bin pressure: with many open bins, prefer closing bins out
    // (reward filling existing bins); with few bins, opening is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 6.0 * pressure * (1.0 - fill);
    score -= 8.0 * pressure * fill * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post-residual,
    // this is a great chain placement -> reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 18.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // next item won't fit here; residual likely dead
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate: empty bin should only win when placement elsewhere
    // would create severe dead space. Penalize opening a bin mildly, scaled
    // by how bad the best alternative residual would be.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * mean_residual;
        if next_item_size > 0 && item_size >= 60 {
            score -= 15.0; // large items: fresh bins are fine
        }
    }

    // Global waste pressure: keep total residual spread tight.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus for tight packing.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (chain packing), penalize near-misses.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0;
        } else {
            score += diff as f64 * 0.5;
        }
        // If next item fits exactly in current residual, prefer leaving that room.
        if next_item_size as u32 <= bin_residual && (bin_residual as i64 - next_item_size as i64) == item_size as i64 {
            score -= 200.0;
        }
