    // Penalize small unusable dead space relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.3;
    } else {
        score -= (post_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But allow opening a fresh bin if no good fit exists (post_residual large gap).
        if post_residual as f64 > 40.0 && next_item_size as f64 > post_residual as f64 {
            score -= 350.0;
        }
    }

    // Mild stream-progression pressure: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
