    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 40.0 * poly;
    // reward tight fits strongly
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // lookahead: if next item fits post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    }
    // last chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // penalize many open bins slightly to encourage consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;
    // deviation from mean residual
    score += 0.2 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (C/8 bands)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor() as i32; // 0..7

    // Dead-space penalty: residuals in (0, 10) are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    if next_fits {
        // Harmonic bonus scaled by how "clean" the leftover class is
        score -= 10.0 + (7 - class.min(7)) as f64 * 2.0;
    } else if next_item_size > 0 {
        // Penalize leaving residue that cannot host the next item,
        // worse when residue is small (dead space)
        score += (post_residual.min(30)) as f64 * 0.4;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * (mean_residual / cap);
        score += 60.0 - crowding * 15.0;
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Mildly reward filling existing bins tighter than mean residual
        if (pr < mean_residual) {
            score -= 5.0;
        }
    }

    // Modulo-16 harmonic texture on post_residual: multiples of 16 align with common size classes
    if post_residual % 16 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible future item (size 1) are never truly "dead", but
    // residuals in a narrow band below the typical item size are hard to
    // reuse. Penalize small-but-nonzero gaps sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual as i32) as f64;
    }
    // Gaps that can't fit the lookahead item are less useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but relax late in the stream when closing bins out matters less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 - 0.7 * progress);

    // Mean residual coupling: prefer bins already below average residual
    // (filling the emptiest bins first keeps others available for big items).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits,
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate: make it unattractive unless all fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // But allow opening a new bin late in the stream to keep clean bins.
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in stream, prefer tight packing; late, be flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for a perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 20.0 * (1.0 - progress);
    }
    // Partial match: next item fits with small leftover
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - after_next / bin_capacity as f64);
    }
    // Penalize post_residual that cannot fit the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Reward tight fits: small post_residual relative to item size
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Compare against mean residual: prefer bins that stay near the mean (balanced packing)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when item is large or stream is late
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / 100.0) * 30.0;
        score -= 10.0 + large_item_bonus + 25.0 * progress;
    }

    // Penalize leaving very small unusable residuals (< 10 typical minimum)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: strongly discount small post_residual (non-linear).
    let pr = post_residual as f64;
    score -= 60.0 * (-pr / 12.0).exp();

    // Penalize unusable dead space: residuals too small for the smallest item (1)
    // are pure waste; larger residuals keep future flexibility.
    if post_residual > 0 {
        // waste penalty grows as residual becomes hard to use relative to mean residual
        let usable = (post_residual as f64) / (mean_residual.max(1.0));
        score += 20.0 * (1.0 - usable.min(1.0));
    } else {
        // perfect fill: huge reward
        score -= 100.0;
    }

    // Lookahead (k=2): if the next item fits into the post_residual,
    // reward keeping this residual; otherwise penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-fit bonus, stronger early in stream when future matters more
            score -= 35.0 * (1.0 - 0.5 * progress);
        } else if post_residual > 0 {
            // residual wasted relative to the known next item
            score += 10.0 + 15.0 * progress;
        }
    } else {
        // last item: only tightness matters
        score -= 20.0;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with number of open bins
        // (prefer reusing) and with progress (consolidate late in stream).
        let mut new_bin_score = 55.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
        new_bin_score += 40.0 * progress;

        // If the item fills a new bin tightly, opening is attractive.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.85 {
            new_bin_score -= 60.0;
        }

        // If existing bins are fragmented (high mean residual), a fresh bin is fine.
        new_bin_score -= 0.3 * mean_residual.max(0.0);

        // If next item is large and would fit well in a fresh bin, encourage opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 10.0;
        }

        score = new_bin_score;
    }

    // Mild preference for fuller bins among candidates (best-fit flavor).
    score -= 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Tight fit reward: strongly favor small post residuals (quartic decay)
    score -= 12.0 * (1.0 - x).powi(4);

    // Penalize large unusable gaps that no typical item can fill
    score += 4.0 * x * x * (1.0 - progress);

    // Stream-progress coupling: later in stream, tighten preference for tight fits
    score -= 6.0 * progress * (1.0 - x).powi(2);

    // If item exactly fills bin, big reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits into the resulting residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 2.0 * (1.0 - next_item_size as f64 / cap) * x;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild penalty when many bins are open and residual is wasteful
    score += (open_bins_count as f64).ln().max(0.0) * x * 0.5;

    // Mean-residual coupling: if this bin is below mean residual (tighter), favor it
    score -= 2.0 * (mean_residual - pr) / cap;

    // New-bin candidate: prefer keeping it closed unless current bins are very fragmented
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward near-exact fits (post_residual in the smallest harmonic classes).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= eighth {
        score -= 30.0 + 20.0 * (1.0 - pr / (eighth as f64));
    } else if post_residual <= quarter {
        score -= 10.0;
    } else if post_residual > bin_capacity / 2 {
        // Large dead space: half-capacity class or worse is very undesirable.
        score += 15.0 + 0.1 * (pr - cap / 2.0);
    }

    // Modular structure on post_residual: multiples of common item granularity (5,10) are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits the post residual, this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 0.35 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer tighter bins: closeness of item to bin_residual (best-fit sharpening).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // New-bin candidate handling: opening a fresh bin is only attractive early in the stream
    // or when many bins are open with poor residual structure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a new bin grows with stream progress (amortization).
        score += 40.0 + 60.0 * progress;
        // If existing fitting bins are few and residuals are fragmented, new bin is cheaper.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        if mean_residual < 15.0 && open_bins_count > 3 {
            score -= 15.0;
        }
    } else {
        // Slight preference to keep bin count low when few bins are open.
        score += (open_bins_count as f64).ln() * 1.5;
    }

    // Mean-residual context: if this bin's residual is far below the mean, it is a good fit target.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Small deterministic tie-break via harmonic class of item_size.
    score += match item_size % 4 {
        0 => -0.5,
        1 => 0.5,
        2 => 0.0,
        _ => -0.25,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Small leftover that could still host a lookahead item: reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Leftover slightly below next item: mild penalty (near-miss gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless
    // this placement leaves a well-usable residual.
    let bin_pressure = open_bins_count as f64 / 8.0;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins whose residual tracks the mean
    // (keeps a balanced pool of medium gaps usable for future items).
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Prefer tighter fits overall (large item in small residual).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin offers a good fit; otherwise keep them penalized.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 12.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward (perfect packing leaves zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover after two placements.
            let two_step_left = post_residual - next_item_size;
            score += two_step_left as f64 * 0.6;
            if two_step_left == 0 {
                score -= 250.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Compare against mean residual: bins with above-mean residual are less scarce;
    // prefer consuming from bins with small residuals (below mean) first.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Mild preference to fill existing bins as stream progresses (reduce bin count pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Default: new bin is slightly worse than a decent existing fit.
        score += 10.0;
        // But if open bins are all nearly full (high mean residual pressure), a new bin is fine.
        if mean_residual > 0.0 && mean_residual < item_size as f64 * 1.2 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing (min size 1..100 stream) can reuse efficiently.
    if post_residual > 0 && post_residual < item_size {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving a medium hole.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, residual quality matters more than bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0 * open_bins_count as f64;

    // Global state: if mean residual across open bins is high, opening/using
    // fresh space is cheap; if mean residual is low, conserve tight bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when no open bin fits well (poor fits into open bins
    // would strand large residuals).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            let best_possible = 1.0 - (item_size as f64 / bin_capacity as f64);
            (best_possible - 0.1).max(0.0)
        };
        score += 20.0 - 15.0 * desperation;
        // Prefer deferring new bins early, allow them later.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and fill ratio
    let pr = post_residual as f64 / bin_capacity as f64;
    let fill = 1.0 - pr;

    // Non-linear waste shaping: quadratic penalty on residual, softened by fill
    let waste_shape = pr * pr * (2.0 - fill);
    score += 6.0 * waste_shape;

    // Smooth progress coupling: later in stream, prefer tighter fits (cubic ramp)
    let tightness = 1.0 - progress * progress * progress;
    score += 10.0 * pr * tightness;

    // Reward filling a bin nearly full (smooth exponential bonus)
    score -= 8.0 * (-(1.0 - fill) * 4.0).exp();

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let fit_next = (1.0 - gap / bin_capacity as f64).max(0.0);
        score -= 7.0 * fit_next * fit_next;
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 15.0 * fill;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean residual context: if this bin is far below mean residual (very full), reward
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate handling: penalize opening a new bin, more so early/mid stream
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        score += 18.0 + 4.0 * open_pressure * (1.0 - progress * 0.5);
        // But if no open bin fits well (large post_residual elsewhere), soften:
        // item_size small relative to capacity -> new bin less wasteful later
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * item_frac * item_frac * progress;
    }

    // Mild preference for consolidating among many open bins
    score += 0.05 * open_bins_count as f64 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small residues are golden.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Class the residue into harmonic bands via integer division on capacity fractions.
    // residue <= 10 : nearly full bin, excellent.
    if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    } else if post_residual <= 30 {
        score -= 25.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        // Large leftover: dead-space penalty, modulated by how "usable" the residue is.
        // Residues that are multiples of common item sizes (10,20,25,50) remain usable.
        let usable = post_residual % 10 == 0 || post_residual % 25 == 0;
        if !usable {
            score += 15.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Harmonic bonus: next item leaves a small residue again.
            score -= 80.0 * (1.0 - slack / cap).max(0.0);
            // Penalize if next item would leave an awkward residue (mod classes).
            if slack > 0.0 && (post_residual - next_item_size) % 10 != 0 && slack < 10.0 {
                score += 20.0;
            }
        } else {
            // Next item won't fit here: mild penalty, unless this bin is nearly full anyway.
            if post_residual > 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin gives a tight fit.
        // Base penalty keeps it behind tight fits in open bins.
        score += 60.0;
        // Early in stream, slightly discourage hoarding bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, discourage new bin.
        score += 0.5 * mean_residual;
        // But if the item is huge (>= 50) and few bins fit it, new bin is safer.
        if item_size >= 50 && fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    // Mild preference for filling bins with more open bins (consolidation pressure).
    score += 0.3 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual gap is "dead" if it's too small to hold even the smallest plausible item.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Perfect fit or near-perfect fit: strong reward.
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // Small gap that likely becomes dead space: strong penalty.
        score += 25.0;
    }

    // Non-linear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Reward using bins that are already mostly full (tight packing).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and favor consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    score += 3.0 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item can fit into the post residual,
    // reward this placement (keeps chains of placements going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving large gaps
        // that won't be usable by the next item.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference toward bins below mean residual (balance residuals,
    // keeping mid-size gaps available for mid-size future items).
    score += 4.0 * (post_residual as f64 - mean_residual).signum()
        * ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin wastes capacity when
    // open bins can still absorb the item. Penalize the empty-bin candidate
    // unless it's early in the stream or no real bin fits well.
    if bin_residual == bin_capacity {
        let early = progress < 0.15;
        if open_bins_count > 0 && !early {
            score += 35.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear pressure.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            // Perfect chained fit: strongly favor this bin.
            score -= 60.0;
        } else if next_item_size as u32 <= post_residual {
            // Next item fits: reward proportional to how well it matches.
            let match_quality = 1.0 - ((pr - nx) / cap);
            score -= 25.0 * match_quality;
        } else {
            // Next item does NOT fit this residual: penalize by the gap size.
            let gap = (next_item_size as u32 - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: just minimize post_residual waste.
        score += 0.2 * pr;
    }

    // Relative to mean residual: bins with residual far above mean waste potential.
    score += 0.15 * (pr - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when many bins are already open
        // and the stream is late (fewer chances to consolidate).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 0.2 * item_size as f64;
    }

    // Early stream: slightly favor consolidating into fewer bins.
    if open_bins_count > 8 {
        score += 1.5 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= (1.0 - tightness) * 60.0;
    }

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 80.0; // small unusable sliver -> good to create now
    }
    if post_residual >= 10 && post_residual < item_size.min(80) {
        score -= 25.0; // residual smaller than plausible next items
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with decent fits.
        score += 120.0;
        // If current item is large relative to mean residual, opening fresh is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 100.0;
        // Late in the stream, prefer closing out bins (fewer open bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 40.0;
        // If many open bins with large mean residual, reuse them instead.
        score += (mean_residual / bin_capacity as f64) * 60.0;
        score += open_bins_count as f64 * 3.0;
    }

    // Lookahead: reward placements that still allow the next item to fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0;
            // Exact chain fit is excellent.
            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just minimize waste.
        score -= 30.0;
    }

    // Mild preference for filling bins with larger residual first
    // (keeps tight bins available for small items).
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.1;

    // Coupling: if this bin's residual is far below mean, it's a "small" bin —
    // prefer using it before it becomes dead space.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = x * x * (1.0 - progress) - x * progress * (1.0 - x);
    score += 12.0 * coupling * cap / 100.0;

    // Reward tight fits, scaled smoothly by progress
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual, smoothly
    let dev = pr - mean_residual;
    score += 0.05 * dev * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - x);
    }

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0 * (next_item_size as f64 / cap);
    }

    // Slight preference to fill existing bins as stream matures
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate penalty unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (1.0 - progress) - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted if nothing more fits

    // Dead-space classes: residuals that few item sizes can use are penalized
    // Items are 1..=100 unknown, but small residuals (< next_item_size) are dead until refill.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - frac); // dead space relative to lookahead
    }

    // Modulo-arithmetc harmonic classes on post_residual
    let class = post_residual % 10;
    match class {
        0 => score -= 8.0,          // exact decade: highly reusable
        1 | 9 => score += 3.0,      // off-by-one residuals are awkward
        2 | 8 => score -= 1.0,
        5 => score -= 4.0,          // half-decade residuals pair with mid items
        _ => {}
    }

    // Integer-division thresholds: reward residuals that can host common size bands
    if post_residual >= 50 { score -= 6.0; }
    else if post_residual >= 25 { score -= 3.0; }
    else if post_residual >= 10 { score -= 1.0; }
    else if post_residual > 0 { score += 4.0; } // tiny sliver

    // Perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: baseline cost, adjusted by stream position and bin count
    if bin_residual == bin_capacity {
        score = cap * 0.9;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress; // later in stream, prefer reusing bins more
        if open_bins_count > 0 {
            // opening new bin is attractive if mean residual is small (all bins tight)
            score -= (mean_residual / cap).max(0.0) * 20.0;
        } else {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 5.0;
        }
    }

    // Coupling: prefer bins whose residual is close to mean (balance load)
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 5.0;

    // Lookahead harmony: if next item would fit exactly in post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold anything useful
    // (below the minimum plausible item footprint) are punished hard.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on tiny-but-not-dead gaps: encourage near-exact fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Reward tight fits (small post_residual) relative to mean residual pressure.
    score -= 10.0 / (1.0 + post_residual as f64);

    // Open-bin pressure: discourage spreading into many bins unless the fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + 2.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin for a forced fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in leftover: mild penalty scaled by leftover smallness.
        score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
    }

    // Mean-residual coupling: placing into a bin with residual far below mean is good
    // (concentrating waste), placing into a large-residual bin wastes usable space.
    if bin_residual as f64 > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate calibration: an empty bin is a safe default but should only win
    // when open bins would create large unusable gaps. Give it a mid-range baseline score
    // equal to its residual (bin_capacity), adjusted by open-bin pressure.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: keep it competitive but not dominant for typical fits.
        score = bin_capacity as f64 * 0.85 + pressure;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item chains into this bin.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize, scaled by dead gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare residual against mean residual: prefer using fuller bins.
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer not spreading across many bins early; later, consolidation matters more.
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    // New-bin candidate: only attractive when no open bin fits well
    // (high post_residual otherwise makes it unattractive; give it a mild base).
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
        // If next item is huge and nothing fits, opening fresh is fine.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity wasted by this placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // Perfect fit bonus: strongly reward exact or near-exact closure
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: penalize leaving a residual that barely fails to fit the next item
    // (dead space the next item almost fits), and reward residuals that fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can host the next item: reward proportional to tightness
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // near-miss dead space: penalize more the closer next_item_size is
            let miss = (post_residual as f64) / (next_item_size as f64);
            if miss > 0.7 {
                score += 10.0 * miss;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Scarcity pressure: when few bins can fit the item, prefer reusing existing bins
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= 6.0 * scarcity;
    }

    // New-bin candidate handling: only open a new bin when existing bins are
    // badly fragmented (mean residual small relative to item) or bin count is low.
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / bin_capacity as f64;
        // Penalize new bins generally (best-fit default), scaled by how much
        // space remains usable across open bins.
        let mut new_bin_score = 30.0 + 40.0 * mean_tight;
        // Early in the stream, opening bins is cheap and keeps options open
        new_bin_score -= 20.0 * (1.0 - progress);
        // If many bins are open and fragmented, new bin becomes attractive
        if open_bins_count > 3 && mean_tight < (item_size as f64 / bin_capacity as f64) {
            new_bin_score -= 25.0;
        }
        // Never open a new bin if a perfect/near fit exists elsewhere
        if post_residual == 0 {
            new_bin_score += 100.0;
        }
        score = new_bin_score;
    } else {
        // Slight preference for fuller bins among open candidates (tighter packing)
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
        // Mild penalty for very fragmented global state when this placement
        // leaves a small awkward residual
        if post_residual > 0 && post_residual < 10 {
            score += 2.0 * (mean_residual / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, large residuals are acceptable (bins stay flexible);
    // late in the stream, residual waste is increasingly penalized.
    let waste_penalty = (pr / cap).powi(2) * (1.0 + 3.0 * progress * progress);
    score += 40.0 * waste_penalty;

    // Cubic term: extremely small residuals are great (near-perfect fit).
    let tight_fit = (1.0 - pr / cap).powi(3);
    score -= 30.0 * tight_fit;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - slack).powi(2);
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are badly fragmented (high mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 15.0 + 60.0 * (1.0 - fragmentation).powi(2);
        // Late in stream, opening fresh bins is less attractive.
        score += 30.0 * progress;
    } else {
        // Prefer bins whose residual is below mean (consolidate waste).
        let rel = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * rel;
    }

    // Mild penalty for proliferating bins early on.
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "harmonic"
    // (divisible by common item sizes) are more reusable.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0f64;
    for &d in &[10u32, 20, 25, 50] {
        if pr >= d && pr % d == 0 {
            harmonic_bonus += 1.0;
        }
    }
    // Perfect fills are ideal.
    if pr == 0 {
        harmonic_bonus += 3.0;
    }
    score -= harmonic_bonus * 2.5;

    // Penalize tiny dead-space residues that no typical item can use.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if pr >= next_item_size {
            if pr % next_item_size == 0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Post-residual too small for next item: dead space penalty scaled
            // by how much is wasted relative to next item.
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = mean_residual / bin_capacity as f64;
        // Open new bins more readily when open bins are fragmented (low mean residual)
        // and late in the stream.
        score += 12.0 - 10.0 * (1.0 - tightness) - 4.0 * progress;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter existing bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 1.0;

    // Modulo-class tiebreak on bin_residual: bins whose residual shares a class
    // with the item pack more cleanly (item + residue sums stay harmonic).
    if bin_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // "Unusable" gap: smaller than the minimum plausible item size.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0 * (1.0 - post_residual as f64 / 20.0);
        } else {
            // Larger residual space is reusable; mild penalty scaled by size.
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tight-fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 20.0 * (fill_ratio - 0.8) * 5.0;
    }

    // Dead-space coupling: penalize if post_residual cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps bin useful for lookahead
        } else if post_residual > 0 {
            score += 12.0; // lookahead can't use the leftover gap
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins with residual below the current mean (keeps residual spread tight).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when all open fits are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: nothing else fits
        } else {
            // Opening a new bin only wins if the best existing fit leaves a tiny gap.
            score = 10.0 + post_residual as f64 + 2.0 * open_bins_count as f64;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the bin -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits with leftover; penalize by leftover smallness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item does NOT fit: dead space risk, penalize proportionally
            score += 8.0 + diff / (bin_capacity as f64 / 4.0);
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0;
    }

    // Compare post_residual against mean residual: avoid leaving much more than average
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid wasting near-full bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is huge, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 12.0;
        }
    }

    // mild preference for tighter existing fits overall
    score += 0.1 * (bin_residual - item_size) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize large dead space, but only when it is truly unusable.
    // Dead space is "wasted" if no typical item (>=1) can realistically pair with it;
    // treat residuals < 10 as near-dead, residuals >= 10 as partially reusable.
    let dead = post_residual as f64;
    if dead < 10.0 {
        score -= 25.0 * (1.0 - dead / 10.0); // tiny residuals are excellent: hard bonus
    } else {
        score += 0.15 * (dead - 10.0); // penalize growing slack mildly
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect_next = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + perfect_next);
    } else if next_item_size > post_residual {
        // Next item won't fit here regardless; slight penalty for hoarding space
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global state coupling: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; when few are open, be less picky.
    let crowding = (open_bins_count as f64).ln_1p();
    score += 3.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — reward using it up further.
    let dev = mean_residual - post_residual as f64;
    score -= 0.10 * dev.clamp(-50.0, 50.0);

    // New-bin candidate handling: bin_residual == bin_capacity means a fresh bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, or when nothing fits well elsewhere,
        // or when the current item leaves a nice residual for the lookahead item.
        let early = progress < 0.3;
        let no_alternative = fitting_bins_count == 0;
        let nice_pair = next_item_size > 0 && next_item_size <= post_residual;
        if !(early || no_alternative || nice_pair) {
            score += 60.0; // discourage opening new bins mid-stream without reason
        } else {
            score -= 5.0;
        }
    }

    // Mild time-horizon term: as the stream nears its end, tighten packing
    // (waste matters more since fewer chances to amortize it).
    score -= 10.0 * progress * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap; // 0..1
    let t = progress;
    let coupling = pr_norm * pr_norm * (1.0 - t) + pr_norm * t * t;
    score += 40.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tight = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 25.0 * tight * (0.5 + t);

    // Penalize large dead space non-linearly
    score += 15.0 * pr_norm * pr_norm * pr_norm;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 * (1.0 - t);
    } else if next_item_size > 0 {
        score += 8.0 * t;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight preference to keep mean residual balanced across bins
    score += 0.3 * (mean_residual - pr).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * t;
    }

    // Mild penalty for many open bins
    score += 0.5 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes.
    // Class by integer division thresholds on post_residual (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows super-linearly for tiny residuals that are
    // unlikely to fit future items (harmonic class: residual mod 10).
    let class = post_residual % 10;
    if class != 0 {
        score += (10 - class) as f64 * 0.35; // non-multiple-of-10 residuals waste space
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward residuals in ranges that commonly fit item sizes (harmonic bands).
    if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0;
    } else if post_residual > 20 && post_residual <= 40 {
        score -= 3.0;
    } else if post_residual > 80 {
        score += 4.0; // nearly-empty bin placement is weak
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // reward proportional to how snugly next item fits after this placement
            let two_step = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - two_step / cap);
        } else {
            // next item won't fit here; penalize proportional to leftover
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let base = 12.0 + 2.0 * open;
        // discount new bin if mean residual across open bins is large enough
        let mean_fit = if item_size as f64 <= mean_residual { 1.0 } else { 0.0 };
        score = base - if mean_fit == 1.0 { 6.0 } else { 0.0 }
            + pr * 0.15
            - (step_index as f64 / total_items.max(1) as f64) * 3.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10) are worthless forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins with below-average residual (more filled bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item can't use the gap: penalize proportionally to wasted space
            score += 0.2 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // New-bin candidate: baseline cost of opening a bin, modulated by stream progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: opening bins is cheap; late stream: prefer reusing.
        score = 30.0 + 40.0 * progress;
        // But if no open bin fits well, allow opening.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact/near-exact chaining of the next item into this bin.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_gap.min(60.0);
        } else {
            // Penalize residuals that are too small to be useful for the next item.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean coupling: bins far below mean residual are "wasted" fills;
    // bins near the mean keep the bin set balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Tight fits are excellent: big reward when item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: only attractive when the fit into open bins is poor
    // (large dead space) or when the open-bin set is getting fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open or
        // when the current placement would leave large unusable residue.
        let mut new_bin_cost = 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin perfectly chains the next item too.
            new_bin_cost -= 20.0;
        }
        if open_bins_count > 0 {
            new_bin_cost -= (open_bins_count as f64).ln() * 3.0;
        }
        score += new_bin_cost;
    }

    // Stream progression: early on, be slightly conservative about wasting bins;
    // later, prioritize tight packing over opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small post-residuals (dead space < smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into this bin's post-residual,
    // reward heavily; if next item cannot fit post-residual but fits elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large relative to mean residual,
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 35.0; // base cost of opening a new bin
        score -= 30.0 * pressure; // worth it when open bins are mostly full
        score -= 20.0 * large_item; // worth it for big items with poor fits available
        if fitting_bins_count > 0 && fit_ratio > 0.9 {
            score += 60.0; // never open a bin when a near-perfect fit exists
        }
    }

    // Mild late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (mean_residual / bin_capacity as f64);

    // Slight preference for bins below mean residual (balance load, keep flexibility).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (favor spreading); late, waste is expensive.
    let waste_penalty = pr * pr / cap * (0.5 + 2.0 * progress * progress);
    score += waste_penalty;

    // Reward near-perfect fits, stronger as the stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize bins that leave a residual too small for typical future items,
    // unless it is essentially zero.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (1.0 + progress);
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // otherwise penalize slightly, scaled by how much space is stranded.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 5.0 + 3.0 * progress;
        } else {
            score += 0.05 * (ni - pr) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // New-bin candidate handling: opening a bin is attractive when open bins
    // are collectively full (mean residual low) and early in the stream,
    // but penalized when it would strand large residuals elsewhere.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64).ln_1p();
        score -= 8.0 * mean_fill * (1.0 - progress) - 2.0 * openness * progress;
        // Discard new bins late in the stream unless nothing fits well.
        score += 20.0 * progress * progress;
    }

    // Mild preference for balancing residuals across bins.
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead-space" classes are rewarded (lowered score).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Integer-division thresholds: post_residual in [0..10) is nearly perfect.
    if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 12.0;
    } else if post_residual < 35 {
        score -= 4.0;
    }

    // Modulo classes: leftovers divisible by small integers are more likely
    // reusable by future items (harmonic sizes 10/20/25/50).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Penalize mid-range dead zones (hard to fill later): 35..65 residual.
    if post_residual >= 35 && post_residual <= 65 {
        score += 10.0 * (1.0 - (pr - 35.0) / 30.0).abs().max(0.0);
    }

    // Lookahead coupling: if next item fits the post_residual exactly or
    // within a small tolerance, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 20.0;
            } else {
                score -= (10.0 / gap as f64) * 5.0;
            }
        } else {
            // Next item won't fit here; slight penalty scaled by overshoot class.
            let over = next_item_size - post_residual;
            score += (over % 10) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // unless the resulting residual is a hopeless dead zone.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 25 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has large base score via
    // post_residual == capacity; only allow it when open bins are all poor fits
    // (high mean residual spread) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0
            - 15.0 * (1.0 - progress)
            - (mean_residual / cap).min(1.0) * 20.0;
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 30.0; // big next item benefits from a fresh bin
        }
    }

    // Mild tie-break toward bins already partially filled relative to mean.
    score += ((bin_residual as f64 - mean_residual) / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals that are too small for any
    // plausible future item (1..=100) are pure waste; penalize heavily.
    // A residual below ~10 is nearly unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead space becomes more costly later in the stream (less time to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * progress;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.6 * open_bins_count as f64;

    // If this bin is the only one that can fit the item, strongly prefer it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
