    // If next item is large and would not fit here, mild penalty for wasting
    // the chance to place it elsewhere.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Mean residual coupling: bins far below mean residual are emptier than
    // average; slightly deprioritize them to keep fills balanced.
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: make the empty bin attractive only when nothing fits
    // well. Baseline moderate score; dead-space penalties on open bins push
    // selection toward a new bin when open bins would create waste.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    score
