                // next item still fits afterwards: mild reward scaled by closeness
                score -= (next_item_size as f64 / post_residual as f64) * 40.0;
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable;
    // dumping an item into a loose bin wastes flexibility.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.8;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * open_bins_count as f64 * 0.1;

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin if current bin would leave a large unusable fragment.
        if post_residual > 0 && post_residual < 10 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable slivers
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            let over = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * over;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Few fitting bins -> scarcity; prefer consolidating into scarce capacity.
    if fitting_bins_count >= 2 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are crowded (low mean residual) or none fit well.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // Penalize new bins when open bins still have room on average.
        score += 15.0 + 30.0 * crowding;
        // But if this is a large item and open bins are tight, ease the penalty.
        if item_size as f64 > bin_capacity as f64 * (1.0 - crowding) {
            score -= 25.0;
        }
        // Late in the stream, discourage opening new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Slight preference for bins already below mean residual (balance avoidance).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    // Non-linear residual shaping: convex penalty for mid-range waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * (1.0 - waste_frac) * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
