    // more reusable (typical item sizes align to decade classes).
    let pr = post_residual;
    let class_bonus = match pr % 10 {
        0 => 18.0,
        1 | 9 => 2.0,
        2 | 8 => 4.0,
        3 | 7 => 6.0,
        4 | 6 => 8.0,
        5 => 10.0,
        _ => 0.0,
