    score -= class_bonus;

    // Small post-residuals are dead space: penalize the "almost full but
    // wasted" zone (1..=9) to prefer exact or generously usable fits.
    if pr > 0 && pr <= 9 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a perfect chaining opportunity.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // fraction of next item absorbed by this residual
            let absorb = next_item_size as f64 / pr as f64;
            score -= 12.0 * absorb;
            // harmonic bonus if post_residual is a multiple of next item
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual at all: mild penalty
            // scaled by how much residual would be stranded
            score += 4.0 * ((pr as f64) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        // base cost of a fresh bin
        score += 45.0;
        // large items deserve fresh bins
        score -= 55.0 * fill;
        // if open bins have plenty of slack, opening new is wasteful
        score += 0.6 * mean_residual;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins -> discourage more sprawl
        score += 2.0 * open_bins_count as f64;
    } else {
        // Tightness reward: filling a bin well is good.
        let tightness = 1.0 - (post_residual as f64) / cap;
        score -= 15.0 * tightness * tightness;
    }

    // Integer-division threshold: post_residual bucketed by quarters of
    // capacity — larger buckets get graded preference.
    let quarter = pr / (bin_capacity / 4).max(1);
    score -= 3.0 * quarter as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
