    }

    // Mild encouragement to keep bin count low early on
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residual is tiny elsewhere
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
