    // New-bin candidate handling: an empty bin has huge residual; make it costly
    // unless current fit is very poor or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized, but less when fits are bad.
        score = 200.0 - 30.0 * (1.0 - progress);
        if post_residual as f64 > bin_residual as f64 - item_size as f64 + 1.0 {
            // (defensive; normally post_residual == capacity - item here)
        }
        // If no open bin can fit (fitting_bins_count == 0 means only new bin offered),
        if fitting_bins_count == 0 {
            score = -50.0;
        }
    }

    // Mild preference for bins below mean residual (balance load) to keep many usable bins.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Slight preference for bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0 + 0.8 * (next_item_size - post_residual) as f64;
    }
    // Dead space relative to the smallest plausible item (size 1..100 unknown, use item_size as proxy scale)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are worthless
    }

    // Reward tight fits (perfect fills are gold).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    // Many fitting bins: prefer the one that best preserves flexibility (higher post_residual ok,
    // but add mild pressure to consolidate).
    if fitting_bins_count > 1 {
        score += 2.0 * fitting_bins_count as f64;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a laggard bin —
    // prefer filling it to normalize residuals.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.4 * (mean_residual - resid).min(50.0);
    } else {
        score += 0.3 * (resid - mean_residual).min(50.0);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual == bin_capacity - item_size;
        if fitting_bins_count == 0 || next_item_size == 0 {
            score -= 20.0; // no alternative or stream end: new bin is fine
        } else if post_residual < next_item_size {
            score -= 10.0; // fresh bin accommodates the next item
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64; // discourage needless new bins
        }
        let _ = good_fit_exists;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * 4.0).max(0.0) * (1.0 - tightness);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap == 0.0 {
            score -= 25.0; // perfect two-item packing chain
        } else if gap <= 5.0 {
            score -= 12.0 * (1.0 - gap / 5.0);
        } else if post_residual < next_item_size {
            // dead space the next item cannot use
            score += 0.5 * gap.min(20.0);
        }
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (compact bins), penalize dipping into roomy bins for small items.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere (large post_residual waste in existing bins is unlikely here,
    // so default cost keeps new bins slightly disfavored unless lookahead favors).
    if bin_residual == bin_capacity {
        score += 8.0;
        // If next item is huge and this item is small, fresh bin pairs well.
        if next_item_size >= item_size.saturating_mul(2) && item_size <= 30 {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate harder: reward using existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 {
        score += 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}
